var e=1,t={ts:{name:`TypeScript`,description:`Od prvih tipova do modelovanja API-ja i React komponenti.`},js:{name:`JavaScript`,description:`Jezik, asinhroni rad i ponašanje koje moraš da objasniš.`},react:{name:`React`,description:`State, Effects, identitet, renderovanje i savremene mogućnosti.`},web:{name:`Web osnove`,description:`HTML, CSS, pristupačnost, browser, mreža i bezbednost.`},stack:{name:`Biblioteke i podaci`,description:`Redux, Saga, Query, Router, Axios, forme, MUI i i18n.`},quality:{name:`Kvalitet i alati`,description:`Testovi, performanse, Git, CI i produkcioni dokazi.`},senior:{name:`Senior i team lead`,description:`Arhitektura, odluke, API ugovori, mentorstvo i odgovornost.`},ai:{name:`AI alati u radu`,description:`Codex i Claude Code: kontekst, provera, granice i samostalnost.`},vite:{name:`Vite i build alati`,description:`Razvojni server, build, env, resursi i pouzdana isporuka.`},cra:{name:`CRA i react-scripts`,description:`Legacy održavanje, skripte, ograničenja i promišljena migracija.`},node:{name:`Node.js osnove`,description:`Runtime, moduli, asinhroni I/O, greške, streamovi i održavanje servera.`},express:{name:`Express.js`,description:`Rute, middleware, validacija, greške i granice HTTP API-ja.`},sass:{name:`Sass / SCSS`,description:`Preprocesor, moduli, tokeni, nesting i stilovi koji se lako održavaju.`},less:{name:`Less`,description:`Promenljive, mixin-i, guard uslovi, računanje i granica između build-a i browsera.`},ui:{name:`UI biblioteke i Figma`,description:`MUI, Bootstrap, design tokens i predaja dizajna developeru.`},viz:{name:`Grafici i mape`,description:`Chart.js, pristupačni podaci i Google Maps integracija.`}},n=JSON.parse(`{"ts01":{"title":"Šta TypeScript zaista proverava?","prompt":"Server vrati podatak pogrešnog tipa. Da li ga TypeScript automatski zaustavlja u browseru?","why":"TypeScript proverava kod pre izvršavanja. Tip koji napišeš uz API odgovor nije provera stvarnog JSON-a.","pitfall":"as User menja ono što kompajler pretpostavlja; ne proverava podatak.","options":["Ne. Statički tipovi se uklanjaju; za spoljne podatke treba runtime provera.","Da, ako odgovor napišem kao Promise<User>.","Da, ako uključim strict.","Da, ako umesto type koristim interface."],"steps":["Kompajler vidi tvoj program i tipove dok razvijaš aplikaciju. Ne kontroliše šta će udaljeni server stvarno poslati sutra.","Ako server pošalje name: null umesto stringa, tek runtime provera može to da otkrije pre poziva name.toUpperCase()."],"remember":"Tip nije zaštitna ograda oko stvarnog JSON-a.","wrong":["Promise<User> opisuje očekivani rezultat, ali ne pregleda mrežni odgovor.","strict pojačava statičke provere; ne dodaje automatski validator u browser.","interface se takođe uklanja iz izvršnog JavaScript koda."]},"ts02":{"title":"Inference umesto previše anotacija","prompt":"Koji je tip promenljive posle ove deklaracije?","why":"Kod let count = 3, TypeScript obično proširi literal na number, jer se vrednost može menjati.","pitfall":"Nije potrebno pisati : number uz svaku očiglednu inicijalnu vrednost.","code":"let count = 3;","options":["number","Tip koji prihvata isključivo broj 3","any","string | number"],"steps":["Promenljiva je deklarisana sa let, pa može kasnije dobiti drugi broj. Zato je korisniji širi tip number nego samo vrednost 3.","Pokušaj count = \\"4\\" i dalje je greška: mogućnost promene vrednosti ne znači mogućnost promene na bilo koji tip."],"remember":"Inference izvodi tip; ne ukida proveru.","wrong":["Literalni tip 3 bi dozvolio samo tu vrednost. Za let se ovaj literal normalno proširuje.","Kompajler ima dovoljno podataka da izvede number; ne mora da koristi any.","U inicijalizaciji nema stringa ni eksplicitnog union ugovora."]},"ts03":{"title":"Tipizuj malu funkciju","prompt":"Napiši funkciju formatPrice koja prima cenu kao number i opcionu valutu kao string, sa podrazumevanom vrednošću RSD. Vraća string.","why":"Tipovi dokumentuju ulaz i izlaz. Podrazumevana vrednost rešava odsutan argument, ali ne proverava valjanost valute u poslovnom smislu.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"function formatPrice(amount: number, currency = \\"RSD\\"): string {\\n  return \`\${amount.toFixed(2)} \${currency}\`;\\n}","checks":["Parametar amount je number.","currency ima podrazumevanu vrednost ili se undefined obrađuje.","Povratna vrednost je string; validan je i inference."],"steps":["amount: number opisuje ulaz funkcije. currency = \\"RSD\\" daje i string inference i vrednost kada pozivalac izostavi argument.","toFixed vraća string, a template literal pravi konačni tekst. Povratni tip možeš napisati radi jasnog javnog ugovora."],"remember":"Tipizuj granicu funkcije; vrednosti obrađuje običan JavaScript.","wrong":[]},"ts04":{"title":"any ili unknown","prompt":"Primaš nepoznat podatak iz spoljnog sistema. Koji početni tip te primorava da proveriš vrednost pre upotrebe?","why":"unknown dopušta da primiš bilo koju vrednost, ali za operacije traži sužavanje tipa. any isključuje važne provere.","pitfall":"unknown sam po sebi nije validator. I dalje moraš napisati proveru.","options":["unknown","any","never","object u svim slučajevima"],"steps":["Sa unknown možeš da primiš bilo šta, ali ne možeš naslepo da pozoveš metodu ili pročitaš svojstvo kao poznatog tipa.","Provera typeof value === \\"string\\" daje kompajleru dokaz za string operacije u toj grani."],"remember":"unknown traži dokaz pre upotrebe.","wrong":["any uglavnom dopušta operacije bez zaštite koju ovde želiš.","never opisuje nemoguć slučaj, a ne nepoznat spoljašnji podatak.","object isključuje neke vrednosti, ali ne opisuje sve moguće spoljne ulaze niti njihovu šemu."]},"ts05":{"title":"Opciona svojstva i undefined","prompt":"Uz strictNullChecks, kakav je tip user.name pri čitanju?","why":"Znak ? znači da svojstvo može izostati. Pre upotrebe kao string potrebno je proveriti ga ili dati odgovarajući fallback.","pitfall":"name! potiskuje proveru, ali ne stvara vrednost koja nedostaje.","code":"type User = { id: string; name?: string };\\ndeclare const user: User;","options":["string | undefined","Samo string","Samo null","never"],"steps":["User je dozvoljen i kao { id: \\"1\\" }, bez name svojstva. JavaScript pri čitanju tog svojstva vraća undefined.","Uz strictNullChecks to moraš da obradiš, na primer user.name ?? \\"Bez imena\\", ili proverom pre poziva string metode."],"remember":"Opcioni podatak zahteva odluku šta radiš kada izostane.","wrong":["string bi neistinito obećao da ime uvek postoji.","null nije deo ovog ugovora; morao bi da bude eksplicitno dozvoljen.","never nije tip odsutnog svojstva; označava nemogućnost vrednosti."]},"ts06":{"title":"Union u svakodnevnom kodu","prompt":"Napiši normalizeId(id: string | number): string bez any i bez type assertion.","why":"Union znači da vrednost pripada jednom od dozvoljenih tipova. Ovde je String(id) dovoljan jer oba podržana ulaza imaju smislen prikaz.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"function normalizeId(id: string | number): string {\\n  return String(id);\\n}","checks":["Prima string | number.","U oba slučaja vraća string.","Nema nepotrebnog as niti any."],"steps":["Ulaz namerno dozvoljava dva tipa. String(id) je stvarna konverzija koja za oba ugovorena slučaja daje string.","Možeš koristiti i typeof granu, ali ovde dodatna složenost nije potrebna. as string bi samo potisnuo proveru, bez konverzije broja."],"remember":"Konverzija menja vrednost; assertion menja pretpostavku kompajlera.","wrong":[]},"ts07":{"title":"type i interface","prompt":"Koja tvrdnja je tačna?","why":"Za mnoge props objekte oba su dobar izbor. Važnije je dobro modelovanje nego pravilo da je jedan uvek bolji.","pitfall":"Ne praviti ideološku raspravu bez konkretne potrebe projekta.","options":["Oba mogu opisati objekat; type može opisati union, a interface podržava declaration merging.","interface postoji kao validator u browseru.","type uvek daje slabiju proveru objekta.","interface može direktno biti alias za string | number."],"steps":["Za props sa nekoliko svojstava oba oblika mogu dati jednako korisnu proveru. Razlika postaje važna kada tražiš konkretne mogućnosti.","Union poput string | number prirodno opisuješ type alias-om. Interface može da se proširuje i učestvuje u declaration merging-u."],"remember":"Izbor zasnivaj na ugovoru i konvenciji projekta.","wrong":["Interface ne ostaje kao izvršivi validator u browseru.","Type alias za objekat nije sam po sebi slabija provera.","Interface opisuje objektnu strukturu; nije direktni alias za union primitiva."]},"ts08":{"title":"Narrowing iz unknown","prompt":"Napiši getLabel(value: unknown): string. Ako je string, vrati trim; u ostalim slučajevima vrati prazan string.","why":"Narrowing povezuje stvarnu JavaScript proveru i precizniji statički tip u toj grani.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"function getLabel(value: unknown): string {\\n  return typeof value === \\"string\\" ? value.trim() : \\"\\";\\n}","checks":["Ulaz je unknown.","typeof provera prethodi string metodi.","Svi putevi vraćaju string."],"steps":["Pre provere value može biti broj, null, objekat ili string, pa trim nije bezbedan poziv.","typeof grana isključuje ostale slučajeve. U suprotnoj grani vraćaš dogovoreni fallback i zato svaki put dobijaš string."],"remember":"Prvo runtime dokaz, pa specifična metoda.","wrong":[]},"ts09":{"title":"Null i objekti","prompt":"Zašto ova provera nije dovoljna da bezbedno pristupiš value.id?","why":"Treba isključiti null, proveriti postojanje svojstva i tip tog svojstva. Provera object nije provera šeme.","pitfall":"Proveriti i nizove ili druga ograničenja ako ih domen isključuje.","code":"function read(value: unknown) {\\n  if (typeof value === \\"object\\") {\\n    // value.id ?\\n  }\\n}","options":["typeof null je \\"object\\", a nepoznat objekat ne mora imati id.","Zato što je typeof zabranjen nad unknown.","Zato što su svi objekti automatski User.","Dovoljna je čim uključimo strict."],"steps":["JavaScript istorijski vraća \\"object\\" za null. Čitanje svojstva sa null bi bacilo grešku.","Čak i { other: 1 } prolazi object proveru, ali nema id. Potrebni su provera vrednosti, svojstva i njegovog tipa."],"remember":"Objekat nije isto što i objekat ispravne šeme.","wrong":["typeof nad unknown je dozvoljen i upravo služi sužavanju.","Postojanje objekta ne dokazuje da je taj objekat User.","strict pomaže da vidiš problem u kodu; ne pretvara nedovoljan uslov u validaciju."]},"ts10":{"title":"Modeluj stanje zahteva","prompt":"Napravi discriminated union RequestState<T> sa idle, loading, success i error stanjima. Samo success ima data, samo error ima message.","why":"Ovako tipovi sprečavaju deo nemogućih kombinacija koje nekoliko nezavisnih boolean promenljivih dozvoljava.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"type RequestState<T> =\\n  | { status: \\"idle\\" }\\n  | { status: \\"loading\\" }\\n  | { status: \\"success\\"; data: T }\\n  | { status: \\"error\\"; message: string };","checks":["Svaki član ima zajedničko status svojstvo sa različitim literalom.","success sadrži data: T; error sadrži message: string.","Ne dozvoljava kombinaciju success bez podataka."],"steps":["Tri boolean zastavice mogu dozvoliti i nelogične kombinacije, recimo isLoading i isSuccess uz nedostajuće data.","Zasebne union grane opisuju tačno šta postoji u svakom stanju. Provera status automatski otvara odgovarajuća svojstva."],"remember":"Modeluj dozvoljena stanja, umesto da svuda krpiš nemoguće kombinacije.","wrong":[]},"ts11":{"title":"Exhaustiveness sa never","prompt":"Kako ćeš obezbediti da dodavanje novog člana union tipa izazove grešku u neobrađenom switch-u?","why":"never predstavlja nemoguć tip u toj tački. Ako nova grana ostane neobrađena, preostala vrednost više nije never.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"function assertNever(value: never): never {\\n  throw new Error(\\"Unexpected state\\");\\n}\\n// U default grani: return assertNever(state);","checks":["Koristi discriminated union i obradi postojeće grane.","U završnoj grani vrednost prosledi funkciji koja prima never.","Razlikuje kompajlersku proveru od runtime zaštite."],"steps":["Kada switch obradi sve članove union-a, u preostaloj grani nema validne vrednosti: njen tip je never.","Ako dodaš novo stanje, a ne dodaš case, preostala vrednost više nije never. Poziv assertNever zato postaje type greška."],"remember":"Novi član union-a treba da te odvede do svih neobrađenih mesta.","wrong":[]},"ts12":{"title":"Generics čuvaju vezu","prompt":"Šta generička funkcija first<T>(items: T[]): T | undefined čuva bolje od verzije sa any[]?","why":"Generik prenosi informaciju o tipu. undefined je bitan jer niz može biti prazan.","pitfall":"Generici se ne uvode radi ukrasa ili obećanja o performansama.","options":["Vezu između tipa elementa ulaznog niza i povratne vrednosti.","Garantuje da niz nije prazan.","Proverava API podatke u runtime-u.","Uvek je brža u browseru."],"steps":["Ako proslediš number[], T postaje number, pa rezultat ostaje number | undefined. Za User[] dobijaš User | undefined.","Sa any[] ta veza nestaje i pozivalac može pogrešno koristiti rezultat bez upozorenja."],"remember":"Generik prenosi informaciju o konkretnom tipu.","wrong":["T[] i dalje može biti prazan niz; zato povratni tip uključuje undefined.","Generički parametri ne proveravaju mrežne podatke tokom rada programa.","Generici se uklanjaju i ne predstavljaju sami po sebi ubrzanje."]},"ts13":{"title":"Generički getProperty","prompt":"Napiši getProperty koji prima objekat i ključ tog objekta, a vraća precizan tip izabranog svojstva.","why":"keyof opisuje dozvoljene ključeve, a indexed access T[K] tip vrednosti za izabrani ključ.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"function getProperty<T, K extends keyof T>(obj: T, key: K): T[K] {\\n  return obj[key];\\n}","checks":["Koristi T i K extends keyof T.","Vraća T[K] ili dozvoljava odgovarajući inference.","Ne prihvata proizvoljan string kao postojeći ključ."],"steps":["T predstavlja konkretan objekat. keyof T daje dozvoljene ključeve tog tipa, a K pamti baš izabrani ključ.","T[K] zato može razlikovati broj iz user.age od stringa iz user.name. Široko string ili any bi izgubilo tu vezu."],"remember":"Poveži objekat, dozvoljeni ključ i tip rezultata.","wrong":[]},"ts14":{"title":"Constraint za generik","prompt":"Želiš funkciju koja čita id, a zadržava dodatna polja konkretnog ulaza. Koji potpis odgovara?","why":"Constraint propisuje minimum potreban implementaciji, dok T zadržava precizniji tip konkretnog argumenta.","pitfall":"Ne vraćati lažno T kada implementacija zapravo konstruiše samo minimalni constraint.","options":["function keep<T extends { id: string }>(value: T): T","function keep(value: any): never","function keep<T>(value: T): string u svim slučajevima","function keep(value: { id: string }): unknown"],"steps":["Constraint kaže da svaki dozvoljeni ulaz mora imati id: string. Zato implementacija sme da pročita id.","T ostaje konkretan širi tip ulaza, pa dodatna polja nisu izgubljena u povratnom tipu kada vraćaš istu vrednost."],"remember":"Constraint je minimum, a T čuva konkretan oblik.","wrong":["never bi obećao da funkcija ne vraća normalan rezultat, što ovde nije cilj.","Bez constraint-a ne znaš da T ima id; povratni string takođe ne čuva ceo objekat.","unknown na izlazu gubi korisnu informaciju o konkretnim poljima."]},"ts15":{"title":"Pick i Omit","prompt":"Koji tip iz User zadržava samo id i name?","why":"Pick bira navedene ključeve. Omit izostavlja ključeve; Partial sva svojstva čini opcionim.","pitfall":"Utility tip za UI nije automatski pravi DTO za svaki endpoint.","options":["Pick<User, \\"id\\" | \\"name\\">","Omit<User, \\"id\\" | \\"name\\">","Partial<User>","Record<User, \\"id\\">"],"steps":["Pick pravi novi tip od tačno navedenih ključeva postojećeg tipa. Ključevi se navode kao union string literala.","Dobijeni tip ponovo koristi postojeće definicije id i name, pa ne prepisuješ ručno njihove tipove."],"remember":"Pick bira; Omit izostavlja.","wrong":["Omit bi uklonio id i name, upravo suprotno od zadatka.","Partial zadržava sva polja i čini ih opcionim.","Record očekuje tip ključeva i tip vrednosti; User ovde nije taj skup ključeva."]},"ts16":{"title":"Partial i poslovna pravila","prompt":"Zašto Partial<User> nije uvek dobar tip za update zahtev? Predloži bolji tip za izmenu imena i telefona.","why":"Tip treba da opisuje nameru i ugovor. Partial<User> može dozvoliti i polja koja korisnik ne sme menjati.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"type UpdateProfile = Partial<Pick<User, \\"name\\" | \\"phone\\">>;\\n// Zasebno definiši brisanje vrednosti ako endpoint koristi null.","checks":["Ne dozvoljava izmenu id, role ili drugih zaštićenih polja.","Bira dozvoljena polja pre Partial.","Razlikuje odsutno svojstvo, null i prazan string prema API ugovoru."],"steps":["User može imati role i id, ali endpoint za profil ne treba da prihvata svaku izmenu tog objekta.","Prvo Pick određuje dozvoljena polja, pa Partial dozvoljava izmenu samo nekih od njih. Server i dalje mora proveriti dozvole."],"remember":"Tip zahteva prati poslovnu operaciju, ne ceo objekat baze.","wrong":[]},"ts17":{"title":"as const nije zamrzavanje","prompt":"Šta as const radi u ovom primeru?","why":"Const assertion utiče na statičke tipove. Runtime nepromenljivost je odvojeno pitanje.","pitfall":"readonly ograničenje može biti zaobiđeno drugim referencama ili netipizovanim kodom.","code":"const statuses = [\\"draft\\", \\"sent\\"] as const;","options":["Čuva literalne tipove i readonly prikaz; ne radi duboko runtime zamrzavanje.","Poziva Object.freeze nad svim ugnježdenim objektima.","Pretvara niz u Set.","Uklanja sve provere tipova."],"steps":["Bez const assertion-a niz stringova obično gubi informaciju da su moguća baš ova dva statusa. as const čuva tu preciznost.","Readonly ograničenje postoji pri proveri tipova. Ne ubacuje kod koji bi sprečio mutaciju iz svakog mogućeg runtime puta."],"remember":"Statička nepromenljivost i runtime zamrzavanje su različite stvari.","wrong":["Object.freeze se ne poziva automatski, a ni njegov osnovni oblik nije duboko zamrzavanje.","Vrednost ostaje niz, sa preciznijim readonly tuple prikazom u tipu.","Const assertion pojačava preciznost; ne isključuje sve provere."]},"ts18":{"title":"satisfies i inference","prompt":"Zašto koristiti satisfies umesto široke anotacije ili as?","why":"satisfies pomaže pri proveri konfiguracija uz zadržavanje korisnih informacija o izrazu. Kontekst i dalje može uticati na inference.","pitfall":"Ne poistovećivati satisfies sa as const ili runtime šemom.","options":["Proverava kompatibilnost izraza sa tipom, bez zamene njegovog izvedenog tipa tim širokim tipom.","Validira odgovor servera tokom izvršavanja.","Uvek sprečava mutaciju vrednosti.","Svaki broj pretvara u numeric literal."],"steps":["Široka anotacija može sakriti precizniji oblik objekta koji si upravo napisao. Assertion može nepravilno ubediti kompajler da je nešto tačno.","satisfies proverava usklađenost, dok izrazu ostavlja njegov izvedeni tip. To je korisno za mape i konfiguracije sa poznatim ključevima."],"remember":"Proveri ugovor i sačuvaj korisnu preciznost.","wrong":["satisfies ne proverava podatke koji kasnije stignu sa servera.","Ne znači automatski readonly niti runtime zabranu mutacije.","Literalna preciznost zavisi i od konteksta; ovo nije univerzalna zamena za as const."]},"ts19":{"title":"Mapped i conditional types","prompt":"Objasni ReadonlyFields<T> i ElementOf<T>. Napiši jednostavne implementacije i jedan slučaj upotrebe.","why":"Ovi alati pomažu u bibliotekama i deljenim modelima. Ne treba komplikovati obične props samo da bi se pokazala sintaksa.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"type ReadonlyFields<T> = { readonly [K in keyof T]: T[K] };\\ntype ElementOf<T> = T extends readonly (infer U)[] ? U : never;\\n\\ntype User = { id: number; profile: { name: string } };\\ntype ReadonlyUser = ReadonlyFields<User>;\\ntype ListItem = ElementOf<User[]>; // User\\nconst view: ReadonlyUser = { id: 1, profile: { name: \\"Ada\\" } };\\n// view.id = 2; // Greška tipa: readonly polje.\\nview.profile.name = \\"Ana\\"; // Dozvoljeno: readonly je ovde plitak.","checks":["Mapped type obilazi keyof T.","Conditional type koristi extends i infer za element niza.","Razume da su ovo statičke transformacije tipova.","Prikazuje konkretan model i razlikuje plitak readonly od duboke nepromenljivosti."],"steps":["Mapped type prolazi kroz svojstva postojećeg tipa i sistematski ih menja, na primer dodaje readonly.","Conditional type bira rezultat prema odnosu tipova. infer U u obrascu niza izvlači njegov element, pa radi i bez ručnog navođenja elementa."],"remember":"Ove alatke transformišu tipove; ne obilaze stvarne objekte tokom izvršavanja.","wrong":[]},"ts20":{"title":"React props i callback","prompt":"Tipizuj SaveButton sa label, disabled i onSave. onSave prima id: string i vraća void.","why":"Dobar props tip govori komponenti šta sme da dobije, a pozivaocu šta mora da prosledi.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"type SaveButtonProps = {\\n  label: string;\\n  disabled?: boolean;\\n  onSave: (id: string) => void;\\n};","checks":["label je string, disabled je opcioni boolean.","Callback je (id: string) => void.","Props i mesto korišćenja poštuju isti ugovor."],"steps":["Props ugovor štiti i komponentu i mesto upotrebe: pozivalac mora dati label i onSave odgovarajućeg oblika.","Tip callback-a opisuje šta komponenta šalje roditelju. disabled? kaže da pozivalac može izostaviti tu opciju."],"remember":"Tip callback-a je deo javnog API-ja komponente.","wrong":[]},"ts21":{"title":"useState i null","prompt":"Koja deklaracija dozvoljava početni null i kasnije User?","why":"Ako je početna vrednost null, eksplicitan union prenosi nameru koju inicijalna vrednost sama ne otkriva.","pitfall":"any prikriva problem i gubi proveru svojstava korisnika.","options":["useState<User | null>(null)","useState(null) bez dodatnog tipa uvek","useState<User>(null) uz strictNullChecks","useState<any>(null) je jedina mogućnost"],"steps":["Početni null ne govori kompajleru da će se kasnije pojaviti User. Eksplicitni union daje tu dodatnu informaciju.","Pri čitanju user.name prvo proveri da user nije null. Time tip ostaje iskren i kroz loading stanje."],"remember":"Početna vrednost nije uvek ceo model budućeg stanja.","wrong":["Samo useState(null) normalno izvodi null, pa kasniji User nije dozvoljen.","Uz strictNullChecks null nije User ako ga ugovor ne uključuje.","any radi tako što odustaje od zaštite; precizan union je bolji ugovor."]},"ts22":{"title":"Input event bez any","prompt":"Napiši onChange handler za HTML input u Reactu i pročitaj string vrednost.","why":"DOM input value je string. Numerički unos zahteva eksplicitnu konverziju i obradu prazne ili nevažeće vrednosti.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"function handleChange(event: React.ChangeEvent<HTMLInputElement>) {\\n  setName(event.currentTarget.value);\\n}","checks":["Koristi React.ChangeEvent<HTMLInputElement> ili inference na JSX handleru.","Čita event.currentTarget.value.","Ne tvrdi da type=\\"number\\" automatski daje number u value."],"steps":["ChangeEvent opisuje React događaj, a HTMLInputElement konkretan element koji taj handler obrađuje.","currentTarget je element na koji je handler vezan. Njegov value je string čak i kada input vizuelno prihvata broj."],"remember":"Tipizovan događaj ne radi automatsku konverziju input vrednosti.","wrong":[]},"ts23":{"title":"Props koji sprečavaju nemoguća stanja","prompt":"Modeluj Alert koji ima variant: success ili error. Samo error traži retry callback.","why":"Discriminated props omogućavaju prirodno sužavanje i sprečavaju deo nevažećih kombinacija na mestu korišćenja.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"type AlertProps =\\n  | { variant: \\"success\\"; message: string; retry?: never }\\n  | { variant: \\"error\\"; message: string; retry: () => void };","checks":["Koristi union grana sa literalnim variant.","Error grana ima obavezan retry.","Success ne dobija lažno obavezan retry; objašnjava ograničenja structural typing-a."],"steps":["Jedan objekat sa opcionim retry svuda dozvolio bi error bez oporavka. Union može zahtevati callback samo kada je potreban.","retry?: never na success grani dodatno ograničava pogrešnu kombinaciju. Podrobnosti opcionih svojstava zavise i od TS podešavanja."],"remember":"Props treba da opisuju dozvoljene kombinacije, ne samo pojedinačna polja.","wrong":[]},"ts24":{"title":"API odgovor nije obećani tip","prompt":"Objasni problem u kodu i predloži bezbedniji tok.","why":"Spoljni sistem nije pod kontrolom TS kompajlera. Granica sistema je dobro mesto za validaciju i normalizaciju.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","code":"const user = await response.json() as User;\\nreturn user.name.toUpperCase();","solution":"const response = await fetch(\\"/api/me\\");\\nif (!response.ok) throw new Error(\`HTTP \${response.status}\`);\\nconst raw: unknown = await response.json();\\nconst user = UserSchema.parse(raw); // uz definisanu šemu","checks":["as User nije runtime provera.","Proverava HTTP status i JSON oblik odvojeno.","Predlaže validator/šemu i obradu nevažećeg odgovora."],"steps":["response.json() može uspešno parsirati JSON koji nema nijedno očekivano User polje. as User to ne popravlja.","HTTP provera kaže da li je status uspešan; šema kaže da li sadržaj ima ugovoreni oblik. To su odvojeni koraci sa različitim greškama."],"remember":"Uspešan HTTP i ispravna poslovna šema nisu isti dokaz.","wrong":[]},"ts25":{"title":"tsc i bundler nisu ista provera","prompt":"Aplikacija se izgradila bundlerom koji uklanja TS sintaksu. Da li je dokazano da nema type grešaka?","why":"Transpilacija, proveravanje tipova i izvršavanje testova pokrivaju različite vrste problema.","pitfall":"Ne pretpostavljati da naziv build skripte garantuje sadržaj njenih provera.","options":["Ne. Potreban je type-check korak, npr. tsc --noEmit, prema konfiguraciji projekta.","Da, svaki bundler obavezno proverava sve tipove.","Da, ako browser nema console greške.","Ne, TypeScript nikada ne može da proveri React."],"steps":["Transpiler može ukloniti TS anotacije i napraviti izvršiv JavaScript, čak i kada program sadrži neslaganja tipova.","Zaseban type-check u CI proverava to neslaganje. Testovi zatim proveravaju ponašanje koje tipovi ne mogu potpuno opisati."],"remember":"Build, type-check i test imaju različite odgovornosti.","wrong":["Mogućnosti bundlera i build skripte zavise od konkretne konfiguracije.","Kod može raditi na jednom putu, a i dalje imati type grešku na drugom.","React i TS su podržana kombinacija; treba odgovarajuća konfiguracija i type-check."]},"ts26":{"title":"Migracija JS projekta u TS","prompt":"Imaš veliki React/Redux projekat i rok za feature. Predloži postepenu migraciju umesto masovnog prepisivanja.","why":"Cilj migracije je sigurniji razvoj. Promena svih ekstenzija uz any svuda može doneti trošak bez koristi.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Primer plana: dogovoriti strict politiku → tipizovati novi API modul → jednu vertikalnu funkcionalnost → proveriti regresije → širiti postepeno.","checks":["Počinje granicama: DTO, zajednički modeli, novi i menjani moduli.","Uvodi proveru tipova u CI i smanjuje any uz jasne prioritete.","Planira kompatibilnost, male PR-ove, testove i merljiv završetak faze."],"steps":["Veliki rewrite menja previše stvari odjednom i otežava razdvajanje migracione greške od funkcionalne promene.","Mala vertikalna celina proverava modele, API i UI zajedno. Posle nje možeš širiti obrazac na osnovu stvarnog iskustva i provera."],"remember":"Migraciju meri povećanom sigurnošću, ne samo brojem .tsx fajlova.","wrong":[]},"ts27":{"title":"Tipizovan async servis","prompt":"Napiši potpis i objasni implementaciju getUsers(): Promise<User[]>. Gde obrađuješ HTTP, nevažeći JSON, otkazivanje i UI grešku?","why":"Promise<User[]> opisuje uspešan rezultat. Sam potpis ne dokumentuje niti proverava sve failure slučajeve.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"async function getUsers(signal?: AbortSignal): Promise<User[]> {\\n  const r = await fetch(\\"/api/users\\", { signal });\\n  if (!r.ok) throw new Error(\`HTTP \${r.status}\`);\\n  return UsersSchema.parse(await r.json());\\n}","checks":["Razdvaja mrežu/HTTP, parsiranje i validaciju podataka.","Prima ili prenosi AbortSignal i ne prikazuje otkazivanje kao običan kvar.","UI razlikuje loading, empty, error i success; ne skriva grešku vraćanjem []."],"steps":["Promise<User[]> govori šta dobijaš kada poziv uspe. Ne garantuje mrežu, status, format tela niti trajanje zahteva.","Servis proverava granicu podataka, a UI prikazuje odgovarajuće stanje. Otkazivanje razlikuješ od kvara koji korisnik treba da vidi."],"remember":"Ne prikrivaj neuspeh praznim nizom ako je prazan niz legitiman uspešan rezultat.","wrong":[]},"ts28":{"title":"Završni TS zadatak: tipizovana tabela","prompt":"Projektuj Column<T> za read-only tabelu: stabilan id, naslov i render(row). Objasni kako bi dodao sortiranje, a da mobilne kartice i desktop koriste iste vrednosti.","why":"Senior rešenje povezuje tipove, ponašanje i upotrebljivost. Generik sam ne garantuje konzistentan komparator ili ispravnu serversku paginaciju.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"type Column<T> = {\\n  id: string;\\n  title: string;\\n  render: (row: T) => React.ReactNode;\\n  getSortValue?: (row: T) => string | number | null;\\n};\\n// Definiši i redosled za null, locale i stabilnost.","checks":["Generik vezuje row za T i render ima smislen izlazni tip.","Razdvaja prikazanu vrednost i vrednost za sortiranje.","Sortira/filtrira ceo klijentski skup pre paginacije i deli pravila prikaza."],"steps":["Column<T> povezuje render funkciju sa istim tipom reda koji tabela prima. Nevažeće svojstvo tako postaje vidljivo pri razvoju.","Prikaz može biti formatirana valuta, ali sortiranje treba da koristi numeričku vrednost. Deljena pravila sprečavaju da mobile i desktop daju različit redosled."],"remember":"Dobar tip povezuje ugovor; dobra implementacija čuva isto ponašanje.","wrong":[]},"js01":{"title":"const ne znači immutable","prompt":"Šta se desi?","why":"Veza u se ne menja, menja se objekat na koji pokazuje.","pitfall":"Immutable update zahteva da razumeš i ugnježdene reference.","code":"const u = { count: 1 };\\nu.count = 2;\\nconsole.log(u.count);","options":["Ispisuje 2. const zabranjuje ponovno vezivanje, ne mutaciju svojstava.","Baca grešku na u.count = 2.","Ispisuje 1.","Objekat postaje duboko zamrznut."],"steps":["const zaključava vezu između imena i objekta. Ne zaključava memoriju samog objekta.","u.count = 2 menja postojeći objekat; u = drugiObjekat bi pokušalo zabranjeno ponovno vezivanje."],"remember":"Stalna referenca ne znači nepromenljiv sadržaj.","wrong":["Svojstvo nije samo po sebi readonly niti zamrznuto.","Izmena je izvršena pre console.log, pa se čita nova vrednost.","const ne poziva Object.freeze, ni plitko ni duboko."]},"js02":{"title":"Event loop i microtasks","prompt":"U browseru, koji redosled ispisa očekuješ za ovaj samostalni primer?","why":"Sinhroni kod završi prvi. Promise callback se izvršava kao microtask pre narednog timer task-a.","pitfall":"setTimeout(..., 0) ne znači odmah; vreme timera nije garancija tačnog početka.","code":"console.log(\\"A\\");\\nsetTimeout(() => console.log(\\"B\\"), 0);\\nPromise.resolve().then(() => console.log(\\"C\\"));\\nconsole.log(\\"D\\");","options":["A, D, C, B","A, B, C, D","A, C, D, B","A, D, B, C"],"steps":["Prvo se izvršava sav sinhroni kod: A i D. Callback-ovi ne prekidaju taj trenutni niz naredbi.","Zatim se prazni microtask red, gde je Promise callback C. Timer B dolazi kao naredni task."],"remember":"Sinhrono → microtasks → sledeći task, za ovaj primer.","wrong":["Timer callback ne ide odmah na mesto gde je setTimeout pozvan.","Promise callback ne preseca preostali sinhroni console.log D.","U ovom primeru Promise microtask ide pre timer task-a."]},"js03":{"title":"Closure u praksi","prompt":"Objasni closure kroz funkciju makeCounter. Zašto dva nezavisna poziva makeCounter ne moraju deliti isti brojač?","why":"Closure je pristup promenljivama iz okruženja u kojem je funkcija nastala, ne automatsko snimanje svake vrednosti u trenutku poziva.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"function makeCounter() {\\n  let count = 0;\\n  return () => ++count;\\n}\\nconst a = makeCounter();\\nconst b = makeCounter();\\n// a(): 1, a(): 2, b(): 1","checks":["Funkcija zadržava pristup leksičkom okruženju.","Svaki poziv fabrike stvara zasebno okruženje.","Daje primer i povezuje ga sa stale closure problemom u Reactu."],"steps":["Vraćena funkcija nastavlja da vidi count iz svog leksičkog okruženja i nakon što se makeCounter završi.","Dva poziva fabrike stvaraju dva count vezivanja. Dve funkcije iz istog okruženja, nasuprot tome, mogu deliti iste promenljive."],"remember":"Closure prati okruženje; proveri koja vezivanja zaista deliš.","wrong":[]},"js04":{"title":"Spread je plitak","prompt":"Koja je vrednost a.address.city posle ovog koda?","why":"Spread kopira prvi nivo. address ostaje ista referenca u oba objekta.","pitfall":"Za React update kopiraj sve nivoe koje menjaš; duboko kloniranje svega nije uvek dobro rešenje.","code":"const a = { address: { city: \\"Beograd\\" } };\\nconst b = { ...a };\\nb.address.city = \\"Novi Sad\\";","options":["Novi Sad","Beograd","undefined","Kod uvek baca grešku."],"steps":["a i b su različiti spoljašnji objekti, ali oba address svojstva pokazuju na isti unutrašnji objekat.","Zato izmena b.address.city postaje vidljiva i kroz a.address.city. Kopiraj i address ako želiš nezavisnu izmenu te grane."],"remember":"Spread ne kopira duboko ceo graf referenci.","wrong":["Beograd bi ostao kada bi ugnježdeni address bio nezavisno kopiran.","Svojstvo city postoji i dobija novu vrednost.","U ovom običnom, nezamrznutom objektu mutacija je dozvoljena."]},"js05":{"title":"?? i || nisu zamenljivi","prompt":"Koji izraz čuva namernu vrednost 0?","why":"?? koristi fallback samo za null i undefined. || ga koristi i za 0, false i prazan string.","pitfall":"Izaberi operator prema domenskom značenju prazne vrednosti.","code":"const count = 0;","options":["count ?? 10","count || 10","Oba uvek daju 10","Nijedan ne može vratiti broj."],"steps":["Nula često ima važno poslovno značenje, na primer da nema artikala ili da je cena nula.","|| nulu smatra falsy i daje fallback. ?? proverava samo null ili undefined i zato zadržava 0."],"remember":"Odluči da li tražiš odsutnu vrednost ili bilo koju falsy vrednost.","wrong":["0 je falsy, pa izraz sa || vraća 10.","Operatori imaju različite uslove za fallback.","Oba mogu vratiti broj; razlika je koji operand biraju."]},"js06":{"title":"Promise.all ili allSettled","prompt":"Tri nezavisna widgeta učitavaju podatke. Jedan endpoint ne radi. Kada biraš all, a kada allSettled?","why":"Pokretanje zahteva, čekanje rezultata i otkazivanje su tri odvojene odluke.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"// all: sve potrebno za jedan rezultat\\n// allSettled: obradi fulfilled/rejected po widgetu","checks":["all odbija zbirni Promise kada neki odbije; ne otkazuje automatski ostale poslove.","allSettled vraća ishod svakog posla.","Odluka zavisi od toga da li delimičan prikaz ima poslovni smisao."],"steps":["Ako jedan rezultat bez ostalih nema smisla, zajednički neuspeh sa all može biti dobar ugovor.","Ako su widgeti nezavisni, allSettled omogućava da prikažeš uspešne i lokalnu grešku za ostale. To samo po sebi ne otkazuje zahteve."],"remember":"Koordinacija rezultata nije isto što i kontrola izvršavanja.","wrong":[]},"js07":{"title":"Debounce za pretragu","prompt":"Napiši mali debounce. Objasni cleanup i zašto debounce sam ne rešava pogrešan redosled API odgovora.","why":"Debounce smanjuje broj pokretanja. Poslati zahtevi i dalje mogu završiti drugačijim redosledom.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"function debounce(fn, ms) {\\n  let timer;\\n  function run(...args) {\\n    clearTimeout(timer);\\n    timer = setTimeout(() => fn(...args), ms);\\n  }\\n  run.cancel = () => clearTimeout(timer);\\n  return run;\\n}\\n// Ova minimalna verzija ne prosleđuje dinamički this.","checks":["Otkazuje prethodni timer i poziva poslednji posao.","Čuva argumente; cleanup otkazuje timer.","Zasebno rešava race condition zahteva."],"steps":["Svaki novi poziv uklanja prethodni timer i zakazuje posao sa poslednjim argumentima. Posao se pokreće nakon perioda bez novih poziva.","Zahtev koji je već poslat ne nestaje uklanjanjem timera. Za njegov zastareli rezultat treba zasebna zaštita."],"remember":"Debounce kontroliše početak posla; race zaštita kontroliše primenu rezultata.","wrong":[]},"js08":{"title":"this i arrow funkcije","prompt":"Objasni razliku između metode objekta i arrow funkcije kada se proslede kao callback. Kako bind pomaže?","why":"Ne treba tvrditi da arrow uvek predstavlja bolju metodu. Važan je željeni receiver.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"const safeCallback = object.method.bind(object);\\n// ili () => object.method()","checks":["Obična funkcija dobija this prema načinu poziva.","Arrow koristi this iz okruženja.","Izdvajanje metode može izgubiti receiver; bind ili wrapper to rešava."],"steps":["Kod obj.method(), receiver je obj. Ako izdvojiš metodu i pozoveš je kao običan callback, taj poziv više nema isti receiver.","bind pravi funkciju sa vezanim this. Arrow ga preuzima iz okruženja i ne dobija novi this samo zato što je pozvan kao metoda."],"remember":"Uvek pogledaj način poziva i mesto nastanka funkcije.","wrong":[]},"js09":{"title":"Sortiranje brojeva","prompt":"Koji kod sortira brojeve rastuće i čuva originalni niz?","why":"sort bez komparatora poredi string prikaze. sort menja niz; kopija čuva ulaz.","pitfall":"Boolean komparator ne definiše pravilan negativan/nula/pozitivan odnos.","options":["[...numbers].sort((a, b) => a - b)","numbers.sort()","numbers.sort((a, b) => a > b)","numbers.reverse()"],"steps":["Podrazumevano sortiranje pretvara vrednosti za poređenje u stringove, pa 10 može doći pre 2.","a - b daje negativno, nulu ili pozitivno prema numeričkom odnosu. Kopija niza sprečava mutaciju originalnog redosleda."],"remember":"Ispravan komparator plus jasna politika mutacije.","wrong":["Menja originalni niz i ne traži numeričko poređenje.","Boolean ne izražava pravilno obe strane poređenja.","reverse samo obrće postojeći redosled, bez opšteg sortiranja."]},"js10":{"title":"Pretraga i zastareo odgovor","prompt":"Korisnik upiše Ana pa Anja. Odgovor za Ana stiže kasnije. Projektuj zaštitu od prepisivanja novijeg rezultata.","why":"Najnoviji započeti upit određuje prikaz, a ne poslednji pristigli odgovor. U praksi query sloj može upravljati ovim pravilima.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"let latest = 0;\\nasync function search(q) {\\n  const requestId = ++latest;\\n  const data = await load(q);\\n  if (requestId === latest) show(data);\\n}\\n// Dodaj obradu grešaka i otkazivanje prema okruženju.","checks":["Prepoznaje race condition.","Koristi AbortController i/ili proveru identiteta aktuelnog zahteva.","Otkazivanje i greške obrađuje odvojeno; proverava slučaj promene parametra."],"steps":["Vreme dolaska odgovora nije identitet korisnikove aktuelne namere. Stariji zahtev može biti sporiji.","Pre primene rezultata proveri da li pripada poslednjem zahtevu. Abort smanjuje nepotreban rad, ali zaštita UI-ja treba da bude promišljena i za završne grane."],"remember":"Poslednja namera određuje rezultat, a ne poslednji pristigli paket.","wrong":[]},"js11":{"title":"Map, Set i složenost","prompt":"Treba da spojiš 10.000 redova po id. Zašto lookup indeks može biti bolji od find unutar map?","why":"Jedan prolaz za indeks i jedan za spajanje često su jasniji i efikasniji od ugnježdenih pretraga.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"const byId = new Map(otherRows.map(row => [row.id, row]));\\nconst merged = rows.map(row => ({ ...row, extra: byId.get(row.id) }));\\n// Ovde poslednji duplikat id-ja pobeđuje: dogovori pravilo.","checks":["Uočava ponovljene linearne pretrage i mogući O(n*m).","Gradi indeks i obrađuje odsutne i duplirane id vrednosti.","Ne predstavlja očekivanu cenu Map operacije kao apsolutnu garanciju."],"steps":["find ponovo prolazi drugi niz za svaki red prvog niza. Kada oba rastu, broj poređenja može rasti veoma brzo.","Indeks praviš jednom, a zatim pronalaziš dopunski podatak po id. Pre toga odluči kako tretiraš duplikate i neuspele spojeve."],"remember":"Prvo razumi obrazac pristupa podacima, pa biraj strukturu.","wrong":[]},"js12":{"title":"Moduli i tree shaking","prompt":"Objasni ESM import/export, dinamički import i zašto tree shaking ne uklanja svaki neiskorišćeni kod.","why":"Manji početni paket može pomoći, ali previše sitnih lazy delova može napraviti waterfall. Proveri rezultat build-a.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"const { openEditor } = await import(\\"./editor.js\\");\\nopenEditor();","checks":["Razlikuje statički modul i async import().","Razume side effects i mogućnosti bundlera.","Code splitting procenjuje prema mreži i korisničkom toku."],"steps":["Statički ESM import/export daje alatu informacije o zavisnostima. Dinamički import() omogućava kasnije učitavanje dela aplikacije.","Kod sa side effects ne može uvek bezbedno da se odbaci. Proveri rezultat bundlera umesto pretpostavke da će ukloniti sve što ne vidiš u JSX-u."],"remember":"Odloženo učitavanje ima cenu mreže i tajminga.","wrong":[]},"re01":{"title":"State je snapshot","prompt":"Uz početni count = 0, klik izvrši ovaj handler. Šta je sledeći count?","why":"Oba izraza koriste count iz istog rendera. Za dva uzastopna povećanja koristi funkcionalne updatere.","pitfall":"setCount(c => c + 1) opisuje promenu nad prethodnim stanjem.","code":"setCount(count + 1);\\nsetCount(count + 1);","options":["1","2","0","Zavisi samo od brzine browsera."],"steps":["Handler koristi count iz rendera u kojem je nastao. U tom renderu count je 0, pa oba poziva traže istu sledeću vrednost: 1.","Funkcionalni updater se obrađuje u redu promena: setCount(c => c + 1) dva puta nadovezuje drugu promenu na prvu."],"remember":"Snapshot vrednosti i red updater funkcija nisu isto.","wrong":["Dva ista zahteva za vrednost 1 ne postaju automatski dva povećanja.","Promena je zakazana i sledeći render dobija novu vrednost.","Semantika ovog handlera ne zavisi od brzine browsera."]},"re02":{"title":"Izvedena vrednost bez Effect-a","prompt":"Ime i prezime su već state. Gde izračunati fullName?","why":"Izvedena vrednost obično ne zahteva zaseban state. Effect uvodi dodatni prolaz i mogućnost neslaganja.","pitfall":"useMemo uvodi se za opravdan trošak ili identitet, ne za svako spajanje stringova.","options":["Tokom rendera, iz firstName i lastName.","U posebnom state-u uz obavezni Effect.","U globalnom store-u u svim slučajevima.","Direktnom promenom DOM-a."],"steps":["fullName nema nezavisnu informaciju: uvek možeš ponovo da ga dobiješ iz dva postojeća stringa.","Ako ga čuvaš u još jednom state-u, moraš održavati dva izvora istine i obrađivati dodatni prolaz sa starom vrednošću."],"remember":"Ne čuvaj u state-u ono što jednostavno izvodiš iz postojećeg state-a.","wrong":["Obavezan Effect ovde dodaje sinhronizaciju koja nije potrebna.","Globalni store ne rešava nepotrebno dupliranje izvedene vrednosti.","Ručna DOM promena zaobilazi React model prikaza bez potrebe."]},"re03":{"title":"Keys i identitet","prompt":"Zašto index kao key može napraviti problem kada redovi imaju inpute i menjaju redosled?","why":"Problem nije samo upozorenje ili brzina. Pogrešan identitet može prikazati podatke ili state drugog reda.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"{rows.map(row => <Row key={row.id} row={row} />)}","checks":["Key učestvuje u povezivanju identiteta elementa između rendera.","Index se odnosi na poziciju i može povezati state sa pogrešnim redom.","Bira stabilan id iz podataka; ne generiše random key pri renderu."],"steps":["React povezuje prethodni i sledeći element pomoću tipa i identiteta, u kojem key ima važnu ulogu među susedima.","Ako key predstavlja poziciju, promena redosleda može zadržati input state na pogrešnom podatku. Stabilan id prati isti poslovni red."],"remember":"Key treba da prati podatak, ne njegov trenutni redni broj.","wrong":[]},"re04":{"title":"Effect kao sinhronizacija","prompt":"Povezuješ subscription ili event listener. Kako biraš dependencies i cleanup?","why":"Dependency niz nije ručni raspored izvršavanja nezavisan od koda. Ako su dependencies problem, preispitaj strukturu Effect-a.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"useEffect(() => {\\n  const unsubscribe = subscribe(roomId, handleMessage);\\n  return unsubscribe;\\n}, [roomId, handleMessage]);","checks":["Effect sinhronizuje komponentu sa spoljnim sistemom.","Navodi reaktivne vrednosti koje koristi.","Cleanup uklanja prethodnu pretplatu i podržava ponovna povezivanja."],"steps":["Setup povezuje komponentu sa spoljnim sistemom koristeći vrednosti tog rendera. Kada se one promene, potrebna je nova sinhronizacija.","Cleanup uklanja prethodnu vezu pre sledećeg odgovarajućeg setup-a i pri uklanjanju komponente. Bez njega ostaju stari listener-i ili pretplate."],"remember":"Svaki setup treba da ima odgovarajuću priču o cleanup-u.","wrong":[]},"re05":{"title":"Strict Mode u razvoju","prompt":"Šta dodatni razvojni setup → cleanup → setup ciklus Effect-a proverava?","why":"Razvojne provere otkrivaju slabosti. Popravka je pravilna sinhronizacija, uz razumevanje gde je StrictMode postavljen.","pitfall":"Ref koji samo blokira drugi setup može sakriti grešku umesto da je reši.","options":["Da li je sinhronizacija otporna na ponovno povezivanje i da li cleanup radi.","Da produkcija obavezno izvršava svaki Effect dva puta.","Da je dozvoljeno preskočiti cleanup uz ref zastavicu.","Da svi API zahtevi automatski postaju idempotentni."],"steps":["Ako ponovno povezivanje napravi duple listener-e ili curenje resursa, dodatni ciklus to otkriva dok razvijaš.","Popravka treba da učini setup i cleanup ispravnim. Samo blokiranje drugog setup-a može ostaviti komponentu nepovezanu nakon cleanup-a."],"remember":"Provera ponovnog povezivanja traži ispravnost, ne zaobilaznicu.","wrong":["Razvojni ciklus nije tvrdnja da se svaki produkcioni Effect uvek duplira.","Ref zastavica ne zamenjuje pravilno upravljanje resursom.","Idempotency server operacije mora biti deo odvojenog ugovora."]},"re06":{"title":"State ili ref","prompt":"Gde čuvaš vrednost inputa koja utiče na prikaz, a gde id timera? Zašto?","why":"Ref i state rešavaju različite potrebe. Promena ref.current sama ne traži novi render.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"const [query, setQuery] = useState(\\"\\");\\nconst timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);","checks":["State kada promena treba da utiče na render.","Ref za promenljivu vrednost koju treba sačuvati bez rendera.","Ne mutira ref tokom rendera za poslovnu sinhronizaciju."],"steps":["Promena inputa treba da promeni ono što korisnik vidi, pa state daje Reactu signal za novi render.","Id timera samo čuvaš za kasnije otkazivanje. Njegova promena nije vizuelni podatak, pa ref odgovara toj potrebi."],"remember":"Pitaj: da li promena ove vrednosti treba da promeni ekran?","wrong":[]},"re07":{"title":"Memoizacija i React Compiler","prompt":"Kako odlučuješ između jednostavnog koda, memo/useMemo/useCallback i Compiler optimizacije?","why":"Compiler može automatski memoizovati podržan React kod u build-u. I dalje moraš razumeti state, čistoću i stvarni uzrok usporenja.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Odgovor zasnuj na profiler tragu, količini podataka i konfiguraciji konkretnog projekta.","checks":["Prvo meri problem i razlikuje render od DOM izmene.","Razume identitet props i cenu/ograničenja memoizacije.","Proverava da li je Compiler uključen i ne smatra ga rešenjem za mrežu ili lošu arhitekturu."],"steps":["Memoizacija čuva rezultat ili identitet kada su relevantni ulazi isti. Ako se ulazi stalno menjaju ili računanje nije skupo, korist može biti mala.","Compiler automatizuje deo tih optimizacija kada je uključen i kod pogodan. Ne smanjuje sam veličinu API odgovora niti menja loš algoritam."],"remember":"Optimizaciju potvrdi merenjem konkretnog uskog grla.","wrong":[]},"re08":{"title":"Context i renderovanje","prompt":"Šta je razumna tvrdnja o Context-u?","why":"Context je način prenošenja vrednosti kroz stablo. Za učestalost promena i granularnost potrošnje treba promišljen dizajn.","pitfall":"Ne dodavati useMemo svuda bez merenja; prvo razdvoji različite potrebe.","options":["Promena provider value može ponovo renderovati potrošače; važno je gde deliš stanje i identitet vrednosti.","Context automatski sprečava sva ponovna renderovanja.","Context je potpuna zamena za server cache.","Svaki globalni podatak mora imati zaseban Redux store."],"steps":["Potrošač čita vrednost iz najbližeg provider-a. Nova value vrednost može zahtevati da se potrošači ažuriraju.","Ako u jedan Context staviš mnogo nepovezanih promenljivih, promena jedne može zahvatiti više potrošača nego što želiš."],"remember":"Podela odgovornosti dolazi pre nasumične memoizacije.","wrong":["Context prenosi podatke; nije univerzalni mehanizam sprečavanja rendera.","Keširanje serverskih podataka uključuje invalidaciju i mrežne tokove koje Context sam ne daje.","Deljenje vrednosti ne zahteva automatski novi Redux store."]},"re09":{"title":"Controlled i uncontrolled forme","prompt":"Objasni obe varijante na input primeru. Koji su kompromisi kod velike forme i integracije sa UI bibliotekom?","why":"Izbor zavisi od funkcionalnosti forme i alata; controlled nije automatski profesionalniji u svakom slučaju.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"import { useState } from \\"react\\";\\n\\nexport function InputExamples() {\\n  const [name, setName] = useState(\\"\\");\\n  return (\\n    <>\\n      <label>Kontrolisano\\n        <input value={name} onChange={event => setName(event.currentTarget.value)} />\\n      </label>\\n      <form onSubmit={event => {\\n        event.preventDefault();\\n        const value = new FormData(event.currentTarget).get(\\"name\\");\\n        console.log(value);\\n      }}>\\n        <label>Nekontrolisano\\n          <input name=\\"name\\" defaultValue=\\"Ada\\" />\\n        </label>\\n        <button type=\\"submit\\">Pročitaj vrednost</button>\\n      </form>\\n    </>\\n  );\\n}","checks":["Razlikuje value/onChange od defaultValue i DOM upravljanja.","Ne prelazi nenamerno između undefined i definisanog value.","Uvažava validaciju, reset, broj rendera i integraciju komponenti."],"steps":["Kod controlled inputa React stanje određuje value. Kod uncontrolled pristupa DOM čuva tekuću vrednost, uz način da je pročitaš kada treba.","Velika forma traži i dobar model validacije, dirty/reset ponašanja i integracije. Broj linija koda nije dovoljan kriterijum za izbor."],"remember":"Izaberi način upravljanja poljem prema potrebnom ponašanju.","wrong":[]},"re10":{"title":"Transition i odloženi prikaz","prompt":"Pretraga sa velikom listom blokira kucanje. Šta mogu useTransition/useDeferredValue, a šta ne mogu?","why":"Odlaganje render prioriteta nije uklanjanje rada. Cilj je odzivnost uz odgovarajući loading ili stale prikaz.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"const deferredQuery = useDeferredValue(query);\\n// Lista može koristiti odloženi query; input ostaje vezan za query.","checks":["Razdvaja hitan input update i manje hitno renderovanje.","Zna da ne predstavljaju sami po sebi mrežni debounce.","Za skupo CPU izračunavanje razmatra algoritam, virtualizaciju ili Worker."],"steps":["Korisnik očekuje da input odmah prati kucanje. Lista može privremeno ostati na prethodnom rezultatu dok se manje hitan prikaz priprema.","Ovi hookovi pomažu raspoređivanju renderovanja. Dug sinhroni proračun, veliki DOM i broj mrežnih zahteva i dalje treba posebno rešavati."],"remember":"Prioritet rada i količina rada su različita pitanja.","wrong":[]},"re11":{"title":"Error boundary i async greške","prompt":"Zašto Error Boundary ne rešava svaku grešku iz onClick i API poziva? Kako deliš odgovornost?","why":"Treba projektovati i globalni fallback i lokalne failure tokove. Prazan ekran nije prihvatljiva obrada greške.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"try { await save(); } catch (error) { setSaveError(toUserMessage(error)); }","checks":["Boundary hvata odgovarajuće render/lifecycle greške potomaka.","Event handler i obične async greške imaju eksplicitnu obradu.","Korisnik dobija oporavak; logovi ne otkrivaju osetljive podatke."],"steps":["Render greška može srušiti deo stabla i boundary tada daje kontrolisan fallback za odgovarajući opseg.","Neuspeo save iz event handlera treba eksplicitno pretvoriti u korisniku razumljivo stanje, mogućnost ponavljanja i odgovarajući log."],"remember":"Globalni fallback ne zamenjuje lokalni error tok.","wrong":[]},"re12":{"title":"Server i Client Components","prompt":"Objasni razliku između RSC, SSR i hydration. Gde smeju tajne, a gde interakcije i browser API-ji?","why":"Ovo je dopunski pravac ako ciljni posao koristi odgovarajući framework. SPA iskustvo samo po sebi ne pokriva serverske granice.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Objasni tok: serverski podatak → serijalizabilni props → interaktivna komponenta → autorizovan server zahtev.","checks":["Ne poistovećuje RSC i SSR.","Client komponente imaju state/evente; browser API-je koristi u odgovarajućem trenutku.","Tajne i autorizacija ostaju na serveru; granice zavise od framework-a."],"steps":["SSR opisuje serversko stvaranje HTML-a; hydration povezuje odgovarajući klijentski kod sa tim prikazom. RSC uvodi drugačiju komponentnu granicu izvršavanja.","Client komponenta može učestvovati i u serverskom pre-renderu, zato browser API ne koristiš naslepo tokom rendera. Tajne ostaju van klijentskog paketa."],"remember":"Razlikuj gde se kod izvršava od toga kada stranica postaje interaktivna.","wrong":[]},"re13":{"title":"Optimistic UI i povratak unazad","prompt":"Korisnik optimistično promeni status reda, ali server odbije zahtev. Kako projektuješ uspeh, rollback i konkurentne izmene?","why":"Optimistic UI je produktna odluka. Za nepovratne ili rizične operacije često je primerenija jasna potvrda sa servera.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Navedi pending stanje, vezu sa mutation-om, ponovno učitavanje i pravilo za konflikt.","checks":["Razdvaja potvrđeni i optimistični prikaz i ima rollback/error tok.","Razmatra dva brza zahteva i identitet izmene.","Poznaje ulogu useOptimistic/useActionState bez obećanja da rešavaju ceo API ugovor."],"steps":["Optimizam privremeno prikazuje očekivani ishod pre server potvrde. Zato moraš znati šta je potvrđeno, a šta još čeka.","Dva brza zahteva mogu učiniti prost rollback na „staru vrednost” pogrešnim. Identitet operacije i pravilo konflikta čuvaju noviju nameru."],"remember":"Brži osećaj UI-ja traži dobar neuspešan tok.","wrong":[]},"re14":{"title":"Custom hook bez preterivanja","prompt":"Ista logika paginacije javlja se na tri ekrana. Kada praviš hook, a kada običnu funkciju ili komponentu?","why":"Dobra granica smanjuje dupliranje i čuva razumljivost. Deljenje hook logike ne znači automatski deljenje state instance.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Predloži mali ugovor sa ulazima, izlazima i jasno definisanim resetom stranice.","checks":["Hook za deljenje React state/effect logike.","Obična funkcija za čistu transformaciju bez hookova.","Ne pravi preopštu apstrakciju sa mnogo zastavica."],"steps":["Čisto filtriranje ili računanje može biti obična funkcija i lako se proverava bez React okruženja.","Hook ima smisla kada deliš React state ili životni tok. Njegov poziv u dve komponente normalno pravi dve instance tog state-a."],"remember":"Deljenje implementacije ne znači automatski deljenje podataka.","wrong":[]},"we01":{"title":"Button ili klikabilni div","prompt":"Za akciju otvaranja dijaloga, koji je najbolji početak?","why":"Native button već daje semantiku, fokus i osnovnu aktivaciju tastaturom. Akcija i navigacija nisu ista stvar.","pitfall":"ARIA ne dopunjava automatski ponašanje tastature.","options":["<button type=\\"button\\"> sa smislenim nazivom","<div onClick> bez dodataka","<a href=\\"#\\"> u svim slučajevima","Slika sa click handlerom bez naziva"],"steps":["Browser već zna da button predstavlja akciju, ume da ga fokusira i aktivira odgovarajućim tasterima.","Sa div elementom bi morao ponovo da obezbediš semantiku i ponašanje. Za običnu akciju nema potrebe da to ručno gradiš."],"remember":"Za standardnu akciju počni od standardnog HTML elementa.","wrong":["Klik mišem sam ne obezbeđuje tastaturu, fokus i semantiku dugmeta.","Link je prvenstveno navigacija; href=\\"#\\" može doneti i neželjenu promenu pozicije.","Slika bez pristupačnog naziva i ponašanja ne prenosi ispravno akciju."]},"we02":{"title":"Pristupačan dijalog i forma","prompt":"Koje stvari ručno proveravaš pri otvaranju modala sa formom?","why":"Vizuelno dobar modal nije dovoljan. Provera tastaturom i odgovarajućom asistivnom tehnologijom hvata drugačije greške od screenshota.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Prođi Tab/Shift+Tab, potvrdu, grešku validacije, zatvaranje i povratak fokusa.","checks":["Fokus prelazi u dijalog, ostaje u njegovom toku i vraća se na okidač.","Postoje naziv, label-e, čitljive greške i tastaturna kontrola.","Obrađuje Escape, background interakciju i razumljive potvrde prema zahtevu."],"steps":["Otvoren dijalog menja mesto na kojem korisnik radi. Fokus mora da prati tu promenu da bi tastatura imala smislen tok.","Greška treba da bude povezana sa poljem i dostupna bez oslanjanja samo na boju. Posle zatvaranja korisnik treba da nastavi sa odgovarajućeg mesta."],"remember":"Proveri ceo tok tastaturom, uključujući neuspeh i izlazak.","wrong":[]},"we03":{"title":"CSS layout i cascade","prompt":"Objasni kada biraš Grid, kada Flexbox i kako dijagnostikuješ CSS pravilo koje ne deluje.","why":"To su smernice, ne zabrane. Rešenje treba proveriti sa realnom dužinom teksta, zoom-om i raspoloživom širinom.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":".cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr)); gap: 1rem; }","checks":["Grid razmatra za dve dimenzije, Flexbox za tok po jednoj osi.","Proverava cascade, specificity, layer, source order i computed styles.","Ne rešava sve novim !important."],"steps":["Flexbox prirodno raspoređuje elemente duž glavne ose, a Grid povezuje redove i kolone u zajedničku mrežu.","Kada stil ne važi, computed styles pokazuju pobednika cascade-a. Tek kada znaš zašto je pravilo izgubilo, možeš napraviti ciljanu izmenu."],"remember":"DevTools objašnjava uzrok; !important ga često samo prekrije.","wrong":[]},"we04":{"title":"Responsive nije samo media query","prompt":"Dugačak preveden naslov i tabela lome mobilni prikaz. Kako proveravaš i rešavaš problem?","why":"Breakpoints treba da prate sadržaj i zadatak korisnika. Mobilna kartica mora zadržati ista pravila filtriranja i sortiranja.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Proveri najmanje 320 px, tablet, desktop, 200% zoom i jedan znatno duži prevod.","checks":["Testira uzak ekran, zoom, duži tekst i dodirne kontrole.","Razume min-width: 0, prelamanje i prikladno skrolovanje tabele.","Čuva informacije, redosled i pristupačnost umesto slepog skrivanja kolona."],"steps":["Responsive prikaz zavisi i od minimalne širine sadržaja, jezika i korisničkog zoom-a, ne samo od naziva uređaja.","Ako mobile sakrije informaciju ili primeni drugo sortiranje, raspored može izgledati uredno a funkcionalno biti pogrešan."],"remember":"Promeni raspored, uz očuvanje značenja i pravila podataka.","wrong":[]},"we05":{"title":"fetch i HTTP greške","prompt":"Server odgovori HTTP 404. Šta fetch tipično radi?","why":"Mrežni neuspeh i HTTP neuspešan status nisu ista stvar. Obrada mora predvideti i parsiranje tela.","pitfall":"Ni JSON telo greške nije garantovano validno ili u očekivanoj šemi.","options":["Promise se razreši Response objektom; proveravaš response.ok/status.","Uvek odbacuje Promise kao za mrežni prekid.","Automatski pretvara odgovor u null.","Automatski ponavlja zahtev dok ne dobije 200."],"steps":["fetch je uspeo da dobije HTTP odgovor i kada server kaže „nije pronađeno”. To nije isto što i nemogućnost da se dođe do servera.","Zato prvo proveravaš status prema ugovoru, a zatim obrađuješ telo. Status 404 može imati HTML umesto očekivanog JSON-a."],"remember":"Mreža, HTTP status i format odgovora su tri različite provere.","wrong":["HTTP greška se ne odbacuje automatski kao mrežni prekid.","fetch vraća Response; nije automatski mapiranje na null.","Automatski retry mora posebno da se implementira i smisleno ograniči."]},"we06":{"title":"401, 403 i stari zahtevi","prompt":"API vrati 401 ili 403. Kada odjavljuješ korisnika i kako izbegavaš da stari odgovor prekine novu sesiju?","why":"Jednostavan interceptor može napraviti neželjene odjave. Potrebni su ugovor, identitet zahteva i smislen oporavak.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Proveri: da li je zahtev slao aktuelni token, da li je odgovor iz aktuelne sesije i šta endpoint garantuje.","checks":["Razlikuje neuspelu autentikaciju i nedovoljnu dozvolu prema API ugovoru.","401 povezuje sa aktuelnom autentifikovanom sesijom/tokenom.","Ne radi globalni logout za svaki 403, login poziv ili zastareli odgovor."],"steps":["401 obično znači da zahtev nema prihvatljivu autentikaciju, a 403 da odgovarajuća dozvola nije data. Konačno ponašanje proveri u API ugovoru.","Odgovor iz prethodne sesije ne sme slepo da poništi noviju prijavu. Zato ga povezuješ sa tokenom ili identitetom sesije koja je poslala zahtev."],"remember":"Status obrađuj zajedno sa kontekstom zahteva.","wrong":[]},"we07":{"title":"XSS, CSRF i čuvanje sesije","prompt":"Uporedi rizike skripti u stranici i automatskog slanja cookies. Zašto nema univerzalnog odgovora „token uvek ovde”?","why":"Strategija zavisi od arhitekture i pretnji. HttpOnly cookie ne uklanja posledice izvršavanja zlonamernog koda u stranici.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Počni od threat model-a i API ugovora, pa definiši skladištenje, životni vek, rotaciju i zaštite.","checks":["Razume da XSS može izvršavati radnje u aplikaciji i čitati JS-dostupne podatke.","Cookie autentifikacija traži odgovarajuću CSRF zaštitu; HttpOnly sprečava JS čitanje cookie-ja.","Razmatra SameSite, CSP, sanitizaciju, server autorizaciju i konkretan tok."],"steps":["XSS izvršava neželjeni kod u kontekstu aplikacije. CSRF koristi okolnost da browser neke kredencijale šalje automatski.","HttpOnly onemogućava JS čitanje cookie vrednosti, ali zlonameran kod i dalje može praviti zahteve iz aplikacije. Zato zaštite moraju pokriti više slojeva."],"remember":"Jedna zastavica ili lokacija tokena ne rešava ceo threat model.","wrong":[]},"we08":{"title":"Frontend env nije tajna","prompt":"Build promenljiva postane deo JavaScript paketa. Da li prefiks ili .env fajl čuvaju taj API ključ od korisnika?","why":"Javni identifikator može imati legitimnu klijentsku upotrebu uz ograničenja. Prava tajna ne pripada isporučenom bundle-u.","pitfall":"Git ignorisanje i zaštita server tajne nisu ista zaštita kao sadržaj browser paketa.","options":["Ne. Podatak poslat browseru može biti pregledan; tajne se čuvaju na serveru.","Da, ako naziv sadrži SECRET.","Da, ako .env nije commitovan.","Da, minifikacija ga kriptografski štiti."],"steps":["Browser mora dobiti klijentski JavaScript da bi ga izvršio. Korisnik može pregledati taj kod i zahteve koje pravi.","Promenljiva može biti privatna na build mašini, a zatim ubačena kao literal u javno isporučeni paket. Njeno poreklo ne menja rezultat."],"remember":"Što pošalješ browseru, smatraj dostupnim korisniku.","wrong":["Naziv SECRET ne stvara kontrolu pristupa nad isporučenim stringom.","Git ignore sprečava commit fajla, ali ne sprečava bundler da ugradi vrednost.","Minifikacija skraćuje kod; nije kriptografsko skrivanje tajne."]},"we09":{"title":"Cache i zastareli resursi","prompt":"Objasni razliku Cache-Control, ETag i klijentskog query cache-a. Zašto korisnik može videti staru verziju?","why":"Keširanje treba projektovati po vrsti resursa i invalidaciji. Nasumično dodavanje query string-a nije potpuna strategija.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Prvo pregledaj response headers i stvarni izvor resursa u Network panelu.","checks":["Razdvaja HTTP cache, aplikacioni cache i eventualni Service Worker.","ETag povezuje sa uslovnom validacijom.","Razmatra fingerprint resurse i politiku HTML dokumenta/deploy-a."],"steps":["HTTP cache odlučuje da li odgovor može biti ponovo korišćen ili treba proveriti promenu. ETag pomaže uslovnoj validaciji verzije resursa.","Query cache čuva aplikacione podatke i svoja pravila svežine. Service Worker može dodati još jedan sloj, pa prvo utvrdi koji sloj vraća star sadržaj."],"remember":"Pre invalidacije identifikuj koji cache poseduje problem.","wrong":[]},"we10":{"title":"CORS nije autorizacija","prompt":"Zašto omogućavanje CORS-a ne znači da je API bezbedan? Može li frontend popraviti pogrešnu server CORS politiku?","why":"Klijent van browsera nije ograničen istim CORS pravilom. Server mora zaštititi svaki zahtev prema svom ugovoru.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Proveri origin, preflight, credentials i odgovarajuće server zaglavlje.","checks":["CORS je browser pravilo za čitanje cross-origin odgovora.","Autentikacija i autorizacija se sprovode na serveru.","Ne predlaže no-cors kao način čitanja običnog zaštićenog JSON odgovora."],"steps":["CORS ograničava browser skriptu u čitanju nekih odgovora sa drugog origin-a. Ne utvrđuje ko sme da izvrši poslovnu operaciju.","Server i dalje mora proveriti identitet i dozvolu. no-cors ne pretvara zabranjeni JSON odgovor u normalno čitljiv podatak za tvoju aplikaciju."],"remember":"CORS je browser granica pristupa odgovoru, a ne server autorizacija.","wrong":[]},"li01":{"title":"Gde stanje treba da živi?","prompt":"Razvrstaj: otvoren modal, URL filter, autentifikacioni identitet, lista sa servera i nacrt forme.","why":"Jedan globalni store za sve često sakriva odgovornost. Ni više biblioteka za istu svrhu nije automatski bolje.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Modal: lokalno; deljivi filter: URL; server lista: query sloj; nacrt: forma; sesija: dogovorena auth granica.","checks":["Razlikuje lokalno UI, URL, deljeno klijentsko i serversko stanje.","Server cache ne kopira bez potrebe u nekoliko store-ova.","Za odluku navodi životni vek, vlasništvo i deljenje."],"steps":["Lokalni modal živi uz komponentu kojoj je potreban. Filter koji treba kopirati u link ima dobar razlog da živi u URL-u.","Serverska lista ima svežinu, greške i invalidaciju, a nacrt forme privremene korisničke izmene. Različiti životni vekovi traže jasno vlasništvo."],"remember":"Vrsta podatka i njegov životni vek određuju mesto čuvanja.","wrong":[]},"li02":{"title":"Redux Toolkit i immutable update","prompt":"Zašto createSlice reducer može izgledati mutirajuće, dok ručna mutacija React state-a pravi problem?","why":"Sintaksa izmene draft-a ne znači da je dozvoljeno menjati bilo koji objekat bilo gde. Razumi granicu biblioteke.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"// U createSlice reducer-u:\\nstate.items.push(action.payload);\\n// Van draft konteksta prati immutable ugovor.","checks":["Zna da RTK koristi Immer draft u odgovarajućem reducer kontekstu.","Razlikuje draft izmene i proizvoljnu mutaciju običnog objekta.","Reducers ostaju bez nedeterminističkih side effects."],"steps":["Immer prati izmene draft-a i od njih pravi novu nepromenljivu strukturu. Zato takva reducer sintaksa može izgledati kao obična mutacija.","Kada nema Immer draft konteksta, ista sintaksa zaista menja postojeći objekat. Side effects poput mrežnog poziva nisu posao čistog reducer-a."],"remember":"Razumi mehanizam alata pre nego što preneseš njegov obrazac drugde.","wrong":[]},"li03":{"title":"Saga: takeLatest i otkazivanje","prompt":"Pretraga koristi takeLatest. Šta se otkazuje i zašto to ne garantuje da je mrežni zahtev ili server posao prestao?","why":"Task cancellation i prekid mreže nisu ista operacija. Server može već obrađivati zahtev.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Objasni finally/cancelled tok, adapter ka transportu i slučaj kada server ipak potvrdi operaciju.","checks":["Razume otkazivanje prethodnog Saga task-a.","Proverava da li transport podržava i dobija AbortSignal/cancel.","Za mutacije razmatra idempotency i stanje na serveru."],"steps":["takeLatest prekida prethodni odgovarajući Saga task kada stigne nova akcija. To sprečava nastavak njegovog normalnog toka.","Transport i server imaju sopstveni životni ciklus. Potrebno je povezati otkazivanje, a kod mutacija proveriti da li je operacija već stigla do servera."],"remember":"Prekinut task ne dokazuje poništenu server operaciju.","wrong":[]},"li04":{"title":"RTK Query ili TanStack Query","prompt":"Koji problem rešavaju? Uporedi ih sa ručnim useEffect + fetch i obrazloži izbor u postojećem Redux projektu.","why":"Za ovaj trening ovo su korisne dopunske teme. To nije tvrdnja da svaki posao traži obe biblioteke.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Objasni query key sa svim parametrima, stale podatke, refetch i invalidaciju posle save-a.","checks":["Navodi cache ključeve, invalidaciju, deduplikaciju i mutation tok.","Bira prema postojećoj arhitekturi i potrebama, ne samo popularnosti.","Uvažava podešavanja i izbegava nekontrolisano uvođenje dva izvora istine."],"steps":["Server state ima više problema od samog čuvanja rezultata: ko deli zahtev, koliko podaci važe i kada se učitavaju ponovo.","Query biblioteke daju obrasce za te tokove. Izbor u postojećem Redux projektu uključuje integraciju i znanje tima, a ne samo novi API koji ti se dopada."],"remember":"Biraj jedan jasan model vlasništva i invalidacije podataka.","wrong":[]},"li05":{"title":"Axios interceptor i refresh","prompt":"Kako izbegavaš petlju osvežavanja i mnogo paralelnih refresh poziva?","why":"Refresh je dogovoren auth protokol, a ne univerzalni trik. Potrebna su pravila greške i prestanka retry-a.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Nacrtaj tok: zahtev → odgovarajući 401 → jedan refresh → najviše jedan retry → jasna greška.","checks":["Ograničava retry i izuzima refresh/login putanju.","Deli jedan aktivan refresh Promise kada ugovor to dopušta.","Vezuje retry za aktuelnu sesiju i čisti interceptor pri odgovarajućem teardown-u."],"steps":["Ako svaki neuspešan zahtev pokrene refresh, više paralelnih poziva može napraviti gomilu osvežavanja i neusaglašene tokene.","Deljenje jednog procesa osvežavanja i ograničen retry rešavaju koordinaciju. Zasebno moraš sprečiti da taj tok oživi već odjavljenu ili zamenjenu sesiju."],"remember":"Auth retry mora imati granicu i identitet sesije.","wrong":[]},"li06":{"title":"Formik, RHF i server validacija","prompt":"Velika forma ima sinhronu validaciju, proveru na serveru i MUI polja. Šta proveravaš pre izbora ili migracije biblioteke?","why":"Formik koji već poznaješ je važan kontekst. RHF i schema validacija su dopuna, ne obavezni rewrite.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Definiši validation timing, submit/pending/duplicate submit, server errors i reset posle uspeha.","checks":["Mapira field errors i form errors uz pristupačan prikaz.","Razmatra način upravljanja poljima, reset, dirty stanje i performanse.","Server ostaje autoritet; ne menja alat bez dokazane koristi."],"steps":["Biblioteka forme pomaže da koordiniraš vrednosti, validaciju i submit. Ne određuje automatski koja poslovna pravila server prihvata.","Pre migracije izmeri konkretan problem i proveri integraciju MUI polja, reset, server greške i pristupačnost. Nova biblioteka nije cilj sama po sebi."],"remember":"Prvo ugovor forme, zatim izbor alata.","wrong":[]},"li07":{"title":"Client-side tabela: tačan redosled","prompt":"Za ceo skup koji je već u browseru, koji tok daje globalno ispravno sortiranje?","why":"Sortiranje posle slice-a menja redosled samo jedne strane. Serverska paginacija traži odgovarajući server ugovor.","pitfall":"Desktop i mobile moraju deliti sort vrednosti, komparator i smer.","options":["Filter → sort celog filtriranog skupa → pagination.","Pagination → sort samo trenutne strane.","Sort samo mobilnih kartica.","Sort samo prikazanih stringova bez obzira na značenje."],"steps":["Ako prvo uzmeš deset redova, komparator nikada neće videti red sa druge strane koji bi trebalo da bude prvi.","Zato se klijentsko sortiranje radi nad celim filtriranim skupom, pa tek onda seče stranica. Kod serverske paginacije posao mora obuhvatiti ceo server skup."],"remember":"Ne možeš globalno sortirati samo ono što si već isekao.","wrong":["Dobijaš redosled unutar strane, a ne redosled celog rezultata.","Mobile i desktop bi mogli prikazati različite poslovne rezultate.","Formatirani tekst, recimo valuta ili datum, ne mora imati isti poredak kao izvorna vrednost."]},"li08":{"title":"react-intl i stvarni podaci","prompt":"Objasni pluralizaciju, datume, valute i fallback. Zašto spajanje prevedenih fragmenata može biti problem?","why":"i18n obuhvata pravila jezika i format podataka. Broj za računanje ne treba uzimati iz formatiranog teksta.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Primer srpske poruke: {count, plural, one {# stavka} few {# stavke} other {# stavki}}","checks":["Koristi celovite poruke i ICU plural prema potrebi.","Locale formatiranje razlikuje od skladištenja datuma/brojeva.","Testira duži tekst, nedostajuću poruku i vremensku zonu."],"steps":["Jezici imaju različit red reči i pravila množine. Celovita poruka prevodiocu daje potreban kontekst.","Datum i novac u podacima treba da ostanu pouzdane vrednosti, dok je locale format stvar prikaza. Formatirani string nije dobar izvor za računanje."],"remember":"Odvoji vrednost podatka od jezičkog prikaza.","wrong":[]},"li09":{"title":"Routing, loader i error UI","prompt":"Za admin stranicu sa URL filterima i nested rutama, kako povezuješ učitavanje, greške, back/forward i dozvole?","why":"React Router ima različite načine upotrebe. Odgovor prilagodi konkretnoj verziji i režimu projekta.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Prođi direktno otvaranje URL-a, refresh, back, nepostojeći id i zabranjenu operaciju.","checks":["URL stanje ima definisanu parsiranje/serijalizaciju.","Razume nested route i odgovarajući loading/error tok izabranog moda.","Frontend guard poboljšava UX; server proverava dozvole."],"steps":["URL filter predstavlja stanje koje browser istorija i direktan link treba da mogu ponovo da stvore. Zato moraš definisati validne parametre i fallback.","Ruta zatim koordinira sadržaj i podatke prema režimu router-a. Skrivanje dugmeta ili redirect u klijentu ne sprečava direktan neovlašćen API poziv."],"remember":"Dobar route tok obuhvata i direktno otvaranje, povratak i neuspeh.","wrong":[]},"li10":{"title":"Velika tabela i izbor biblioteke","prompt":"100.000 redova, selekcija, filteri i izvoz. Šta pitaš pre izbora grida i gde deliš posao sa serverom?","why":"Virtualizacija smanjuje DOM, ali ne rešava prenos ogromnog skupa, memoriju ni tačnost server pretrage.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Napiši query ugovor, total count/next cursor, stable id, selection pravila i limit izvoza.","checks":["Pita za veličinu podataka, dozvole, latency, licencu i pristupačnost.","Razdvaja virtualizaciju DOM-a od server paginacije/filtera/sortiranja.","Izvoz i selekcija imaju jasan ugovor za ceo skup ili trenutnu stranu."],"steps":["Virtualizacija prikazuje samo deo DOM redova, ali svi preuzeti podaci i dalje troše mrežu i memoriju.","Server paginacija smanjuje taj trošak, ali traži ugovor za sortiranje, selekciju i izvoz. „Select all” mora precizno reći da li znači stranu ili ceo rezultat."],"remember":"Razdvoji veličinu DOM-a, veličinu prenosa i značenje operacije.","wrong":[]},"qa01":{"title":"Testiraj korisničko ponašanje","prompt":"Kako testiraš formu koja snimi korisnika i prikaže potvrdu bez oslanjanja na internu implementaciju?","why":"Test treba da otkrije pokvareno ponašanje i da preživi razuman refactor interne strukture.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Arrange realističan odgovor → user popunjava formu → submit → vidi potvrdu; poseban test za server grešku.","checks":["Nalazi polja i dugmad po ulozi/nazivu i unosi podatke kao korisnik.","Čeka smislen async rezultat i proverava zahtev/vidljiv ishod.","Pokriva neuspeh i validaciju, ne samo srećan put."],"steps":["Ako test traži dugme po nazivu i prolazi stvaran unos, on proverava ugovor koji korisnik vidi.","Test interne funkcije ili state promenljive može ostati zelen i kada dugme prestane da radi. Proveri vidljivi ishod, kao i smislen neuspešan tok."],"remember":"Test treba da padne kada je korisnički zadatak pokvaren.","wrong":[]},"qa02":{"title":"Unit, integration i E2E","prompt":"Rasporedi provere za sort komparator, formu sa mock API-jem i stvarni tok prijave. Koje granice ima svaki dokaz?","why":"Dobar izbor test sloja daje najbržu korisnu povratnu informaciju za rizik koji proveravaš.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Navedi i šta test nije dokazao: stvarni auth provider, prava mreža, dozvole i deploy konfiguracija.","checks":["Čistu funkciju proverava malim unit testom.","Interakciju komponenti i ugovor sa mockom proverava integraciono.","Stvarni povezani tok proverava E2E; ne izjednačava mock sa produkcijom."],"steps":["Čista funkcija traži mali i brz test granica. Povezanost forme, validacije i zahteva traži veći obuhvat.","E2E može proveriti stvarnu integraciju, ali njegov uspeh važi za testirano okruženje, nalog i scenario. Mock ne potvrđuje ponašanje stvarnog backend-a."],"remember":"Svaki sloj daje određen dokaz i ostavlja određene nepoznanice.","wrong":[]},"qa03":{"title":"Flaky E2E bez sleep-a","prompt":"Test ponekad pada na sporijem CI-u. Kako istražuješ i popravljaš?","why":"Flakiness može značiti loš test ili realnu trku u aplikaciji. Dokazi treba da razdvoje ta dva slučaja.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Počni od neuspelog trace-a i zabeleži koje stanje je nedostajalo u trenutku akcije.","checks":["Koristi trace, screenshot i mrežne događaje za reprodukciju.","Čeka vidljivo stanje i stabilan locator umesto fiksnog sleep-a.","Izoluje podatke, vreme i spoljne servise; retry ne predstavlja kao popravku."],"steps":["Fiksni sleep pretpostavlja trajanje koje se menja na CI-u. Čekanje očekivanog stanja prati stvarni uslov spremnosti.","Trace pokazuje da li je UI kasnio, zahtev zakazao ili su podaci deljeni između testova. Tek uzrok određuje da li menjaš test ili aplikaciju."],"remember":"Ponavljanje neuspešnog testa nije zamena za dijagnozu.","wrong":[]},"qa04":{"title":"Core Web Vitals","prompt":"Koja grupa odgovara aktuelnom osnovnom skupu metrika koji je proveren za ovaj trening?","why":"LCP prati prikaz glavnog sadržaja, INP odziv na interakcije, a CLS vizuelnu stabilnost.","pitfall":"Jedan Lighthouse rezultat ne predstavlja iskustvo svih stvarnih korisnika; INP traži interakcije.","options":["LCP, INP, CLS","FCP, FID, broj komponenti","TTFB, Lighthouse score, broj npm paketa","Samo veličina bundle-a"],"steps":["LCP se odnosi na glavni vidljivi sadržaj, INP na korisnikov doživljaj odziva, a CLS na neočekivano pomeranje rasporeda.","Zajedno pokrivaju različite aspekte iskustva. Ipak, nisu sva važna svojstva kvaliteta aplikacije svedena na ove tri metrike."],"remember":"Učitavanje, odziv i stabilnost: tri različita pitanja.","wrong":["FID je zamenjen INP-om u osnovnom skupu; broj komponenti nije Core Web Vital.","Ovo mogu biti korisni podaci ili alati, ali nisu navedeni osnovni skup.","Bundle veličina je ulaz u analizu, a ne potpuna mera korisničkog iskustva."]},"qa05":{"title":"Performanse: hipoteza pa merenje","prompt":"Admin ekran je spor. Kako razlikuješ mrežni problem, skupo računanje, previše DOM-a i React render?","why":"Optimizacija bez dijagnoze često dodaje kompleksnost. Lab rezultat i terenski podaci imaju različitu ulogu.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Zabeleži: tok korisnika, trajanje, uređaj, veličinu podataka, trag, promenu i izmereni ishod.","checks":["Pravi merljivu reprodukciju na relevantnom uređaju/skupu podataka.","Koristi Network, Performance i React Profiler za različita pitanja.","Menja jednu hipotezu i poredi pre/posle, uključujući funkcionalne regresije."],"steps":["Spor endpoint ne popravljaš memoizacijom komponente. Veliku DOM listu ne rešava samo brži server.","Alati prikazuju različite delove troška. Poređenje istog toka pre i posle promene proverava da li je hipoteza bila korisna."],"remember":"Pronađi deo trajanja koji stvarno menjaš.","wrong":[]},"qa06":{"title":"CI i kvalitet build-a","prompt":"Koje provere ima smisla pokrenuti pre spajanja React/TS promene i kako skaliraš obim?","why":"Ne mora svaki mali CSS PR pokretati sve skupe tokove, ali provera ne sme izostaviti stvarni rizik promene.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Definiši obavezne brze provere i dodatne provere za auth, podatke, routing i deploy promene.","checks":["Proverava tipove, relevantna statička pravila i testove.","Pokreće build i kritične tokove prema riziku promene.","Razlikuje uspeh komande od poslovne i produkcione ispravnosti."],"steps":["Type-check hvata deo neslaganja ugovora; testovi proveravaju očekivano ponašanje, a build proverava put pakovanja.","Kritična auth ili API promena traži više dokaza od lokalne vizuelne izmene. Pravila skaliraj prema uticaju i mogućem kvaru."],"remember":"Provera treba da odgovara riziku, ne samo navici.","wrong":[]},"qa07":{"title":"Git konflikt i bezbedan review","prompt":"U konfliktu oba branch-a menjaju API mapiranje. Kako rešavaš i proveravaš rezultat?","why":"Rešen tekstualni konflikt ne znači rešen semantički konflikt. Potrebno je proveriti krajnje ponašanje.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Navedi konkretan primer dva ispravna pojedinačna patch-a koji zajedno prave grešku.","checks":["Čita obe namere i trenutni API ugovor.","Ne bira automatski ours/theirs za celu datoteku.","Pregleda završni diff i proverava tokove koje obe promene pokrivaju."],"steps":["Git može sastaviti tekst koji se uredno parsira, ali pogrešno spaja dve poslovne namere.","Čitanje obe promene i zajedničkog ugovora sprečava da jedna strana tiho poništi drugu. Završni diff je novi rezultat koji zasebno pregledaš."],"remember":"Tekstualno čist merge može imati semantičku grešku.","wrong":[]},"qa08":{"title":"Dependency odluka u 2026.","prompt":"Kako biraš novu biblioteku i obrazlažeš zašto je ne uvodiš u neki postojeći projekat?","why":"Biblioteke su promenljive. Trening proverava model odluke, ne pamćenje trenutnog kataloga paketa.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Uporedi održavanje postojećeg rešenja, mali dodatak i migraciju; zapiši razlog i kriterijum ponovne procene.","checks":["Polazi od konkretnog problema, održavanja, licence, a11y i kompatibilnosti.","Proverava aktuelnu dokumentaciju i trošak bundle-a/migracije.","Ne izjednačava popularnost, starost ili broj zvezdica sa kvalitetom."],"steps":["Nova biblioteka donosi i funkcionalnost i obavezu održavanja. Procenjuješ API, podršku, licencu, pristupačnost i trošak integracije.","U postojećem stabilnom modulu korist mora opravdati regresioni rizik i obuku. Popularnost je signal za istraživanje, a ne konačan dokaz."],"remember":"Uvođenje zavisnosti je tehnička odluka sa dugoročnim troškom.","wrong":[]},"sr01":{"title":"Arhitektura admin modula","prompt":"Projektuj novi modul za korisnike: lista, filteri, detalji, edit forma i različite dozvole.","why":"Ne postoji jedina ispravna struktura foldera. Važniji su jasna odgovornost, promenljivost i mogućnost provere.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Počni od korisničkih tokova i ugovora, pa nacrtaj module i podatke koje svaki poseduje.","checks":["Definiše granice UI, domena, API mapiranja i query/state sloja.","Planira loading/empty/error, a11y, i18n i direktno otvaranje rute.","Opisuje test strategiju i izbegava preopšti framework bez potrebe."],"steps":["Arhitektura treba da olakša promene u korisničkim tokovima i ugovorima. Sama imena foldera nisu dovoljan odgovor.","Pokaži gde podatak ulazi, ko njime upravlja i gde se greška pretvara u UI stanje. Zatim objasni kako bi proverio ključni tok."],"remember":"Granice i odgovornost objasni kroz konkretan scenario.","wrong":[]},"sr02":{"title":"API ugovor i nepoznanice","prompt":"Backend još nije spreman. Kako radiš frontend bez lažnog zaključka da je integracija potvrđena?","why":"Senior komunikacija jasno odvaja potvrđen lokalni tok od otvorenih backend/deploy pitanja.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Napiši: šta je potvrđeno, kojim dokazom, šta nije i koji sledeći test zatvara nepoznanicu.","checks":["Dogovara šeme, statuse, paginaciju, dozvole i greške.","Mock izveden iz ugovora proverava frontend, a ne stvarni server.","Vodi listu integracionih nepoznanica i planira završne provere."],"steps":["Mock omogućava razvoj prema dogovoru, ali će dati upravo odgovor koji si mu zadao. Ne dokazuje da ga pravi server daje.","Zato uz lokalne rezultate vodiš listu pitanja za integraciju: realne dozvole, paginacija, error šeme, auth i deploy."],"remember":"Jasno navedi šta dokaz obuhvata, a šta tek treba proveriti.","wrong":[]},"sr03":{"title":"Code review po riziku","prompt":"Pregledaš veliki PR sa UI promenama i auth interceptorom. Kako biraš redosled i formulišeš nalaz?","why":"Kvalitet review-a meri se korisnim i tačnim nalazima, ne brojem komentara.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Primer: stari 401 nakon nove prijave odjavljuje aktuelnog korisnika; pokaži tok i predloži vezivanje za sesiju.","checks":["Prvo proverava gubitak podataka, bezbednost i promenu ugovora.","Nalaz sadrži konkretan trigger, dokaz, posledicu i smer popravke.","Posle nalaza proverava i preostali diff; odvaja stil od funkcionalnog problema."],"steps":["Ograničeno vreme review-a prvo usmeravaš na mesta gde kvar ima najveću posledicu. Auth promena može biti rizičnija od mnogo CSS linija.","Konkretan trigger i posledica čine nalaz proverljivim. Posle prve greške nastavi pregled: jedan nalaz ne garantuje da je ostatak bezbedan."],"remember":"Nalaz treba da omogući reprodukciju i korisnu odluku.","wrong":[]},"sr04":{"title":"Priča o tehničkoj odluci","prompt":"Izaberi svoj projekat. Objasni problem, dve alternative, odluku, svoju ulogu i proverljiv rezultat.","why":"Godine iskustva pomažu kontekstu, ali intervju traži dubinu odgovornosti i obrazložene odluke.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Struktura: situacija → ograničenja → alternative → odluka → tvoj doprinos → rezultat → šta bi danas promenio.","checks":["Razdvaja lični doprinos i doprinos tima.","Navodi realne alternative i kompromis.","Koristi stvarne dokaze; ne izmišlja procente ili poslovni uticaj."],"steps":["Intervjuer traži da vidi kako si razmišljao u stvarnim ograničenjima, a ne samo koji stack je tim koristio.","Razlikovanje lične odluke, timskog rada i stvarno izmerenog ishoda čini priču pouzdanom. Ako nemaš metriku, navedi tačno koji dokaz imaš."],"remember":"Dokaziv rezultat je jači od impresivnog, neproverenog procenta.","wrong":[]},"sr05":{"title":"Mentorstvo bez preuzimanja zadatka","prompt":"Kolega stalno uvodi Effect za izveden state. Kako daješ feedback i proveravaš da je obrazac razumeo?","why":"Mentorstvo treba da poveća samostalnost. Samostalno prepisivanje tuđeg PR-a ne proverava razumevanje.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Pitaj koji spoljašnji sistem Effect sinhronizuje; zatim zajedno uklonite redundantni state.","checks":["Pokazuje jedan konkretan primer i posledicu.","Traži da kolega predloži popravku i primeni je na drugom primeru.","Dogovara smernicu i prati sledeću promenu bez omalovažavanja."],"steps":["Konkretan primer povezuje feedback sa posledicom u kodu. Pitanje navodi kolegu da sam objasni model, umesto da samo prihvati ispravku.","Novi primer proverava da li može preneti pravilo. Uklonjen bug u jednom PR-u još ne potvrđuje da je obrazac naučen."],"remember":"Mentorstvo treba da poveća tuđu samostalnost.","wrong":[]},"sr06":{"title":"Rok, procena i delegiranje","prompt":"Tim od nekoliko ljudi ima nejasan feature i kratak rok. Kako planiraš bez lažne preciznosti?","why":"Profesionalna procena je raspon sa pretpostavkama kada nepoznanice to zahtevaju, ne obećanje bez osnova.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Daj primer kratkog spike-a, faze isporuke i jednog jasnog definition of done.","checks":["Razdvaja poznato, nepoznato, zavisnosti i minimalni korisni obim.","Delegira celovite delove sa kriterijumima prihvatanja i review granicama.","Procenu ažurira dokazima i rano komunicira rizik."],"steps":["Nejasan zadatak ima skrivene zavisnosti koje jedna precizna cifra lako sakrije. Kratko istraživanje može znatno promeniti procenu.","Delegiranje sa kriterijumima prihvatanja daje kolegi samostalnost i jasan završetak, dok review granice štite integraciju."],"remember":"Procena ima pretpostavke; plan se menja kada dobiješ nove dokaze.","wrong":[]},"sr07":{"title":"Produkcioni incident","prompt":"Posle deploy-a deo korisnika ne može da sačuva formu. Koji su prvi koraci?","why":"Brza spekulativna izmena može povećati incident. Prvo zaštiti korisnike i pronađi konkretan failure tok.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Objasni kako bi proverio stale bundle, API ugovor, dozvole i dupli submit.","checks":["Proceni obim i uticaj; razmatra rollback/feature flag prema ovlašćenju.","Prikuplja bezbedne logove, mrežni tok, verziju i reprodukciju.","Razdvaja mitigaciju, uzrok i prevenciju; jasno komunicira potvrđene činjenice."],"steps":["Prvi cilj incidenta je smanjenje štete za korisnika. Rollback ili isključivanje funkcije može kupiti vreme za dijagnozu.","Zatim proveravaš konkretan neuspešan tok i granice uticaja. Trajna popravka i prevencija dolaze kada postoji dovoljno dokaza o uzroku."],"remember":"Odvoji trenutno ublažavanje posledice od dokazivanja uzroka.","wrong":[]},"sr08":{"title":"Kada ne prepisati projekat","prompt":"Predložen je veliki rewrite na novi stack. Kako skeptično, ali pošteno procenjuješ predlog?","why":"Novo nije automatski bolje, a postojeće nije automatski opravdano. Odluku veži za dokaze i granice.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Napiši mali ADR: kontekst, opcije, odluka, posledice i datum/okidač ponovne procene.","checks":["Traži merljiv problem i trošak održavanja sadašnjeg stanja.","Poredi postepeno popravljanje, izdvajanje modula i rewrite.","Računa migraciju podataka/tokova, obuku, regresije i uslove uspeha."],"steps":["Rewrite može ukloniti ozbiljno ograničenje, ali istovremeno mora ponovo stvoriti mnogo ponašanja koje je već ugrađeno u stari sistem.","Poredi alternative po konkretnom problemu i ukupnom trošku. Postepeno izdvajanje može dati korist ranije, a ponekad stvarna ograničenja opravdavaju rewrite."],"remember":"Odluka treba da preživi pošteno poređenje opcija.","wrong":[]},"ai01":{"title":"Zadatak za Codex ili Claude Code","prompt":"Napiši prompt za popravku trke u pretrazi. Šta daješ agentu da bi rezultat mogao da proveri?","why":"Dobar kontekst i provera rezultata smanjuju nejasnoće. Sam duži prompt nije garancija kvaliteta.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Popravi prikaz zastarelog rezultata u SearchPanel-u. Reprodukcija: spor odgovor A stigne posle B. Sačuvaj javni API. Proveri oba redosleda odgovora i otkazivanje. Navedi pokrenute provere i preostale nepoznanice.","checks":["Opisuje stvarni problem, relevantne fajlove/ugovor i ograničen obim.","Daje reprodukciju i kriterijume uspeha.","Traži pregled diff-a, relevantne provere i iskreno navođenje neproverenog."],"steps":["Agent ne može pouzdano pogoditi pravilo koje mu nije dostupno u kodu ili zadatku. Reprodukcija mu daje konkretan problem.","Kriterijumi uspeha i način provere omogućavaju da se rezultat ospori. Završni odgovor treba da kaže šta je zaista pokrenuto i šta nije."],"remember":"Jasan cilj plus proverljiv ishod čine zadatak upotrebljivim.","wrong":[]},"ai02":{"title":"Zeleni AI testovi nisu dovoljan dokaz","prompt":"Agent napiše kod i testove; sve prolazi. Kako proveravaš da testovi mere zahtev, a ne samo implementaciju?","why":"Kod i test mogu deliti istu pogrešnu pretpostavku. Drugi model pomaže review-u, ali nije dokaz sam po sebi.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Zatraži minimalnu reprodukciju, regression test i jedan slučaj koji izgleda slično, ali ne sme biti promenjen.","checks":["Izvodi očekivano ponašanje iz nezavisnog zahteva/ugovora.","Proverava da test pada na stvarnom prethodnom kvaru i pokriva kontra-primer.","Pregleda diff i stvarni tok prema riziku; ne oslanja se samo na završni izveštaj agenta."],"steps":["Ako su i kod i test nastali iz iste pogrešne pretpostavke, međusobno slaganje ne pokazuje da zahtev radi.","Regresioni test treba da prepozna stari kvar, a kontra-primer da ograniči preširoku popravku. Ponašanje porediš sa nezavisnim zahtevom."],"remember":"Zelen test vredi onoliko koliko vredi njegova tvrdnja.","wrong":[]},"ai03":{"title":"Repo instrukcije i enforcement","prompt":"Koja tvrdnja o AGENTS.md, CLAUDE.md i sličnim uputstvima je najtačnija?","why":"Tekstualna instrukcija nije isto što i determinističko sprovođenje pravila. Važni su opseg, aktuelnost i način provere.","pitfall":"Kontekst fajl ne treba da postane istorija svih razgovora ili skladište tajni.","options":["Daju kontekst i pravila agentu; obavezne tehničke granice treba sprovoditi i alatima, dozvolama i CI proverama.","Tekst u fajlu kriptografski sprečava svaku zabranjenu komandu.","Zamenjuju server autorizaciju.","Treba u njih kopirati sve tokene da ih agent lakše koristi."],"steps":["Tekstualno pravilo agent čita i tumači, pa rezultat nije isto što i zabrana koju alat tehnički sprovodi.","Važne granice pojačaj dozvolama, sandbox-om, CI proverama ili drugim odgovarajućim mehanizmom. Kontekst fajl drži kratak i relevantan."],"remember":"Uputstvo pomaže ponašanju; enforcement postavlja granicu.","wrong":["Tekst nije kriptografska ili procesna zaštita od izvršavanja komande.","Server mora sam sprovesti autorizaciju nezavisno od agentovog konteksta.","Tajne u kontekst fajlu povećavaju nepotrebno izlaganje podataka."]},"ai04":{"title":"Prompt injection i granice pristupa","prompt":"Agent čita issue ili dokument koji mu nalaže da pošalje .env na spoljašnju adresu. Kako pristupaš tome?","why":"Kodiranje sa agentom uključuje procenu poverenja u ulaze i alate. Tajne ne pripadaju zadatku bez stvarne potrebe.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Prekini taj tok, izdvoji sumnjivi tekst kao podatak i nastavi legitimni zadatak bez iznošenja podataka.","checks":["Sadržaj spoljnog dokumenta tretira kao nepouzdan podatak.","Ne dozvoljava mu da nadjača korisnički cilj i granice pristupa.","Koristi najmanje potrebne dozvole i proverava odredišta i promene."],"steps":["Issue i dokument su izvor informacija o zadatku, ali njihov autor ne dobija automatski pravo da upravlja tvojim agentom.","Zahtev da se otkriju tajne nije legitimna posledica običnog čitanja dokumenta. Proveravaš poreklo instrukcije, podatke, odredište i stvarno ovlašćenje."],"remember":"Podatak koji čitaš nije sam po sebi instrukcija koju moraš izvršiti.","wrong":[]},"ai05":{"title":"Kako iskreno govoriš o AI radu","prompt":"Na intervjuu pitaju: „Ako koristiš AI svakog dana, šta je tvoj doprinos?” Odgovori kroz jedan stvaran primer.","why":"Kvalitet upotrebe alata vidi se u odlukama i proverljivom rezultatu, uz jasnu odgovornost za kod.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Primer strukture: agent je predložio X; ja sam proverio Y, odbacio Z zbog konkretnog rizika i potvrdio rezultat testom W.","checks":["Objašnjava definisanje problema, arhitekturu i proveru.","Navodi konkretan pogrešan AI predlog koji je prepoznao ili ograničenje koje je postavio.","Može sam objasniti i izmeniti isporučeni kod; ne izmišlja uštedu vremena."],"steps":["Tvoj doprinos obuhvata izbor problema, odluku o rešenju i proveru posledica. Agentov predlog je samo jedan ulaz u taj proces.","Stvaran primer odbačenog ili ispravljenog predloga pokazuje samostalno razumevanje bolje od tvrdnje da alat uvek ubrzava rad."],"remember":"Odgovornost za isporučeni kod traži sposobnost da ga objasniš i promeniš.","wrong":[]},"ai06":{"title":"Učenje uz AI bez preskakanja razumevanja","prompt":"Kako koristiš Codex/Claude kada učiš generics, a želiš samostalno znanje?","why":"Agent može biti tutor i reviewer. Ako odmah napiše ceo odgovor, još nisi proverio da li sam umeš da ga konstruišeš.","pitfall":"Objasni i granice svog rešenja; samo naziv pojma nije potpun odgovor.","solution":"Prompt: Ne rešavaj odmah. Proveri moj pokušaj, pokaži prvi problem i postavi jedno podpitanje. Posle toga daj sličan novi zadatak.","checks":["Prvi pokušaj radi bez rešenja.","Traži jednu smernicu, zatim objašnjava sopstveni kod i testira ga.","Kasnije rešava varijantu bez pomoći i proverava tipove."],"steps":["Prvi samostalni pokušaj otkriva gde zaista nedostaje znanje. Gotovo rešenje to može da prikrije jer deluje razumljivo dok ga čitaš.","Smernica, ispravka i kasniji novi zadatak stvaraju novu proveru. Ako ne možeš ponovo bez pomoći, tema još traži rad."],"remember":"Prepoznavanje rešenja nije isto što i samostalno stvaranje rešenja.","wrong":[]},"js13":{"title":"Scope, hoisting i temporal dead zone","prompt":"Šta se događa u ovom samostalnom primeru?","why":"let ima blokovski scope i temporal dead zone pre inicijalizacije. Hoisting ne znači da sve deklaracije možeš bezbedno čitati ranije.","pitfall":"Prati stvarno izvršavanje i objasni pravilo svojim rečima.","code":"console.log(value);\\nlet value = 2;","options":["Baca ReferenceError jer se let čita pre inicijalizacije.","Ispisuje undefined kao svaki var.","Ispisuje 2 jer je cela naredba podignuta.","Ispisuje null."],"steps":["let vezivanje postoji u scope-u, ali se ne može čitati pre završene inicijalizacije.","var ima drugačiji tok inicijalizacije i function scope, pa ne prenosi njegovo ponašanje na let/const."],"remember":"Hoisting nije dozvola za čitanje svake vrednosti unapred.","wrong":["undefined bi odgovarao nekim čitanjima var pre dodele, ne ovom let primeru.","Inicijalizacija brojem 2 se još nije izvršila.","null nije automatska inicijalna vrednost ovog vezivanja."]},"js14":{"title":"Jednakost i konverzija tipova","prompt":"Koji je ispis za ova dva poređenja?","why":"== ovde vrši konverziju koja vodi do numeričkog poređenja. === ne izjednačava string i boolean.","pitfall":"Prati stvarno izvršavanje i objasni pravilo svojim rečima.","code":"console.log(\\"0\\" == false);\\nconsole.log(\\"0\\" === false);","options":["true, false","true, true","false, false","Baca TypeError."],"steps":["Kod == string i boolean u ovom primeru dolaze do numeričkog poređenja sa nulom.","=== zadržava razliku tipova i zato string \\"0\\" nije jednak boolean vrednosti false."],"remember":"Razumi konverziju; za uobičajene provere preferiraj jasan ugovor tipova.","wrong":["Drugi izraz ne vrši ovu konverziju.","Prvi izraz u ovom primeru jeste true.","Oba poređenja su validna i ne bacaju ovu grešku."]},"js15":{"title":"Argumenti i reference","prompt":"Koja je završna vrednost a.x?","why":"Argument dobija kopiju vrednosti reference. Mutacija pogađa zajednički objekat; ponovno vezivanje parametra ne menja vezivanje a.","pitfall":"Prati stvarno izvršavanje i objasni pravilo svojim rečima.","code":"const a = { x: 1 };\\nfunction update(value) {\\n  value.x = 2;\\n  value = { x: 3 };\\n}\\nupdate(a);\\nconsole.log(a.x);","options":["2","3","1","JavaScript uvek duboko kopira argument."],"steps":["Parametar dobija kopiju reference na isti objekat, pa value.x = 2 menja i objekat koji vidi a.","value = { x: 3 } vezuje samo lokalni parametar za novi objekat; ne menja originalnu promenljivu a."],"remember":"Kopija reference nije duboka kopija objekta.","wrong":["Novi objekat je vezan samo za lokalni parametar.","Mutacija x se već dogodila nad zajedničkim objektom.","JavaScript argumenti ne podrazumevaju duboko kloniranje."]},"js16":{"title":"Čista funkcija i mutacija","prompt":"Funkcija prima niz i vraća ga sortiranog. Koji izraz čuva ulazni redosled?","why":"Čista transformacija ne menja podatke koje je dobila. Kopiranje niza pre sort čuva ulaz, ali elementi ostaju iste reference.","pitfall":"Prati stvarno izvršavanje i objasni pravilo svojim rečima.","options":["[...items].sort(compare)","items.sort(compare)","items.reverse()","items.splice(0) pa korišćenje originala"],"steps":["sort menja niz nad kojim se poziva. Spread prvo pravi drugi spoljašnji niz, pa originalni redosled ostaje netaknut.","To nije duboka kopija elemenata. Ako menjaš svojstvo elementa, potrebna je i odluka o kopiranju tog objekta."],"remember":"Čistoća uključuje odsustvo neželjene mutacije ulaza.","wrong":["Direktan sort menja ulazni niz.","reverse menja ulaz i ne obezbeđuje traženo sortiranje.","splice menja original; ovaj tok ga prazni ili uklanja elemente."]},"js17":{"title":"map, filter i reduce","prompt":"Iz niza proizvoda izdvoji aktivne, napravi niz njihovih naziva i izračunaj zbir njihovih cena. Objasni izbor metoda.","why":"Ove metode opisuju različite transformacije. Ne koristi map samo zbog side effect-a ako rezultat ne koristiš.","pitfall":"Proveri bar jedan granični slučaj, ne samo srećan put.","solution":"const active = products.filter(p => p.active);\\nconst names = active.map(p => p.name);\\nconst total = active.reduce((sum, p) => sum + p.price, 0);","checks":["filter bira podskup bez namerne mutacije ulaza.","map pravi novu vrednost za svaki zadržani element.","reduce ima početnu vrednost i radi i za prazan niz."],"steps":["filter bira koje stavke ostaju, map menja njihov oblik, a reduce svodi više vrednosti na jednu.","Početni zbir 0 određuje ponašanje za prazan niz i sprečava grešku reduce-a bez početne vrednosti."],"remember":"Biraj metodu prema željenom izlazu.","wrong":[]},"js18":{"title":"Zašto async forEach ne čeka?","prompt":"Moraš sačuvati stavke redom i tek onda prikazati uspeh. Koji tok ispunjava zahtev?","why":"forEach ne čeka Promise rezultate callback-a i vraća undefined. Za sekvencu koristi for...of; za nezavisni paralelni rad razmotri Promise.all.","pitfall":"Prati stvarno izvršavanje i objasni pravilo svojim rečima.","options":["for (const item of items) await save(item); pa potvrda.","await items.forEach(async item => save(item)); pa potvrda.","items.map(async item => save(item)); bez čekanja.","setTimeout za potvrdu sa unapred zadatim trajanjem."],"steps":["forEach ignoriše povratne Promise vrednosti callback-a. Await nad njegovim undefined rezultatom ne čeka sačuvane stavke.","for...of uz await pokreće sledeću stavku nakon prethodne. Ako redosled nije zahtev, razmotri eksplicitno čekanje paralelnih operacija."],"remember":"Čekaj stvarne Promise-e koji predstavljaju tvoj posao.","wrong":["forEach ne pravi zajednički Promise rezultata callback-ova.","Niz Promise-a bez čekanja ne potvrđuje završetak.","Fiksni timer ne može dokazati uspeh mrežnog posla."]},"js19":{"title":"Destructuring default i null","prompt":"Koja je vrednost limit posle ove deklaracije?","why":"Default vrednost u destructuring-u primenjuje se kada je dobijena vrednost undefined, ne kada je null.","pitfall":"Prati stvarno izvršavanje i objasni pravilo svojim rečima.","code":"const { limit = 10 } = { limit: null };","options":["null","10","undefined","Deklaracija nije validan JavaScript."],"steps":["Default se aktivira za odsutnu/undefined vrednost. null je u ulazu eksplicitno prisutna vrednost.","Ako poslovno i null znači „nije zadato”, zasebno primeni ?? ili normalizaciju."],"remember":"Destructuring default i ?? imaju različitu primenu.","wrong":["10 bi se primenilo kada je izdvojena vrednost undefined.","Ulaz eksplicitno sadrži null, pa on ostaje rezultat.","Ovo je validna deklaracija sa destructuring-om."]},"js20":{"title":"Prototype i class","prompt":"Objasni kako objekat pronalazi metodu koja nije njegovo sopstveno svojstvo. Kako se class uklapa u ovaj model?","why":"JavaScript class sintaksa koristi prototipski model. Nije svako svojstvo klase isto: static metode i instance fields imaju druga mesta.","pitfall":"Proveri bar jedan granični slučaj, ne samo srećan put.","solution":"class User {\\n  greet() { return \\"Hello\\"; }\\n}\\nconst user = new User();\\n// greet is found on User.prototype.","checks":["Pretraga može pratiti prototype lanac.","Obične class metode nalaze se na prototype-u, dok instance fields imaju drugačije ponašanje.","Razlikuje nasleđivanje ponašanja od kopiranja celog objekta."],"steps":["Ako objekat nema sopstveno svojstvo, lookup može preći na njegov prototype i dalje kroz lanac.","Class sintaksa organizuje taj model. Instance fields, obične metode i static članovi ne nalaze se svi na istom objektu."],"remember":"Razumevanje lanca je važnije od same class sintakse.","wrong":[]},"js21":{"title":"try/catch i async greške","prompt":"Zašto try/catch ne hvata nužno kasnije odbijanje Promise-a ako ga samo vratiš bez await? Pokaži ispravan tok.","why":"await unutar try prenosi odbijanje u tok koji catch može da obradi. Sam return promise ne zadržava taj try aktivnim za kasniji rejection.","pitfall":"Proveri bar jedan granični slučaj, ne samo srećan put.","solution":"async function submit() {\\n  try {\\n    return await save();\\n  } catch (error) {\\n    report(error);\\n    throw error;\\n  }\\n}","checks":["Razlikuje sinhrono bacanje i kasnije Promise odbijanje.","Koristi await unutar try ili odgovarajući .catch.","Grešku obrađuje ili prosleđuje, bez tihog skrivanja."],"steps":["Try blok obrađuje bacanja koja se dogode u njegovom toku. Kasniji rejection vraćenog Promise-a traži odgovarajuće čekanje ili handler.","await unutar try čini da odbijanje pređe u catch. Tu možeš prevesti grešku ili je nakon dodatne obrade ponovo baciti."],"remember":"Vrati ili obradi grešku prema ugovoru; nemoj je slučajno sakriti.","wrong":[]},"js22":{"title":"Optional chaining nije validacija","prompt":"Šta user?.name obezbeđuje ako user postoji kao deklarisana promenljiva?","why":"?. prekida odgovarajući pristup za nullish vrednost. Nije opšti validator strukture ni zaštita za nedeklarisanu promenljivu.","pitfall":"Prati stvarno izvršavanje i objasni pravilo svojim rečima.","options":["Vraća undefined ako je user null ili undefined; ne proverava šemu name.","Garantuje da name ima tip string u runtime-u.","Pretvara svaki prazan string u undefined.","Sprečava ReferenceError i za svako nedeklarisano ime."],"steps":["Optional chaining testira null ili undefined na tom mestu lanca i tada vraća undefined.","Ne dokazuje da sledeći podatak ima očekivan tip, niti uvodi deklaraciju za ime koje ne postoji u scope-u."],"remember":"Bezbedan nullish pristup nije provera celog modela.","wrong":["Tip name moraš posebno proveriti kada je podatak nepouzdan.","Prazan string nije nullish vrednost.","Čitanje nedeklarisanog imena i dalje može baciti ReferenceError."]},"js23":{"title":"Rekurzija i bazni slučaj","prompt":"Treba obići stablo menija. Objasni bazni slučaj, napredovanje i rizik od veoma duboke ili ciklične strukture.","why":"Rekurzija mora stići do završetka. Za proizvoljan graf ili veoma dubok ulaz može trebati visited skup ili iterativni pristup.","pitfall":"Proveri bar jedan granični slučaj, ne samo srećan put.","solution":"function collect(nodes) {\\n  return nodes.flatMap(node => [\\n    node.id, ...collect(node.children ?? [])\\n  ]);\\n}\\n// Assumes an acyclic tree of manageable depth.","checks":["Ima uslov završetka i prelazi na manji deo problema.","Čuva ispravan redosled i rezultat obilaska.","Razmatra stack dubinu i cikluse ako ulaz nije garantovano stablo."],"steps":["Bazni slučaj daje rezultat bez novog rekurzivnog poziva, a svaki korak treba da mu se približava.","Vrlo dubok lanac može iscrpeti call stack. Ciklus bez zaštite može sprečiti završetak."],"remember":"Proveri završetak, napredovanje i oblik ulaza.","wrong":[]},"js24":{"title":"Bubbling, delegacija i default akcija","prompt":"Objasni event bubbling i delegaciju na listi. Razlikuj preventDefault i stopPropagation.","why":"Zaustavljanje širenja nije isto što i sprečavanje navigacije ili slanja forme. Delegacija treba da proveri i granicu kontejnera.","pitfall":"EventTarget nije garantovano Element. Proveri tip pre poziva DOM metoda kao što je closest.","solution":"list.addEventListener(\\"click\\", event => {\\n  if (!(event.target instanceof Element)) return;\\n  const button = event.target.closest(\\"button[data-id]\\");\\n  if (!button || !list.contains(button)) return;\\n  openItem(button.dataset.id);\\n});","checks":["Razlikuje event.target od currentTarget.","Delegacija koristi širenje događaja i proveru pogođenog elementa.","preventDefault utiče na default akciju; stopPropagation na dalje širenje.","Pre closest proverava da li je target Element i čuva granicu kontejnera."],"steps":["target označava izvor događaja, a currentTarget element na kojem se trenutni handler izvršava.","Bubbling omogućava handler na roditelju. Sprečavanje default akcije i dalje širenje događaja su nezavisne odluke."],"remember":"preventDefault i stopPropagation ne rade istu stvar.","wrong":[]},"re15":{"title":"Rules of Hooks","prompt":"Zašto useState ne smeš da pozoveš samo u jednoj grani uslova?","why":"Za useState i druge obične Hookove poštuj poziv na vrhu React komponente/custom Hook-a. Poseban use API ima druga pravila i ne opravdava uslovni useState.","pitfall":"Prati stvarno izvršavanje i objasni pravilo svojim rečima.","options":["React zahteva dosledan redosled tih Hook poziva između rendera.","Zato što svaka komponenta sme imati samo jedan useState.","Zato što Hookovi rade samo u class komponentama.","Može uvek, ako uslov obično ostaje isti."],"steps":["React se oslanja na doslednost odgovarajućih Hook poziva između rendera iste instance.","Uslovni useState može promeniti taj redosled. Prebaci uslov u podržanu logiku ili izdvoji komponentu."],"remember":"Običan Hook pozivaš na odgovarajućem vrhu, ne u proizvoljnoj grani.","wrong":["Jedna komponenta može imati više useState poziva.","Hookovi služe funkcionalnim komponentama i custom Hookovima.","„Obično isti” uslov nije garantovana doslednost."]},"re16":{"title":"Čisto renderovanje i props","prompt":"Komponenta u renderu poziva props.items.sort(). Zašto je to problem i kako bi je popravio?","why":"Render može biti ponovljen ili prekinut. Mutacija ulaza čini ponašanje zavisnim od redosleda rendera i utiče na druge potrošače.","pitfall":"Proveri bar jedan granični slučaj, ne samo srećan put.","solution":"const sorted = [...items].sort(compare);\\nreturn sorted.map(item => <Row key={item.id} item={item} />);","checks":["Ne mutira props i njihove deljene strukture.","Prikaz izvodi iz ulaza bez sporedne promene tuđih podataka.","Kopira niz ili menja model sortiranja prema potrebi; ne uvodi nepotreban Effect."],"steps":["Props su ulaz u render. sort menja taj ulaz i može uticati na roditelja ili drugi potrošač istog niza.","Kopija omogućava izračunavanje prikaza bez izmene tuđih podataka; Effect nije potreban samo zbog te transformacije."],"remember":"Render treba da ostane predvidljiv za iste ulaze.","wrong":[]},"re17":{"title":"useReducer ili više useState poziva","prompt":"Forma ima povezane prelaze: edit, submit, success i reset. Kada reducer olakšava model, a kada ga ne uvodiš?","why":"Reducer pomaže kada je važno jasno opisati dozvoljene promene. Za nekoliko nezavisnih vrednosti useState može ostati jednostavniji.","pitfall":"Proveri bar jedan granični slučaj, ne samo srećan put.","solution":"function reducer(state, action) {\\n  switch (action.type) {\\n    case \\"reset\\": return initialState;\\n    case \\"submit\\": return { ...state, status: \\"saving\\" };\\n    default: return state;\\n  }\\n}","checks":["Razmatra povezane prelaze i centralizovanu logiku.","Reducer je čista funkcija stanja i akcije.","Ne uvodi Redux/globalni store samo zato što koristi reducer."],"steps":["Povezane promene je često lakše objasniti kroz akcije i dozvoljene prelaze nego kroz mnogo nezavisnih setter-a.","Reducer ne treba da šalje mrežne zahteve niti menja prethodni state. On računa sledeće stanje iz ulaza."],"remember":"useReducer je lokalni alat; ne zahteva globalni store.","wrong":[]},"re18":{"title":"Lifting state up i jedan vlasnik","prompt":"Dve sibling komponente menjaju isti filter. Kako sprečavaš dve neusaglašene kopije stanja?","why":"Dve kopije koje se sinhronizuju Effect-ima često stvaraju dodatne prelaze i trke. Jedan vlasnik čini tok predvidljivijim.","pitfall":"Proveri bar jedan granični slučaj, ne samo srećan put.","solution":"const [filter, setFilter] = useState(\\"\\");\\n// Parent passes filter and onFilterChange to both children.","checks":["Definiše jednog vlasnika stanja u odgovarajućem zajedničkom scope-u.","Prosleđuje vrednost i akciju promene ili koristi opravdan zajednički izvor.","Razmatra URL ako filter mora biti deljiv i sačuvan kroz navigaciju."],"steps":["Jedan vlasnik daje jednu tekuću vrednost i jasno mesto na kojem se promena primenjuje.","Deca dobijaju vrednost i nameru promene. URL ili zajednički store biraš kada postoje stvarni zahtevi deljenja i trajanja."],"remember":"Jedna informacija treba da ima jasno određen izvor istine.","wrong":[]},"re19":{"title":"Render nije automatska DOM izmena","prompt":"Komponenta se ponovo renderovala. Šta iz toga sigurno sledi?","why":"Razlikuj render računanje, commit potrebnih promena i browser prikaz. Ponovni render nije dokaz da je ceo DOM obnovljen.","pitfall":"Prati stvarno izvršavanje i objasni pravilo svojim rečima.","options":["React je ponovo izračunao njen prikaz; stvarna DOM izmena zavisi od rezultata.","Svi DOM čvorovi su obrisani i ponovo napravljeni.","Browser je obavezno ponovo učitao stranicu.","Obavezno se izvršio svaki Effect, bez obzira na dependencies."],"steps":["Render računa šta bi trebalo prikazati. Ako je rezultat u relevantnom delu isti, DOM može ostati isti.","Effect i browser layout nisu sinonimi za poziv komponente. Razdvoji faze kada meriš performanse."],"remember":"Ponovni render nije isto što i ponovno stvaranje stranice.","wrong":["React ne mora ponovo da napravi sve DOM čvorove.","Render komponente ne znači mrežni reload dokumenta.","Izvršavanje Effect-a zavisi od njegovih pravila i dependencies."]},"re20":{"title":"Immutable izmena jednog reda","prompt":"Napiši state update koji jednom redu po id postavlja done: true, bez menjanja prethodnog niza ili objekta.","why":"Nova referenca promenjenog dela pomaže pouzdanom toku podataka. Nije potrebno duboko klonirati ceo skup.","pitfall":"Proveri bar jedan granični slučaj, ne samo srećan put.","solution":"setItems(previous => previous.map(item =>\\n  item.id === id ? { ...item, done: true } : item\\n));","checks":["Koristi prethodno stanje kada iz njega računa novi rezultat.","Pravi nov niz i nov objekat samo za izmenjeni red.","Čuva ostale reference i stabilan id."],"steps":["map pravi novi niz. Samo izmenjeni red dobija novi objekat, dok neizmenjeni mogu zadržati reference.","Funkcionalni updater koristi odgovarajuće prethodno stanje i ne zavisi od potencijalno zastarele promenljive iz handlera."],"remember":"Kopiraj promenu kroz potrebne nivoe, ne celu aplikaciju.","wrong":[]},"we11":{"title":"Box model i border-box","prompt":"Element ima width: 100px, padding: 10px i border: 2px solid uz box-sizing: border-box. Kolika je ukupna širina bez margina?","why":"Uz border-box deklarisana širina uključuje sadržaj, padding i border. Margine su izvan tog obračuna.","pitfall":"Prati stvarno izvršavanje i objasni pravilo svojim rečima.","options":["100 px","124 px","120 px","96 px"],"steps":["Deklarisana širina u border-box modelu obuhvata i unutrašnji razmak i border.","Sadržaj zato dobija preostalu unutrašnju širinu. Margin ostaje van ove ukupne širine elementa."],"remember":"Prvo proveri koji box model koristiš.","wrong":["124 px bi odgovaralo računanju 100 + 20 + 4 u content-box modelu.","Padding se ovde ne dodaje preko deklarisane širine.","Oduzimanje samo bordera nije ukupna border-box širina."]},"we12":{"title":"absolute, relative i sticky","prompt":"Objasni pozicioniranje značke unutar kartice i sticky zaglavlja unutar scroll kontejnera.","why":"position nije samo pomeranje nekoliko piksela. Kontekst i scroll granice određuju stvarno ponašanje.","pitfall":"Proveri bar jedan granični slučaj, ne samo srećan put.","solution":".card { position: relative; }\\n.badge { position: absolute; top: .5rem; right: .5rem; }\\n.header { position: sticky; top: 0; }","checks":["Razume tok dokumenta i containing block za absolute.","Koristi odgovarajući referentni kontejner, uz svest o transform/contain pravilima.","Za sticky proverava scroll pretka, inset i raspoloživ prostor."],"steps":["Absolute element koristi odgovarajući containing block, pa kartica često eksplicitno postavlja position: relative.","Sticky zavisi od scroll okruženja i inset-a. Transformacije i druga CSS pravila mogu promeniti kontekst, zato pregledaj pretke."],"remember":"Pozicioniranje uvek tumači u njegovom kontekstu.","wrong":[]},"we13":{"title":"Zašto flex dete izlazi iz kontejnera?","prompt":"Dugačak naziv fajla u flex redu pravi overflow. Šta proveravaš pre dodavanja fiksne širine?","why":"Automatska minimalna veličina flex deteta može sprečiti skupljanje. min-width: 0 omogućava ga, a način prikaza dugog teksta je zasebna odluka.","pitfall":"Proveri bar jedan granični slučaj, ne samo srećan put.","solution":".row { display: flex; }\\n.name { min-width: 0; overflow-wrap: anywhere; }","checks":["Proverava minimum sadržaja, flex-basis i shrink ponašanje.","Razmatra min-width: 0 i primereno prelamanje/ellipsis.","Čuva dostupan puni sadržaj kada skraćuje vizuelni prikaz."],"steps":["Flex item može imati automatski minimum vezan za sadržaj i odbiti potrebno smanjivanje.","min-width: 0 dopušta smanjenje, ali zatim biraš prelamanje, ellipsis ili pristupačan način čitanja pune vrednosti."],"remember":"Smanjivanje elementa i prikaz skraćenog sadržaja su odvojene odluke.","wrong":[]},"we14":{"title":"Dugme unutar forme","prompt":"Obično dugme za Cancel nalazi se unutar forme. Šta eksplicitno dodaješ da ne šalje formu?","why":"Za obično dugme u formi podrazumevani submit može biti neželjen. type=\\"button\\" jasno određuje da to dugme nije submit kontrola.","pitfall":"Prati stvarno izvršavanje i objasni pravilo svojim rečima.","options":["type=\\"button\\"","type=\\"submit\\"","Samo name=\\"cancel\\"","Samo CSS klasu .cancel"],"steps":["Dugme za Cancel predstavlja posebnu akciju, pa mu eksplicitno određuješ običan button tip.","Naziv, tekst i CSS klasa ne menjaju submit ponašanje dugmeta."],"remember":"U formi jasno označi koja dugmad šalju formu.","wrong":["submit upravo bira slanje forme.","name sam ne određuje ovu vrstu dugmeta.","CSS klasa menja stil, a ne ugrađenu form semantiku."]},"we15":{"title":"HTTP metode i idempotency","prompt":"Objasni safe i idempotent semantiku. Zašto retry POST zahteva za kreiranje može napraviti duplikat?","why":"Kod ponovljene mutacije važno je stanje koje ostaje na serveru. Metod i stvarni ugovor endpoint-a zajedno određuju šta smeš ponoviti.","pitfall":"Proveri bar jedan granični slučaj, ne samo srećan put.","solution":"Primer ugovora: za kreiranje pošalji idempotency ključ; server povezuje ponovljene zahteve sa istom operacijom.","checks":["Razlikuje bezbedno čitanje od ponavljanja iste namere.","Ne poistovećuje idempotency sa istim response body-jem.","Razmatra server podršku za idempotency ključ i jasno pravilo retry-a."],"steps":["Safe govori o nameri bez menjanja server stanja; idempotent o efektu ponavljanja iste namere. Odgovori ne moraju biti bajt-po-bajt isti.","Mrežni prekid može sakriti činjenicu da je kreiranje već uspelo. Server idempotency ugovor može sprečiti duplu operaciju pri retry-u."],"remember":"Za retry proveri semantiku operacije, ne samo status greške.","wrong":[]},"we16":{"title":"Browser render pipeline","prompt":"Objasni vezu DOM/CSS, style, layout, paint i compositing. Kako nastaje layout thrashing?","why":"Naizmenični upisi i merenja mogu naterati browser da prerano računa raspored više puta. Optimizaciju potvrdi tragom umesto univerzalnim pravilom.","pitfall":"Proveri bar jedan granični slučaj, ne samo srećan put.","solution":"Prvo pročitaj potrebnu geometriju, izračunaj promene, pa grupiši DOM upise. Proveri rezultat u Performance tragu.","checks":["Razlikuje faze i zna da svaka promena ne prolazi obavezno sve faze.","Prepoznaje naizmenično menjanje stilova i čitanje geometrije.","Grupiše čitanja/pisanja i proverava Performance trag."],"steps":["Browser od strukture i stilova izvodi geometriju i zatim prikaz. Različite promene mogu zahtevati različit deo tog rada.","Čitanje geometrije posle izmene može forsirati obračun. Mnogo naizmeničnih čitanja/pisanja može umnožiti trošak."],"remember":"Grupiši rad i potvrdi posledicu Performance tragom.","wrong":[]},"vite01":{"title":"Šta Vite radi u React projektu?","prompt":"U standardnoj client-only React aplikaciji, koja je uloga Vite-a tokom razvoja i isporuke?","options":["Izvršava React komponente na korisnikovom telefonu umesto JavaScript engine-a.","Daje razvojni server i priprema produkcione resurse koje može da isporuči statički hosting.","Zamenjuje API server i automatski proverava korisničke dozvole.","Pretvara TypeScript tipove u runtime validatore svih mrežnih odgovora."],"why":"Vite je razvojni i build alat. React kod se u browseru i dalje izvršava kao JavaScript; običan SPA build može da se posluži kao statički sadržaj.","steps":["U razvoju alat obrađuje module i omogućava brza osvežavanja dok menjaš kod.","Za isporuku napraviš build, a hosting korisniku šalje dobijene HTML, JS i CSS resurse."],"remember":"Vite priprema i služi kod; poslovni API i browser imaju druge odgovornosti.","pitfall":"Uspešan razvojni server ne dokazuje da su produkcioni API, putanje i hosting pravilno podešeni.","wrong":["Korisnikov browser i dalje izvršava klijentski JavaScript; Vite nije njegov JavaScript engine.","Autorizacija zahteva serverska pravila i nije posledica izbora build alata.","Statički tipovi ne postaju automatski mrežni validatori."]},"vite02":{"title":"VITE_ promenljiva nije tajni sef","prompt":"Privatni API token uneseš kao VITE_API_TOKEN u zaštićenu CI promenljivu i koristiš ga u browser kodu. Ko može da sazna tu vrednost?","options":["Samo CI administrator, jer je vrednost tamo označena kao secret.","Samo autor repozitorijuma, ako .env fajl nije commitovan.","Korisnik koji dobije bundle može da je otkrije; tajni poziv treba da ide preko odgovarajućeg servera.","Niko, ako promeniš naziv prefiksa VITE_ kroz envPrefix."],"why":"Zaštita vrednosti u CI-ju štiti CI skladište, ali ne menja činjenicu da klijentski build sadrži ono što browser mora da koristi.","steps":["Prati vrednost: iz CI okruženja ulazi u build, a zatim u kod koji se šalje korisniku.","Poverljivi token zadrži na serveru i tamo primeni autentikaciju, autorizaciju i ograničenja poziva."],"remember":"Sve što browser mora da zna tretiraj kao dostupno korisniku.","pitfall":"Javni identifikatori ili ključevi predviđeni za browser mogu biti javni; ne mešaj ih sa poverljivim serverskim tokenima.","wrong":["Secret oznaka sprečava neke prikaze u CI-ju, ali ne štiti vrednost ugrađenu u JS.","Git ignore sprečava commit fajla, a ne ugrađivanje njegove vrednosti u build.","Promena prefiksa menja izbor promenljivih, ne pravi zaštitu za ugrađene vrednosti."]},"vite03":{"title":"Transpile nije isto što i typecheck","prompt":"Komanda vite build prolazi iako IDE prijavljuje neispravan TypeScript tip. Šta prvo proveravaš u CI toku?","code":"const quantity: number = \\"12\\";","options":["Da li je minifikacija uključena, jer ona proverava dodelu tipova.","Da li je fajl preimenovan iz .ts u .tsx, jer samo .tsx proverava tipove.","Da li je uključen HMR, jer on radi potpunu proveru produkcije.","Da li se zasebno izvršava TypeScript provera, na primer tsc --noEmit, i da li njen neuspeh zaustavlja isporuku."],"why":"Vite obrađuje TypeScript sintaksu radi izvršavanja, ali njegov transform nije zamena za proveru tipova celog programa.","steps":["Anotacija može da se ukloni iz ovog fajla bez dokazivanja da dodeljena vrednost odgovara deklarisanom tipu.","Pokreni proveru tipova kao obavezan korak; tek posle njenog uspeha nastavi build i isporuku."],"remember":"Dodaj eksplicitnu TypeScript proveru u razvojni i CI tok.","pitfall":"Ako npm run build već poziva TypeScript pa Vite, zaštitu daje ta skripta, a ne sam vite build.","wrong":["Minifikacija optimizuje izlaz; ne dokazuje ispravnost TypeScript ugovora.","Obe ekstenzije traže proveru tipova; .tsx samo omogućava JSX sintaksu.","HMR je razvojni mehanizam osvežavanja, ne produkcioni typecheck."]},"vite04":{"title":"Šta HMR zaista obećava?","prompt":"Posle promene modula tokom razvoja stranica se potpuno osveži i lokalno stanje forme nestane. Koje je najtačnije objašnjenje?","options":["HMR pokušava da primeni promenu kroz podržane granice modula; neke izmene ipak zahtevaju ponovno učitavanje.","Vite je dužan da trajno sačuva svako React stanje između svih izmena izvornog koda.","HMR menja samo CSS, pa React komponente nikada ne mogu da se osveže bez reload-a.","HMR automatski upisuje React state u localStorage, pa nestanak stanja dokazuje problem sa API-jem."],"why":"HMR ima granice koje prihvataju promene i može da pređe na full reload. Očuvanje stanja kroz React Fast Refresh zavisi i od vrste izmene.","steps":["Razlikuj zamenu podržanog modula od novog učitavanja celog dokumenta.","Ako je nestalo važno korisničko stanje, proveri razvojnu promenu i granice modula; za trajne podatke osmisli posebno čuvanje."],"remember":"HMR ubrzava iteraciju; nije sistem trajnog čuvanja podataka.","pitfall":"Nemoj na osnovu jednog razvojnog osvežavanja zaključiti da ista promena stanja postoji u produkciji.","wrong":["Nije garantovano očuvanje svakog state-a za sve moguće izmene koda.","Vite podržava HMR integracije i za komponente, uz pravila odgovarajućeg framework-a.","HMR sam ne pravi localStorage trajnost niti ovaj simptom dokazuje API problem."]},"vite05":{"title":"Dev proxy nije produkcioni API ugovor","prompt":"Lokalni fetch('/api/users') radi uz server.proxy, a posle statičkog deploy-a vraća 404. Koji zaključak je najbolji?","options":["Dodaj CORS: * u React request i browser će pronaći backend.","Kopiraj node_modules u dist da bi proxy nastavio da radi.","Proveri produkcioni API URL ili reverse proxy na hostingu; Vite server.proxy je podešavanje razvojnog servera.","Uključi changeOrigin u browseru, jer time isporučuješ Vite proxy korisnicima."],"why":"Relativni /api/users na produkciji ide na produkcioni origin. Pravilo razvojnog Vite servera ne postaje automatski pravilo statičkog hostinga.","steps":["U Network panelu pogledaj tačan produkcioni URL i odgovor servera.","Podesi podržan produkcioni API put ili serverski reverse proxy, uz odgovarajući CORS i autentikaciju."],"remember":"Lokalni proxy je razvojna pogodnost; produkcionu mrežnu putanju definiši zasebno.","pitfall":"CORS je politika browser pristupa odgovoru, a ne način da se nepostojeća serverska ruta kreira.","wrong":["Browser ne definiše serverski Access-Control-Allow-Origin, a CORS ne rešava nedostajuću rutu.","Instalirane zavisnosti nisu statička proxy usluga koju browser izvršava.","changeOrigin je proxy opcija na serveru; nije browser mehanizam isporuke proxy-ja."]},"vite06":{"title":"Importovana slika ili public folder?","prompt":"U Vite aplikaciji želiš da slika prati dependency graph i dobije build URL sa obradom/hash-om kada je izdvojena kao fajl. Koji pristup biraš?","code":"// src/components/Profile.tsx","options":["Stavi sliku u public i uvek očekuj da njen originalni naziv dobije content hash.","Importuj sliku iz src i koristi dobijeni URL u komponenti.","U JSX napiši apsolutnu putanju lokalnog diska razvojnog računara.","U JSX ručno napiši /src/assets/avatar.png i pretpostavi da će taj source folder postojati na hostingu."],"why":"Importovani resurs je deo build grafa. Vite može da ga izdvoji sa hash-om ili, za mali resurs i odgovarajuće podešavanje, inline-uje.","steps":["Import je veza koju alat može da analizira i prepiše pri izgradnji.","public koristi kada ti treba stabilno ime/kopiranje bez tog učešća u grafu; njegove fajlove ne tretiraj kao automatski hash-ovane importe."],"remember":"Za obrađene resurse koristi import; public je namenski prostor za resurse sa posebnim zahtevima.","pitfall":"Ne oslanjaj se na tačan izlazni naziv: mali importovani resurs može biti inline-ovan.","wrong":["public resursi zadržavaju ime pri kopiranju; to nije isto što i importovani build asset.","Putanja diska postoji na tvom računaru, ne na korisnikovom uređaju ili hostingu.","Produkcioni build ne mora da isporuči src strukturu; koristi URL koji alat generiše."]},"vite07":{"title":"Staging mode i produkcioni build","prompt":"Pokrećeš vite build --mode staging bez posebne NODE_ENV izmene. Koji opis je tačan?","options":["Automatski se pokreće dev server i ukida produkciona optimizacija.","Sve env vrednosti učitavaju se tek iz browserovog operativnog sistema.","MODE i PROD moraju imati isti tip i istu vrednost.","Bira se staging mode i odgovarajuće env podešavanje, dok build podrazumevano ostaje produkcioni."],"why":"Mode određuje koje mode-specifične vrednosti učitavaš. NODE_ENV i mode nisu ista stvar, pa staging ne znači razvojni bundle.","steps":["Razdvoji namenu okruženja, kao što je staging API, od vrste build optimizacije.","Proveri konkretne import.meta.env vrednosti i build komandu; nemoj izvlačiti NODE_ENV iz samog naziva mode-a."],"remember":"Staging može da koristi produkcioni build sa drugim javnim podešavanjima.","pitfall":"Postojeća CI env promenljiva može imati prednost nad .env fajlom; proveri stvarni ulaz u proces.","wrong":["build i dalje pravi build; --mode sam ne pretvara komandu u razvojni server.","Env vrednosti se pripremaju tokom Vite procesa, ne čitaju iz korisnikovog OS-a u browseru.","MODE je string; PROD je boolean povezan sa production okruženjem."]},"vite08":{"title":"Stari tab ne može da učita novi chunk","prompt":"Korisnik je otvorio aplikaciju pre deploy-a. Kasnije otvori lazy stranicu i dobije grešku jer stari hash-ovani chunk više ne postoji. Predloži isporuku i oporavak koji čuvaju korisnikov rad.","why":"Tab već izvršava određenu verziju koda i zato traži resurse te verzije. Obrada HTML keša i zadržavanje potrebnih resursa smanjuju problem; kontrolisan oporavak obrađuje preostale greške.","steps":["Poveži traženi URL iz Network panela sa verzijom entry bundle-a i odgovorom 404; odvoji to od običnog prekida mreže.","Planiraj kompatibilan deploy i proveru svežine HTML-a; pri grešci ponudi ograničen reload tek posle čuvanja nacrta."],"remember":"Životni vek resursa mora da pokrije i tabove koji još izvršavaju prethodnu verziju.","pitfall":"Automatski reload u petlji može izgubiti unos ili se ponavljati dok je korisnik offline.","checks":["Razlikuje nedostajući stari chunk od drugih mrežnih grešaka.","Predlaže revalidaciju HTML-a i razuman period zadržavanja verzionisanih resursa.","Obrađuje vite:preloadError ili odgovarajući app error boundary uz čuvanje nacrta.","Ograničava broj pokušaja i prikazuje poruku ako oporavak ne uspe."],"solution":"Primer pristupa: HTML revalidirati (npr. Cache-Control: no-cache), hash-ovane resurse verzionisati i po mogućnosti zadržati prethodnu isporuku tokom prelaza. Na vite:preloadError sačuvati nacrt, prikazati dugme „Učitaj novu verziju” i omogućiti najviše jedan automatski pokušaj po verziji. Offline korisniku ponuditi pokušaj kada veza proradi. Proveriti ponašanje u tabu otvorenom pre deploy-a.","wrong":[]},"vite09":{"title":"Deploy u podfolder","prompt":"SPA treba da radi pod /training/. JS/CSS zahtevi pogrešno idu na koren domena. Koje Vite podešavanje prvo proveravaš?","options":["base za javne putanje resursa; zatim zasebno proveravam router basename i hosting fallback.","Naziv React root DOM elementa.","Broj paralelnih zahteva browsera.","Samo server.port, jer produkcioni asset URL zavisi od razvojnog porta."],"why":"base usmerava javne URL-ove resursa. To je povezano sa lokacijom isporuke, ali ne rešava samo po sebi sva pravila klijentskog rutiranja.","steps":["Pogledaj generisani index.html i Network zahteve: /assets/... nije isto što i /training/assets/....","Uskladi build base sa hosting putanjom, pa proveri direktno otvaranje i refresh svake podržane rute."],"remember":"Build putanja resursa, putanja router-a i hosting fallback moraju da se slažu.","pitfall":"Podešen base ne pretvara automatski proizvoljan serverski 404 u SPA rutu.","wrong":["DOM root identifikuje mesto renderovanja; ne određuje javnu putanju build fajlova.","Paralelizam browsera ne menja pogrešno generisane URL-ove.","Razvojni port ne podešava putanju produkcionih statičkih resursa."]},"vite10":{"title":"Lazy modul koji se ipak učitava odmah","prompt":"Veliki editor želiš tek na posebnoj stranici. Međutim, entry modul ga i statički importuje i prikazuje. Šta je najbolji prvi korak?","code":"import Editor from './HeavyEditor';\\n// elsewhere: lazy(() => import('./HeavyEditor'))","options":["Dodati još jedan lazy import bez menjanja statičke zavisnosti.","Promeniti samo ime fajla u HeavyEditor.lazy.tsx.","Ukloniti nepotrebnu eager zavisnost iz početnog puta, napraviti jasnu async granicu i izmeriti produkcioni izlaz.","Isključiti TypeScript, jer on sprečava code splitting."],"why":"Lazy import može da odloži učitavanje, ali statička zavisnost iz početnog koda može taj cilj da poništi. Raspodelu proveravaš u stvarnom produkcionom buildu.","steps":["Prati dependency graph od entry modula do velikog editora, uključujući re-export fajlove.","Izoluj retko korišćen deo iza async granice, pa uporedi preuzete bajtove i doživljaj učitavanja pre i posle promene."],"remember":"Odlaganje traži stvarnu async granicu, a ne samo lazy naziv.","pitfall":"Code splitting uvodi dodatna učitavanja; prikaz loading/error stanja je deo rešenja.","wrong":["Drugi import ne uklanja već postojeću početnu zavisnost.","Naziv fajla sam po sebi nije pravilo raspodele chunk-ova.","TypeScript nije razlog što statički import ostaje eager zavisnost."]},"vite11":{"title":"build.target nije katalog browser API-ja","prompt":"Spustiš build.target, ali stariji podržani browser nema Array.prototype.toSorted. Šta tačno moraš da razmotriš?","options":["target automatski dodaje polyfill za svaki nedostajući Web i JavaScript API.","Pored transformacije sintakse treba proveriti runtime podršku i po potrebi koristiti polyfill ili kompatibilnu implementaciju.","Dovoljno je promeniti TypeScript anotaciju niza, bez promene izvršnog koda.","Ako build prođe, dodatna browser provera nije potrebna."],"why":"Transformacija sintakse i dostupnost runtime API-ja nisu ista provera. Podešen jezički target ne dokazuje da konkretna metoda postoji u korisnikovom browseru.","steps":["Razdvoji sintaksu koju alat može da transformiše od metode koju izvršava JavaScript engine.","Definiši podržane browsere, proveri korišćene API-je i testiraj potreban fallback ili polyfill."],"remember":"Syntax target ne garantuje sve runtime mogućnosti.","pitfall":"Ne dodaj naslepo ceo polyfill paket: proveri stvarne zahteve i cenu u bundle-u.","wrong":["Vite podrazumevano ne obezbeđuje sve runtime polyfill-ove; target to ne garantuje.","TypeScript anotacija ne implementira nedostajuću metodu u browseru.","Uspešno generisan bundle nije dokaz podrške svakog API-ja na ciljnom uređaju."]},"vite12":{"title":"Vite 7 → 8: šta proverava senior?","prompt":"Tim nadograđuje Vite 7 na Vite 8. Kolega kaže: „Samo promeni verziju, isti su esbuild i Rollup.” Objasni promenu i predloži proverljiv plan nadogradnje.","why":"Vite 8 koristi Rolldown i Oxc alate umesto prethodne kombinacije esbuild/Rollup. Sličan plugin interfejs olakšava prelaz, ali ne dokazuje identično ponašanje svakog projekta.","steps":["Prvo popiši verzije, plugin-ove, prilagođene transformacije, build opcije i podržane browsere.","Zatim uporedi tipove, testove i produkcioni izlaz; proveri i runtime, učitavanje ruta, resurse i mogućnost rollback-a."],"remember":"Nadogradnju build alata potvrđuješ ponašanjem i izlazom, uz čitanje migration guide-a.","pitfall":"Ne obećavaj tuđi procenat ubrzanja; izmeri ovaj projekat istim uslovima pre i posle.","checks":["Prepoznaje Rolldown/Oxc promenu u Vite-u 8.","Proverava migration guide, Node podršku i kompatibilnost korišćenih plugin-ova/opcija.","Uključuje typecheck, testove, build i smoke proveru produkcionih ruta/resursa.","Meri sopstveni build i proverava ciljane browsere i rollback."],"solution":"Napraviti zasebnu granu i zabeležiti početni rezultat i trajanje build-a. Pročitati Vite 8 migration guide, proveriti potrebni Node i plugin verzije, zameniti ili prilagoditi relevantna esbuild/Rollup podešavanja. Pokrenuti provere i uporediti izlaz, source map pristup, lazy rute, CSS i deployment putanje na staging-u. Izmeriti isti projekat i odobriti isporuku uz poznat način vraćanja verzije.","wrong":[]},"cra01":{"title":"CRA u pripremi za intervju 2026.","prompt":"Kako je najtačnije predstaviti Create React App na intervjuu u novembru 2026?","options":["To je podrazumevana preporuka React tima za svaki novi projekat.","To je važan legacy alat: CRA je deprecated za nove aplikacije od 14. februara 2025, a postojeće sisteme održavaš i planiraš migraciju prema potrebama.","React aplikacije napravljene CRA-om automatski su prestale da rade tog datuma.","CRA deprecation znači da su i React i client-side rendering deprecated."],"why":"Deprecated status menja preporuku za izbor i održavanje alata; ne znači da postojeća aplikacija sama prestaje da radi. Važno je razumeti njen build i rizike promene.","steps":["Odvoji status alata za nove projekte od ponašanja trenutno isporučene aplikacije.","Za postojeći projekat proceni podršku, zavisnosti, potrebe i trošak migracije umesto da obećaš hitan rewrite bez analize."],"remember":"Znanje CRA-a je korisno za održavanje; novi izbor alata traži aktuelnu procenu.","pitfall":"Stare CRA stranice služe kao dokumentacija legacy ponašanja, ne kao dokaz preporuke za novi projekat.","wrong":["React tim je objavio suprotnu preporuku i usmerio nove aplikacije ka podržanim alternativama.","Deprecation obaveštenje ne briše već isporučen JS ili postojeći sajt.","Status jednog build alata ne ukida React ni CSR način prikaza."]},"cra02":{"title":"create-react-app i react-scripts","prompt":"U postojećem CRA projektu ko obezbeđuje upakovane start/build/test komande i njihovu konfiguraciju dok projekat nije eject-ovan?","options":["Globalno instalirani create-react-app, koji se ponovo izvršava pri svakom build-u.","Sam react-dom, zato što i renderuje UI.","Browser, koji automatski preuzima webpack konfiguraciju sa npm-a.","Instalirani react-scripts paket u projektu; create-react-app prvenstveno generiše početni projekat."],"why":"Generator i alat koji projekat kasnije koristi nisu isto. U standardnom CRA projektu skripte upućuju na lokalno instalirani react-scripts.","steps":["Pogledaj scripts u package.json: start/build/test pokreću odgovarajuće react-scripts komande.","Za konkretno ponašanje proveri verziju te projektne zavisnosti i lock fajl, a ne verziju globalnog generatora."],"remember":"Generator pravi projekat; projektni react-scripts vodi njegov standardni alatni tok.","pitfall":"Ovo opisuje standardni unejected CRA; proveri overrides ili kopirane skripte u prilagođenom projektu.","wrong":["Globalni generator nije proces koji standardni projekat pokreće pri svakoj isporuci.","react-dom se bavi renderovanjem/hidracijom, ne CRA build konfiguracijom.","Build alati rade u razvojnom/CI okruženju; browser ne instalira webpack sa npm-a."]},"cra03":{"title":"Promenjena env vrednost, stari API URL","prompt":"CRA SPA je već build-ovana i statički isporučena. Promeniš REACT_APP_API_URL samo u okruženju servera koji služi fajlove. Bez posebnog runtime config mehanizma, šta očekuješ?","options":["Stari ugrađeni URL ostaje; za novu build-time vrednost treba novi build i isporuka.","Svaki postojeći browser odmah pročita novu serversku env vrednost.","Novi URL se pojavi čim promenim naziv React state promenljive.","REACT_APP_ vrednosti su uvek poverljive, pa browser ionako ne može da koristi API URL."],"why":"CRA ugrađuje izabrane env vrednosti tokom build-a. Statički server zatim isporučuje već dobijene fajlove, umesto da automatski prepisuje njihov sadržaj.","steps":["Razlikuj okruženje build procesa od okruženja servera koji samo vraća gotov JS.","Ako želiš jedan build za više okruženja, zasebno projektuj javni runtime config i proveri njegov keš i validaciju."],"remember":"Build-time konfiguracija ostaje ista dok ne isporučiš drugi build.","pitfall":"REACT_APP_ vrednosti koje uđu u bundle su javne korisniku; runtime config nije mesto za tajne.","wrong":["Browser nema automatski pristup procesu koji na serveru služi fajlove.","Ime state promenljive ne menja već ugrađeni sadržaj bundle-a.","Prefiks omogućava izlaganje klijentu; ne obezbeđuje poverljivost."]},"cra04":{"title":"CRA proxy i produkcioni CORS","prompt":"CRA package.json ima proxy za lokalni API. Zašto to ne dokazuje da će isti /api poziv i autentikacija raditi posle deploy-a?","options":["Zato što svaki produkcioni API mora imati potpuno isti port kao CRA dev server.","Zato što React zabranjuje relativne URL-ove u produkciji.","Proxy je razvojno podešavanje; produkcioni origin, reverse proxy, CORS i cookie pravila treba zasebno proveriti.","Zato što browser može da pošalje samo GET zahteve iz produkcionog build-a."],"why":"Razvojni server posreduje zahteve samo u svom okruženju. Posle deploy-a stvarna mrežna topologija i pravila browsera određuju gde poziv ide i koje kredencijale može da pošalje.","steps":["Zabeleži origin aplikacije, URL API-ja i da li produkcija koristi isti origin ili cross-origin pozive.","Proveri ruta/proxy podešavanje i autentikacioni ugovor na stvarnom hostingu; lokalni uspeh je samo lokalni dokaz."],"remember":"Dev proxy ne testira produkcioni mrežni i autentikacioni ugovor.","pitfall":"Nemoj koristiti lokalni proxy kao dokaz da su produkcioni cookie, CORS ili dozvole bezbedno podešeni.","wrong":["Isti port nije obavezan; origin/proxy/CORS arhitektura određuje dozvoljen put.","Relativni URL-ovi su validni; bitno je na koji origin i rutu se razrešavaju.","Produkcioni browser podržava i druge HTTP metode uz odgovarajuća pravila."]},"cra05":{"title":"Šta znači eject?","prompt":"Tim predlaže npm run eject radi jedne izmene build konfiguracije. Koji opis posledice je tačan?","options":["Eject samo uključuje debug log i potpuno se vraća sledećim npm start.","Kopira alatnu konfiguraciju i zavisnosti u projekat; tim preuzima održavanje, pa odluku i povratak kroz Git treba unapred razmotriti.","Eject pretvara React u server framework sa automatskim API rutama.","Eject ažurira sve zavisnosti na bezbedne verzije i uklanja potrebu za migracijom."],"why":"Eject izlaže konfiguraciju koju je ranije skrivao react-scripts i povećava odgovornost tima. CRA nema običnu uneject komandu.","steps":["Proveri da li problem može da se reši podržanim podešavanjem ili planiranom migracijom bez preuzimanja cele konfiguracije.","Ako je eject opravdan, napravi pregledan commit i proverljiv način vraćanja pre nego što menjaš kopirane skripte."],"remember":"Eject prenosi kontrolu i teret održavanja konfiguracije na tim.","pitfall":"„One-way” u CRA interfejsu ne znači da Git ne može da vrati prethodni commit; prvo sačuvaj poznato stanje.","wrong":["Eject menja projekat i konfiguraciju; npm start ga ne poništava.","Otvaranje build konfiguracije ne pravi serverske poslovne rute.","Eject sam ne garantuje nadograđene ili bezbedne zavisnosti."]},"cra06":{"title":"Jest/jsdom nije Safari test","prompt":"Legacy CRA komponentni testovi prolaze u Jest/jsdom-u. Šta iz tog rezultata možeš pouzdano da zaključiš?","options":["Potvrđeno je da CSS raspored i touch interakcije rade na fizičkom iPhone-u.","Potvrđeno je da svi produkcioni CORS i cookie scenariji rade.","Potvrđeno je da će offline service worker sigurno raditi posle privatne prijave.","Prošli su ti testovi u tom okruženju; browser specifične tokove i stvarnu integraciju proveravaš odgovarajućim dodatnim proverama."],"why":"jsdom simulira deo browser DOM okruženja u Node-u. Koristan je za ponašanje komponenti, ali nije fizički Safari niti potpuna produkciona mreža.","steps":["Navedi šta test zaista izvršava: render, korisničku akciju, mock odgovore i očekivani rezultat.","Za layout, browser API-je, instalaciju ili produkcionu autentikaciju odredi dokaz iz odgovarajućeg browser/integration testa."],"remember":"Rezultat testa važi u granicama onoga što je test izvršio.","pitfall":"Nemoj zameniti smislen komponentni test velikim mock-om koji samo potvrđuje sopstvenu implementaciju.","wrong":["jsdom ne potvrđuje stvarno renderovanje CSS-a i fizički touch uređaj.","Mock ili simulirano okruženje ne dokazuje stvarnu produkcionu mrežnu politiku.","Jest rezultat ne proverava sam po sebi service worker i offline privatnu prijavu."]},"cra07":{"title":"Plan CRA → Vite migracije bez izgubljenih funkcija","prompt":"Nasleđuješ CRA admin aplikaciju sa React Router-om, Sass-om, testovima i env podešavanjima. Predloži redosled migracije na Vite koji jasno odvaja promenu alata od promene ponašanja proizvoda.","why":"Novi build alat ne prenosi automatski sve konvencije starog. Postojeće funkcije proveravaš preko inventara ulaza, izlaza i realnih tokova.","steps":["Popiši build/start/test skripte, HTML entry, env pristup, proxy, asset putanje, Sass i routing pravila.","Prenesi ih u novi tok, zatim proveri istu produkcionu aplikaciju kroz tipove, testove, build i važne korisničke scenarije."],"remember":"Migracija je prenos ugovora i ponašanja, a ne samo zamena npm komande.","pitfall":"Ne preslikavaj svaki REACT_APP_ ključ u VITE_ bez pregleda: obe klijentske konfiguracije mogu izložiti vrednost.","checks":["Pravi inventar CRA konvencija i bira odgovarajući Vite React setup.","Razlikuje process.env.REACT_APP_* od import.meta.env.VITE_* i čuva tajne na serveru.","Prenosi entry, assets, Sass, proxy i produkcione base/routing ugovore.","Zasebno planira test runner, proveru tipova, CI i rollback.","Proverava realne kritične tokove umesto oslanjanja samo na pokrenut dev server."],"solution":"1. Sačuvati baseline i izolovati granu. 2. Uvesti Vite React entry i scripts uz odgovarajući index.html. 3. Pregledati i preneti javne env vrednosti, assets, Sass i proxy. 4. Uskladiti izlazni folder i hosting/routing pravila. 5. Obezbediti test/typecheck tok; migracija na drugi test runner je zasebna odluka. 6. Uporediti login, direktne rute, forme, API pozive i build na staging-u pre promene isporuke.","wrong":[]},"cra08":{"title":"Ruta radi klikom, ali refresh vraća 404","prompt":"U CRA SPA-u koristiš BrowserRouter. Link do /users/42 radi iz aplikacije, a direktan URL ili refresh vraća serverski 404. Objasni uzrok i bezbedno ispravi hosting pravilo.","why":"Klijentski router vidi navigaciju tek kada se aplikacija učita. Kod direktnog URL-a prvi zahtev obrađuje hosting, koji mora da razlikuje SPA dokument, statičke resurse i API.","steps":["Uporedi navigaciju bez novog dokumenta sa punim HTTP zahtevom za /users/42.","Za dozvoljene frontend navigacione putanje posluži SPA index.html, dok API i stvarni resursi zadrže svoja odgovarajuća pravila i statuse."],"remember":"Client-side router ne zamenjuje pravilo servera za prvo učitavanje dokumenta.","pitfall":"Globalni fallback koji vraća HTML umesto nepostojećeg JS ili API odgovora može da sakrije greške i napravi pogrešne odgovore.","checks":["Objašnjava razliku između browser history navigacije i punog server zahteva.","Predlaže fallback za frontend navigacione putanje na index.html.","Izuzima API i statičke resurse iz pogrešnog HTML fallback-a.","Proverava direktan URL, refresh, nepostojeće resurse i subfolder ako se koristi."],"solution":"Na konkretnom hostingu podesiti pravilo: postojeći statički fajlovi idu kao fajlovi; /api/... ide u API i zadržava API statuse; dozvoljene frontend navigacije dobijaju index.html. U browseru proveriti /users/42 direktno i refresh. Zatražiti i nepostojeći .js i API put da se potvrdi da ne vraćaju lažni HTML uspeh. Za podfolder uskladiti javnu putanju build-a i router basename. Sintaksu pravila birati prema verziji servera; stari Express wildcard primer ne kopirati bez provere.","wrong":[]},"node01":{"title":"Isti JavaScript, drugo okruženje","prompt":"Kolega kopira običan browser modul koji koristi document.querySelector u Node skriptu. Šta treba prvo da objasniš?","why":"JavaScript je jezik, a runtime daje dodatne API-je. Node bez dodatnog DOM okruženja nema document; umesto toga nudi server i sistemske API-je.","pitfall":"Postojanje nekih zajedničkih Web API-ja, poput fetch u podržanom Node-u, ne znači da postoji ceo browser.","options":["Node dodaje document kada fajl ima ekstenziju .js.","Treba razdvojiti zajedničku logiku od koda koji zavisi od DOM-a.","Dovoljno je instalirati TypeScript da document postane dostupan.","Svaki modul koji radi u browseru automatski radi i u Node-u."],"steps":["Prvo utvrdi da li je problem u JavaScript sintaksi ili u API-ju okruženja.","Izvuci čistu logiku u zajednički modul, a DOM rad ostavi browser sloju."],"remember":"Jezik je isti; dostupni API-ji zavise od runtime-a.","wrong":["Ekstenzija bira način učitavanja, ne kreira DOM.","TypeScript tipovi ne stvaraju document tokom izvršavanja.","Browser moduli mogu zavisiti od DOM-a i drugih browser mogućnosti koje Node nema."]},"node02":{"title":"Zašto async ne rešava težak proračun?","prompt":"HTTP handler je async, ali pre prvog await deset sekundi računa rezultat u velikoj petlji. Šta se dešava ostalim zahtevima u istom Node procesu?","why":"Običan JavaScript u toj petlji i dalje zauzima event loop. Async funkcija ne prebacuje automatski CPU posao u poseban thread.","pitfall":"Ni Promise.resolve().then(heavyCalculation) ne pretvara sinhroni proračun u paralelni posao.","options":["Async automatski šalje svaku petlju u libuv thread pool.","Samo taj korisnik čeka, jer svaki HTTP zahtev dobija svoj JavaScript thread.","Drugi zahtevi trpe kašnjenje; razmotri ograničenje posla, podelu ili worker threads za CPU zadatak.","await na kraju handlera retroaktivno oslobađa event loop tokom petlje."],"steps":["Dok petlja traje, callback koji obrađuje taj zahtev ne vraća kontrolu event loop-u.","Izmeri trošak, ograniči ulaz i za skup CPU posao razmotri kontrolisan worker pool ili drugi servis."],"remember":"Async menja tok čekanja; ne pravi svaki proračun paralelnim.","wrong":["libuv ne preuzima proizvoljne JavaScript petlje samo zato što je funkcija async.","Node ne dodeljuje automatski poseban JavaScript thread svakom HTTP zahtevu.","Kasniji await ne može ukloniti vreme koje je već potrošeno blokiranjem."]},"node03":{"title":"Prebaci čitanje fajla na async API","prompt":"Ova funkcija se često poziva dok server obrađuje zahteve. Prepiši je koristeći node:fs/promises i pokaži gde se obrađuju greške čitanja i JSON parsiranja. Putanja je ovde pouzdana konfiguracija aplikacije.","why":"Promise API omogućava da se tokom I/O čekanja obrađuje drugi posao. Čitanje i JSON.parse mogu da otkažu, pa pozivalac treba da sačeka rezultat i obradi odbijeni Promise.","pitfall":"JSON.parse je i dalje sinhron; za ogroman dokument treba razmotriti dodatna ograničenja ili streaming.","code":"import { readFileSync } from 'node:fs';\\nfunction loadConfig(path) {\\n  return JSON.parse(readFileSync(path, 'utf8'));\\n}","solution":"import { readFile } from 'node:fs/promises';\\n\\nasync function loadConfig(path) {\\n  const text = await readFile(path, 'utf8');\\n  return JSON.parse(text);\\n}\\n\\ntry {\\n  const config = await loadConfig('./config.json');\\n  // Validate the parsed shape before using it.\\n} catch (error) {\\n  // Handle or report the read/parse failure at this boundary.\\n  throw error;\\n}","checks":["Koristi readFile iz node:fs/promises sa utf8.","Funkcija je async i readFile rezultat se čeka pre JSON.parse.","Pozivalac koristi await i hvata ili prosleđuje i I/O i parse grešku.","Ne vraća lažno uspešan prazan objekat za svaki neuspeh."],"steps":["Zameni blokirajuće čitanje Promise API-jem; ne uklanjaš samu operaciju, već čekanje oslobađaš za druge zahteve.","Greška iz await ili JSON.parse odbija Promise async funkcije; obradi je na smislenoj granici."],"remember":"Async I/O traži i await i jasno rukovanje neuspehom.","wrong":[]},"node04":{"title":"package.json i izbor modula","prompt":"Najbliži package.json ima \\"type\\": \\"module\\". Kako Node tretira običan .js fajl u tom paketu?","why":"Eksplicitno type: module postavlja ES module režim za .js fajlove tog paketa. Ekstenzija .cjs ostaje način da se određeni fajl eksplicitno označi kao CommonJS.","pitfall":"Ne oslanjaj se na implicitno prepoznavanje sintakse ako paket može jasno da navede svoj modul sistem.","options":["Kao ES module; .cjs može eksplicitno da označi CommonJS fajl.","Kao CommonJS, jer samo .mjs može biti ES module.","Kao TypeScript, jer module uključuje proveru tipova.","Način učitavanja određuje samo ime npm paketa."],"steps":["Node traži granicu paketa i vrednost polja type.","Za izuzetke koristi eksplicitnu ekstenziju, a import/export i module.exports ne mešaj bez razumevanja interoperabilnosti."],"remember":"Polje type opisuje .js modul sistem; ne uključuje TypeScript.","wrong":[".js može biti ES module kada paket to eksplicitno navede.","Modul sistem i statička provera tipova su odvojene stvari.","Naziv paketa ne zamenjuje pravila za type i ekstenzije."]},"node05":{"title":"Relativni import u Node ESM-u","prompt":"Pokrećeš običan Node ESM bez bundlera ili prilagođenog loadera. Fajl helper.js postoji. Koji je najjasniji ispravan relativni import?","why":"Node ESM traži eksplicitnu ekstenziju za relativne i apsolutne specifiere. Bundler u frontendu može da podrži drugačiju rezoluciju, ali ta pretpostavka se ne prenosi automatski na Node.","pitfall":"To što Vite prihvata kraći import ne dokazuje da će isti specifier raditi u običnom Node ESM-u.","options":["import { help } from './helper';","import { help } from './helper/';","import { help } from 'helper.js';","import { help } from './helper.js';"],"steps":["Specifier koji počinje sa ./ označava relativan fajl.","U standardnom Node ESM-u navedi ceo naziv fajla, uključujući .js; package specifier bez ./ ima drugo značenje."],"remember":"Za relativni Node ESM import navedi stvarnu ekstenziju.","wrong":["Node ESM ne dopisuje automatski .js za ovaj relativni import.","Direktorijumski import ne zamenjuje punu putanju konkretnog fajla.","Bez ./ ovo je bare package specifier, a ne relativni helper.js."]},"node06":{"title":"Zašto je \\"false\\" uključio funkciju?","prompt":"Environment sadrži FEATURE_ENABLED=false, a kod koristi if (process.env.FEATURE_ENABLED). Zašto ulazi u if?","why":"Vrednost iz environment-a je string \\"false\\", a neprazan string je truthy. Konfiguraciju treba eksplicitno parsirati i proveriti, na primer poređenjem sa \\"true\\".","pitfall":"Server environment može čuvati tajnu samo dok je ne ispišeš u log, odgovor ili frontend bundle.","options":["Node automatski pretvara false u boolean true.","Environment promenljive uvek imaju vrednost 1.","To je neprazan string; potreban je eksplicitan način parsiranja.","Problem se rešava dodavanjem TypeScript anotacije boolean."],"steps":["Razdvoji tekst iz konfiguracije od JavaScript boolean vrednosti.","Definiši dozvoljene vrednosti, obradi odsutnu/neispravnu konfiguraciju i parsiraj je pri pokretanju."],"remember":"Environment je ulazni tekst; parsiranje i validacija su tvoj posao.","wrong":["Node ne pravi takvu automatsku boolean konverziju.","Environment podržava tekstualne vrednosti, ne samo broj 1.","TypeScript anotacija ne menja stvarni string u runtime-u."]},"node07":{"title":"Backpressure pri velikom download-u","prompt":"Brz izvor podataka piše sporom writable stream-u. write(chunk) vrati false. Šta treba uraditi u ručnoj petlji za pisanje?","why":"False znači da je internom baferu potreban predah. Privremeno prestani da šalješ nove chunk-ove i sačekaj drain; za povezivanje stream-ova često je bolji pipeline.","pitfall":"False nije dokaz da je baš taj chunk izgubljen ili da ga treba odmah poslati ponovo.","options":["Odmah ponovo poslati isti chunk, dok ne vrati true.","Pauzirati novo pisanje i sačekati drain pre nastavka.","Ignorisati rezultat jer stream automatski ograničava svu memoriju.","Pretvoriti ceo fajl u jedan Buffer da se izbegne čekanje."],"steps":["Proizvođač je brži od potrošača, pa bi nastavak slanja gomilao memoriju.","Poštuj signal stream-a i obradi i završetak i greške, umesto da povećavaš bafer bez granice."],"remember":"Backpressure usklađuje brzinu proizvođača sa potrošačem.","wrong":["Chunk nije za automatsko ponovno slanje; dupliranje može pokvariti izlaz.","Ako nastaviš uprkos false, možeš nastaviti da gomilaš podatke u memoriji.","Ceo veliki Buffer povećava memorijski trošak i gubi prednost streaming-a."]},"node08":{"title":"Greška u callback-u nije u starom try bloku","prompt":"try { setTimeout(() => { throw new Error('boom'); }, 0); } catch (error) { ... } Da li ovaj spoljašnji catch hvata kasnije bačenu grešku?","why":"Ne. Spoljašnji try se završi pre nego što timer callback počne. Callback mora da obradi grešku u svom toku ili da je preko odgovarajućeg Promise/callback mehanizma prosledi pozivaocu.","pitfall":"Node API-ji mogu prijaviti neuspeh kroz throw, rejected Promise, error-first callback ili error događaj; proveri ugovor konkretnog API-ja.","options":["Ne; try/catch ne ostaje otvoren dok zakazani callback kasnije radi.","Da; try automatski prati sve callback-ove nastale u njemu.","Da, ako je timeout 0, jer tada callback radi sinhrono.","Da, čim uz callback napišemo TypeScript tip Error."],"steps":["Prvo se samo registruje timer, a spoljašnji sinhroni blok nastavlja i završava se.","Kasniji callback ima sopstveni tok izvršavanja; rukovanje greškom mora biti povezano sa njim."],"remember":"Hvataj grešku tamo gde se njen stvarni tok izvršava.","wrong":["Običan try/catch ne prati automatski naknadno zakazane callback-ove.","Timeout 0 znači najraniji kasniji termin, ne trenutno sinhrono izvršavanje.","Tip Error ne menja način propagacije runtime greške."]},"node09":{"title":"Node pokreće .ts: da li proverava tipove?","prompt":"Koristiš podržanu savremenu Node verziju sa ugrađenim type stripping-om. Skripta sa uklonjivim TypeScript anotacijama se pokreće. Šta iz toga možeš da zaključiš?","why":"Type stripping uklanja podržanu TS sintaksu da bi se kod izvršio. Ne radi statičku proveru i ne primenjuje automatski tsconfig opcije, pa tsc --noEmit ostaje zasebna provera.","pitfall":"Ne radi svaka TypeScript konstrukcija u ovom režimu; tipovi koji zahtevaju generisanje JavaScript-a imaju dodatna ograničenja.","options":["Uspešno pokretanje dokazuje da nema TypeScript grešaka.","Node je automatski preuzeo sve opcije iz tsconfig.json.","Podržane su sve TS transformacije koje bilo koji bundler ume da napravi.","Skripta može da se izvrši i uz pogrešne tipove; pokreni zasebnu statičku proveru."],"steps":["Razdvoji izvršavanje JavaScript ponašanja od analize tipova pre izvršavanja.","Koristi podržanu erasable sintaksu, proveri Node dokumentaciju i zadrži typecheck u razvojnom/CI toku."],"remember":"Pokretanje .ts fajla nije dokaz da su tipovi ispravni.","wrong":["Izvršavanje prati runtime ponašanje, ne dokazuje statičku ispravnost.","Ugrađeni stripping namerno ne čita tsconfig za takve transformacije.","Ugrađeni režim ima uži obim od punog TypeScript toolchain-a."]},"node10":{"title":"Uredno gašenje Node servera","prompt":"Deploy šalje SIGTERM procesu koji obrađuje HTTP zahteve i koristi bazu. Objasni redosled urednog gašenja i šta radiš ako zahtevi ne završe u razumnom roku.","why":"Naglo gašenje može prekinuti odgovore i ostaviti posao nedovršen. Uredno gašenje ograničava novo opterećenje, daje aktivnom poslu vreme da završi i zatvara resurse, uz krajnji rok.","pitfall":"Samo dodavanje signal handler-a ne zatvara automatski bazu, background poslove ili upgraded/WebSocket veze.","solution":"1. Označi instancu kao nespremnu za nove zahteve i pozovi server.close().\\n2. Dozvoli aktivnim HTTP zahtevima da završe u dokumentovanom vremenskom roku.\\n3. Zaustavi ili isprazni background posao; posebno upravljaj upgraded/WebSocket vezama kada postoje.\\n4. Zatvori DB pool i druge resurse, obradi cleanup neuspehe, pa završi proces odgovarajućim statusom.\\n5. Ako rok istekne, zabeleži bezbednu dijagnostiku i prinudno završi prema deployment politici.","checks":["Zaustavlja ili odvodi nove zahteve pre zatvaranja zajedničkih resursa.","Predviđa završetak tekućih zahteva i zatvaranje DB pool-a.","Ima ograničen rok i postupak za zaglavljene zahteve/veze.","Razlikuje HTTP server od background poslova i posebnih veza."],"steps":["Prvo smanji priliv posla, da cleanup ne radi paralelno sa novim zahtevima koji i dalje traže iste resurse.","Zatim sačekaj dozvoljeni period, zatvori resurse i obezbedi izlaz čak i kad nešto ostane zaglavljeno."],"remember":"Graceful shutdown je redosled i vremenski budžet, ne samo SIGTERM callback.","wrong":[]},"node11":{"title":"npm ci u CI okruženju","prompt":"Repo sadrži usklađene package.json i package-lock.json. Zašto je npm ci dobar izbor za instalaciju u CI-u?","why":"npm ci instalira prema lock fajlu i ne ažurira ga da bi prikrio neslaganje. Ako package.json i lock nisu usklađeni, komanda prijavljuje neuspeh.","pitfall":"Lock fajl pomaže ponovljivosti, ali ne izjednačava različite Node verzije, operativne sisteme i native toolchain-e.","options":["Automatski prepravlja lock na najnovije verzije bez obzira na package.json.","Instalira zaključano stablo i prijavljuje neslaganje manifest/lock fajla.","Preuzima samo aplikacione dependency-je, bez mogućnosti devDependency instalacije.","Dokazuje da aplikacija nema ranjivih dependency-ja."],"steps":["Manifest opisuje nameru, a lock konkretne rezolucije zavisnosti.","CI treba da otkrije neusklađene fajlove, umesto da neprimetno generiše drugačije dependency stablo."],"remember":"npm ci prati lock; ne služi za tiho popravljanje lock fajla.","wrong":["Ažuriranje verzija i lock-a pripada drugom, pregledanom koraku.","Dev dependencies mogu se instalirati; izostavljanje zavisi od konfiguracije i okruženja.","Uspešna instalacija nije kompletan sigurnosni audit."]},"node12":{"title":"Izbor Node verzije u 2026.","prompt":"Pripremaš produkcioni servis. Koji pristup izboru Node verzije je najpouzdaniji prema dokumentaciji proveravanoj 6. novembra 2026.?","why":"Izaberi podržanu Active ili Maintenance LTS granu, ažuriraj patch verziju i proveri kompatibilnost aplikacije. Pravilo „uvek samo parni major” nije trajna politika: objavljen je drugačiji ciklus počev od Node 27.","pitfall":"Najviši broj verzije i uspešan lokalni start ne dokazuju produkcionu podršku.","options":["Uvek uzmi najviši broj verzije, uključujući Alpha, da bi projekat bio moderan.","Zauvek odbaci svaki neparni major bez čitanja release rasporeda.","Proveri aktuelni LTS/EOL status i kompatibilnost, pa zaključaj i testiraj izabranu podržanu verziju.","Zadrži EOL verziju čim package-lock postoji, jer lock obezbeđuje bezbednosne zakrpe runtime-a."],"steps":["Proveri zvanični raspored podrške na datum odluke; status se menja vremenom.","Zatim proveri zahtevane Node verzije dependency-ja i produkcioni tok na odabranoj patch verziji."],"remember":"Biraj po aktuelnoj podršci i kompatibilnosti, ne po parnosti broja.","wrong":["Pre-release status nije isto što i dugoročna produkciona podrška.","Dokumentovan je novi release ciklus od Node 27, pa stara prečica može zastareti.","Lock zaključava pakete, ali ne održava EOL Node runtime."]},"express01":{"title":"Redosled JSON middleware-a","prompt":"POST ruta je registrovana pre app.use(express.json()). Zahtev ima validan JSON i odgovarajući Content-Type, ali ruta nema prethodni parser. Zašto req.body nije parsiran u toj ruti?","why":"Middleware se izvršava po redosledu registracije za odgovarajući zahtev. Parser mora da bude pre handlera koji koristi njegov rezultat.","pitfall":"Dodavanje parsera na kraju fajla ne znači da je retroaktivno obradio prethodnu rutu.","options":["Svaka POST ruta automatski dobija parsiran body bez parsera.","Parser treba postaviti tek posle res.json da ne uspori rutu.","express.json treba registrovati pre ruta kojima je parsirani body potreban.","Problem rešava samo preimenovanje req u request."],"steps":["Prati tok zahteva od prve odgovarajuće middleware funkcije do rute.","Parser postavi dovoljno rano i proveri Content-Type, ograničenje veličine i validaciju podataka."],"remember":"Middleware koji priprema podatke mora prethoditi onome koji ih koristi.","wrong":["Express ne parsira svako telo automatski samo zato što je metod POST.","Posle slanja odgovora je kasno da parser pripremi ulaz za tu rutu.","Ime parametra ne menja redosled i funkciju middleware-a."]},"express02":{"title":"Middleware mora da nastavi ili završi zahtev","prompt":"Middleware pozove logRequest(req), ali ne pošalje odgovor i nikad ne pozove next(). Šta se dešava u običnom Express middleware lancu?","why":"Express čeka da middleware završi odgovor ili eksplicitno prepusti kontrolu. Sam povratak iz funkcije ne pokreće sledeći middleware.","pitfall":"Ne pozivaj next posle konačnog odgovora bez jasnog razloga; možeš pokrenuti pokušaj drugog odgovora.","options":["Zahtev ostaje nezavršen; za nastavak treba next(), a za kraj poslati/završiti odgovor.","Express automatski pozove sledeću funkciju čim middleware vrati undefined.","Sledeći middleware radi paralelno sa prethodnim bez next().","Express automatski pretvori logRequest rezultat u JSON odgovor."],"steps":["Razdvoji povratak JavaScript funkcije od završetka HTTP odgovora.","Izaberi jedan tok: next za nastavak, next(error) za grešku ili završetak odgovora."],"remember":"Middleware: nastavi tok ili završi odgovor.","wrong":["Povratak undefined ne zamenjuje next.","Express ne paralelizuje middleware lanac na taj način.","Povratna vrednost obične middleware funkcije ne postaje automatski HTTP telo."]},"express03":{"title":"params, query i body","prompt":"Za rutu GET /users/:id stiže /users/42?tab=activity. Koje mapiranje je ispravno, uz uobičajen query parser?","why":"Parametar putanje id dolazi iz req.params, a query string tab iz req.query. To su ulazni podaci zahteva i treba proveriti očekivani format i dozvoljene vrednosti.","pitfall":"Query parser može proizvesti različite oblike; ne pretpostavljaj da je svaki req.query.x uvek pouzdan string.","options":["req.body.id je 42, a req.params.tab je activity.","req.query.id je 42, a req.body.tab je activity.","Oba podatka su automatski u req.params.","req.params.id je \\"42\\", a req.query.tab potiče iz query stringa."],"steps":["Deo :id pripada šablonu putanje, pa ga tražiš među params.","Deo posle ? je query string; validiraj ga pre korišćenja u filteru ili upitu."],"remember":"Putanja → params; deo posle ? → query; payload → body.","wrong":["Ova putanja ne smešta id u body niti query polje u params.","Broj u putanji nije query parametar, a tab nije request body.","req.params prati deklarisane parametre rute, ne sva polja URL-a."]},"express04":{"title":"JSON parser nije validator","prompt":"Posle express.json() želiš da sačuvaš req.body kao korisnički profil. Koji je najispravniji sledeći korak?","why":"Parser proverava da payload može da se protumači kao JSON prema podešavanju parsera. To ne dokazuje poslovni oblik, dozvoljena polja ili pravo korisnika da menja određeni profil.","pitfall":"Ne prihvataj privilegovana polja poput role ili ownerId samo zato što ih je klijent poslao.","options":["Sačuvati ceo req.body: parsiranje već garantuje validan profil.","Validirati dozvoljena polja i vrednosti i odvojeno proveriti identitet i pravo izmene.","Dodati TypeScript cast Profile i odmah upisati objekat.","Proveriti samo da req.body nije null, jer je ostatak već siguran."],"steps":["Prvo potvrdi strukturu i poslovna ograničenja runtime validatorom ili eksplicitnim proverama.","Zatim proveri server-side autorizaciju za ciljni resurs i sastavi objekat samo od dozvoljenih polja."],"remember":"Parsiranje čita oblik zapisa; validacija i autorizacija proveravaju ugovor i pravo.","wrong":["Sintaksno validan JSON može sadržati pogrešne tipove ili neodobrena polja.","TypeScript cast ne proverava vrednosti pristigle preko mreže.","Nenull vrednost još ne dokazuje tipove, dozvoljene vrednosti ili pravo pristupa."]},"express05":{"title":"Express 5 i async greške","prompt":"U Express 5 ruta je async i radi const user = await loadUser(); zatim šalje odgovor. loadUser odbaci Promise. Šta Express 5 radi sa tim neuspehom?","why":"Async handler vraća Promise, a Express 5 automatski prosleđuje njegovo odbijanje u error middleware tok. To važi za Promise koji handler zaista vraća ili čeka.","pitfall":"Odvojeni, nečekani Promise ili greška u timer callback-u nisu automatski deo tog vraćenog Promise-a. Za legacy Express 4 proveri wrapper/catch(next) obrazac.","options":["Uvek šalje 200 sa praznim user objektom.","Automatski ponavlja zahtev sve dok baza ne odgovori.","Prosleđuje odbijanje u error middleware tok, slično next(error).","Zahteva da svaki await bude u svom zasebnom setTimeout-u."],"steps":["Async funkcija vraća Promise koji Express 5 može da prati.","Kad await baci zbog odbijanja, Promise handlera se odbija i Express prelazi u error tok."],"remember":"Express 5 prati vraćeni Promise; odvojeni async posao traži svoj tok greške.","wrong":["Odbijanje nije uspešan rezultat i ne postaje automatski 200.","Express ne uvodi automatski retry samo zbog async handlera.","Timer nije potreban i može otežati povezivanje greške sa handlerom."]},"express06":{"title":"Kako Express prepoznaje error middleware?","prompt":"Koji potpis funkcije treba koristiti za centralni Express error middleware registrovan posle ruta?","why":"Express prepoznaje poseban error tok po četiri argumenta: err, req, res, next. Čak i ako next nije iskorišćen u jednostavnom primeru, potpis error middleware-a treba sačuvati.","pitfall":"Dodavanje error middleware-a pre ruta može propustiti greške iz kasnijeg dela lanca.","options":["(err, req, res, next) => { ... }","(req, res, next) => { ... }","(err, res, next) => { ... }","() => Promise.reject(new Error())"],"steps":["Običan middleware ima req, res, next; error middleware počinje dodatnim err argumentom.","Registruj ga posle ruta čije greške želiš da obradi i pošalji tačno jedan smislen odgovor."],"remember":"Centralni Express error middleware ima četiri argumenta.","wrong":["To je potpis običnog middleware-a, ne posebnog error handler-a.","Tri argumenta ne prate Express ugovor za error middleware.","Samo pravljenje novog odbijenog Promise-a ne definiše handler za postojeće greške."]},"express07":{"title":"Bezbedan odgovor za neočekivanu grešku","prompt":"Napiši error middleware posle ruta za neočekivanu serversku grešku. req.id je već serverom generisan request ID, a logger je dostupan. Sačuvaj dijagnostiku u server log-u, ali klijentu ne vraćaj stack trace ili interne poruke. Obradi i headersSent slučaj.","why":"Klijentu treba stabilan neuspeh i referenca za podršku, a detalji pripadaju kontrolisanom server log-u. Kad su header-i već poslati, drugi JSON odgovor nije moguć; prepusti grešku sledećem handler-u.","pitfall":"U stvarnom log sistemu rediguj tajne i lične podatke; samo premeštanje svih podataka u log nije zaštita.","solution":"app.use((err, req, res, next) => {\\n  logger.error({ requestId: req.id, error: err });\\n  if (res.headersSent) return next(err);\\n  return res.status(500).json({\\n    error: 'Internal server error',\\n    requestId: req.id,\\n  });\\n});","checks":["Handler je posle ruta i ima err, req, res, next potpis.","headersSent grana prosleđuje next(err) i ne pokušava ponovo da šalje odgovor.","Neočekivana greška vraća 500 sa generičkom porukom i request ID-jem.","Interni detalji se ne šalju klijentu; kontrolisani log beleži request ID i u headersSent grani."],"steps":["Prvo utvrdi da li još možeš bezbedno da formiraš novi HTTP odgovor.","Zatim razdvoji javni ugovor greške od interne dijagnostike i obezbedi samo jedan odgovor."],"remember":"Javna poruka treba da bude stabilna; interna dijagnostika treba da bude kontrolisana.","wrong":[]},"express08":{"title":"CORS nije kontrola pristupa API-ju","prompt":"API dozvoljava CORS samo za tvoj frontend origin. Da li to samo po sebi sprečava napadača da pozove privatnu rutu iz curl-a?","why":"Ne. CORS middleware postavlja response header-e koje browser koristi da kontroliše da li JavaScript sme da čita odgovor. Nebrowser klijenti ne koriste tu zaštitu kao autentikaciju ili autorizaciju.","pitfall":"Browser može poslati neke zahteve čak i kada JavaScript ne sme da pročita odgovor; CORS ne zamenjuje ni CSRF razmatranje kod cookie autentikacije.","options":["Da, server odbija svaki paket koji nije poslao navedeni browser.","Da, Origin header je neoboriv dokaz identiteta korisnika.","Da, ako je express.json uključen pre CORS-a.","Ne; privatna ruta i dalje mora da proveri identitet i pravo pristupa."],"steps":["Razdvoji browser pravilo čitanja odgovora od server odluke da izvrši operaciju.","Za svaki privatni resurs proveri autentikaciju i autorizaciju; CORS podesi kao odvojen browser mehanizam."],"remember":"CORS je browser pravilo za čitanje odgovora, ne identitet i dozvola.","wrong":["CORS ne predstavlja mrežni zid koji verifikuje izvor svakog paketa.","Origin nije zamena za provereni korisnički identitet i može se postaviti u drugim klijentima.","JSON parser ne menja CORS u sistem autorizacije."]},"express09":{"title":"Zašto error handler nije uhvatio 404?","prompt":"Nijedna ruta nije odgovorila na /missing, a centralni error middleware se nije pokrenuo. Kako uobičajeno definišeš JSON 404 odgovor?","why":"Nepostojanje odgovarajuće rute samo po sebi nije bačena Express greška. Običan middleware na kraju ruta može da pošalje 404 odgovor pre završnog error handler-a.","pitfall":"Catch-all 404 postavljen pre API ruta može zaustaviti sve zahteve pre nego što stignu do pravih handler-a.","options":["Error middleware mora automatski da dobije svaku nepostojeću rutu; Express je pokvaren.","Dodati običan završni middleware posle ruta koji šalje res.status(404).json(...).","Svaku nepoznatu putanju treba preusmeriti na 200 da browser ne bi prijavio grešku.","Premestiti centralni error middleware pre svih ruta."],"steps":["Ako lanac nije poslao odgovor i nema error-a, potreban je normalan fallback odgovor.","Postavi 404 fallback iza dostupnih ruta, pa zaseban error handler za stvarne greške."],"remember":"404 fallback i error middleware imaju različite uloge.","wrong":["Nepronađena ruta ne mora da proizvodi error objekat.","200 bi tvrdio da je traženi API resurs uspešno obrađen i narušio ugovor.","Promena redosleda error handler-a ne pravi uobičajeni 404 fallback."]},"express10":{"title":"API pre izlaska u produkciju","prompt":"Mali Express API koristi cookie login, prima korisničke podatke i ima rutu za izmenu naloga. Navedi prioritetne kontrole pre produkcije i objasni šta svaka štiti. Ne traži se lista svih mogućih bezbednosnih mera.","why":"Produkcioni API treba više slojeva: zaštićen transport, proveru ulaza, bezbedne sesije, autentikaciju i autorizaciju resursa. Kontrole treba povezati sa stvarnim tokom i rizikom, a ne samo instalirati middleware.","pitfall":"Helmet, CORS ili uspešan frontend test pojedinačno ne dokazuju da je API bezbedan. Cookie postavke i CSRF zaštita zavise od login i cross-site modela.","solution":"Prioritet je tok izmene naloga:\\n1. HTTPS i izričito podešavanje pouzdanog proxy-ja kada deployment to zahteva.\\n2. Runtime validacija i dozvoljena polja, primereni limiti tela zahteva i odbijanje nepodržanog ulaza.\\n3. Serverska provera autentifikovane sesije i prava izmene ciljnog naloga.\\n4. Cookie podešavanja prilagođena okruženju (Secure, HttpOnly, promišljen SameSite) i CSRF zaštita za promene koje koriste cookie autentikaciju.\\n5. Zaštita login-a od brute force napada, podržani dependency-ji i primereni sigurnosni header-i.\\n6. Bez curenja tajni ili stack trace-a, redigovani korisni logovi i provera i dozvoljenih i zabranjenih zahteva.\\nTačna podešavanja i dodatne mere zavise od arhitekture i modela pretnji.","checks":["Povezuje HTTPS i cookie/sesiju sa konkretnim deployment-om.","Razdvaja validaciju, autentikaciju i autorizaciju ciljnog naloga.","Razmatra CSRF u cookie toku i ograničenja ulaza/zloupotrebe login-a.","Predlaže proveru dozvoljenih i zabranjenih slučajeva, bez tvrdnje da jedan middleware rešava sve."],"steps":["Počni od radnje koja menja nalog: ko je korisnik, koji nalog sme da menja i koja polja su dozvoljena.","Zatim zaštiti transport i sesiju, ograniči zloupotrebu i proveri da greške i odbijeni zahtevi rade prema ugovoru."],"remember":"Svaka kontrola treba da štiti konkretan deo toka i da ima proverljiv rezultat.","wrong":[]},"sass01":{"title":"Sass i SCSS: dve sintakse, isti alat","prompt":"U CV-ju piše SCSS/Sass. Koje objašnjenje te razlike je tačno?","options":["SCSS se izvršava u browseru, a Sass na serveru pri svakom zahtevu.","SCSS je jedna od Sass sintaksi; .scss koristi vitičaste zagrade, a .sass uvlačenje.","SCSS ima promenljive, a .sass sintaksa ih nema.","SCSS je React biblioteka koja zamenjuje CSS."],"why":"Sass je preprocesorski jezik sa SCSS i indented sintaksom. Obe služe pisanju stilova koji se prevode u CSS; izbor sintakse ne menja ulogu browsera.","pitfall":"Ne izvodi mogućnosti jezika samo iz ekstenzije: .scss i .sass podržavaju iste osnovne Sass mogućnosti.","steps":["U .scss fajlu blokove pišeš sa { } i deklaracije završavaš sa ;, pa kod liči na CSS.","U .sass fajlu strukturu određuje uvlačenje. U oba slučaja browser tipično dobija generisan CSS."],"remember":"SCSS je sintaksa Sass-a, a ne poseban runtime.","wrong":["Obe sintakse se prevode u CSS; ova podela browser/server ne opisuje njihovu razliku.","Obe sintakse podržavaju Sass promenljive i ostale jezičke mogućnosti.","SCSS možeš koristiti sa Reactom ili bez njega; nije React biblioteka."]},"sass02":{"title":"Sass promenljiva ili CSS custom property?","prompt":"Korisnik menja temu u otvorenoj aplikaciji, bez novog build-a. Koji pristup odgovara promeni boja u browseru?","options":["Promena vrednosti $surface u već kompajliranom Sass izvornom fajlu.","Samo dodavanje !default uz $surface garantuje promenu u otvorenom browseru.","CSS custom properties, npr. --surface, sa vrednostima zavisnim od data-theme atributa.","Svaki React render automatski ponovo pokreće Sass kompajler."],"why":"Sass promenljive koriste se tokom kompilacije. CSS custom properties ostaju u CSS-u i browser određuje njihove vrednosti kroz cascade i stilove teme.","pitfall":"Sass može organizovati tokene, ali runtime promena teme zahteva CSS ili JavaScript koji deluje na prikaz.","steps":["Posle build-a, $surface više nije promenljiva koju browser može da promeni.","Ako .card koristi background: var(--surface), promena teme može da promeni --surface i browser ponovo izračunava stil."],"remember":"$token je build-time; --token može biti runtime.","wrong":["Promena izvora bez nove kompilacije i isporuke ne menja već učitan CSS.","!default upravlja početnom Sass konfiguracijom, a ne browser stanjem.","React render ne podrazumeva pokretanje build alata ili Sass kompajlera."]},"sass03":{"title":"Promena Sass promenljive ne menja raniji CSS","prompt":"Koje vrednosti width dobija generisani CSS za .first i .second?","code":"$space: 8px;\\n.first { width: $space; }\\n$space: 16px;\\n.second { width: $space; }","options":[".first: 8px; .second: 16px.","Obe dobijaju 16px, jer poslednja deklaracija menja sva ranija korišćenja.","Obe dobijaju 8px, jer se Sass promenljiva nikad ne menja.","Build mora da padne jer je promenljiva deklarisana dva puta."],"why":"Sass vrednuje promenljive po toku kompilacije. Kasnija dodela utiče na naredna korišćenja, dok je ranija deklaracija već dobila svoju vrednost.","pitfall":"Ne prenosi automatski CSS cascade ili Less lazy-evaluation mentalni model na Sass promenljive.","steps":["Kada se obrađuje .first, $space je 8px i ta vrednost ulazi u njegov CSS.","Dodela 16px se dešava pre .second, pa drugi selektor dobija 16px."],"remember":"Sass dodela ne prepravlja već obrađen CSS.","wrong":["Sass promenljive nisu retroaktivne: prethodna deklaracija zadržava vrednost koju je imala tokom obrade.","Promenljivoj može da se dodeli nova vrednost; ona nije nepromenljiva konstanta.","Ponovna dodela u ovom primeru je dozvoljena."]},"sass04":{"title":"@use: namespace i jedna kopija modula","prompt":"Više Sass fajlova koristi isti tokens modul. Šta važi za @use u jednoj kompilaciji?","options":["Svaki @use mora da duplira sav CSS modula u izlazu.","Promenljive iz modula postaju automatski globalne u svim fajlovima projekta.","@use učitava CSS preko mreže pri svakom React renderu.","Modul se učitava jednom; članovi se koriste kroz namespace i svaki fajl eksplicitno učitava ono što koristi."],"why":"Sass module system ograničava dostupnost članova na fajl koji ih učitava. Namespace pokazuje poreklo imena, a učitavanje istog modula jednom smanjuje slučajno dupliranje njegovog CSS-a.","pitfall":"„Jednom” važi u okviru iste kompilacije. Dve nezavisne Sass kompilacije i dalje mogu da proizvedu iste stilove.","steps":["Posle @use \\"tokens\\", član možeš da referenciraš kao tokens.$spacing.","Drugi fajl mora imati svoj @use ako želi taj član; već učitan modul se u istoj kompilaciji ponovo ne emituje kao nova kopija."],"remember":"@use daje eksplicitan namespace i jedno učitavanje po kompilaciji.","wrong":["Upravo @use izbegava ponovno učitavanje istog modula u okviru kompilacije.","Članovi učitani kroz @use nisu automatski vidljivi drugim fajlovima.","@use je Sass build instrukcija, a ne React ili browser mrežni API."]},"sass05":{"title":"@forward i javni API stil biblioteke","prompt":"Praviš index.scss koji korisnicima izlaže tokene i mixin-e iz više fajlova. Koja uloga @forward je tačna?","options":["Automatski stavlja sve prosleđene promenljive u lokalni scope bez @use.","Prosleđuje javne članove potrošačima modula; za lokalno korišćenje tih članova u istom fajlu potreban je i @use.","Radi samo sa CSS selektorima i nikad sa promenljivama ili mixin-ima.","Služi za slanje Sass koda iz browsera na server."],"why":"@forward pravi zajedničku ulaznu tačku biblioteke. To što nešto izlaže njenim korisnicima ne znači da te članove ujedno uvodi u lokalni scope fajla koji prosleđuje.","pitfall":"Ako istom modulu trebaju @forward i @use, planiraj redosled zbog početne konfiguracije; obično @forward ide prvi.","steps":["index.scss može da prosledi module, pa potrošač koristi jednu @use putanju.","Ako sam index.scss računa vrednost koristeći prosleđeni token, on mora i da učita modul pomoću @use."],"remember":"@forward izlaže API; @use ga učitava za korišćenje.","wrong":["Prosleđivanje javnih članova nije isto što i njihovo lokalno učitavanje.","@forward podržava promenljive, funkcije i mixin-e, ne samo stilove.","Ovo je organizacija modula tokom Sass kompilacije, bez browser/server prenosa."]},"sass06":{"title":"Mixin ili funkcija?","prompt":"Želiš ponovljivo izračunavanje razmaka koje se koristi unutar vrednosti padding. Koji pristup odgovara tome?","options":["@include može direktno da se koristi kao broj unutar padding vrednosti.","Sass @function mora da vrati ceo CSS selektor, nikad jednu vrednost.","Sass @function koja vraća vrednost preko @return; mixin je pogodniji za uključivanje blokova deklaracija.","Mixin i funkcija su isto i obe se pozivaju isključivo sa @include."],"why":"Funkcija proizvodi vrednost za izraz, npr. spacing(3). Mixin se uključuje u kontekst stilova i koristi se za skup deklaracija ili drugih Sass instrukcija.","pitfall":"Ne pravi komplikovanu funkciju kada je obično množenje ili CSS calc() dovoljno jasno.","code":"@function spacing($step) { @return $step * 4px; }\\n.card { padding: spacing(3); }","steps":["spacing(3) vraća 12px, pa deklaracija postaje padding: 12px.","Za više ponovljenih deklaracija, poput border i background zajedno, možeš definisati mixin i uključiti ga sa @include."],"remember":"Function vraća vrednost; mixin uključuje stilove.","wrong":["@include je at-rule i nije numerički rezultat za padding izraz.","Sass funkcije upravo vraćaju Sass vrednosti preko @return.","Funkcija se poziva kao funkcija u izrazu; @include uključuje mixin."]},"sass07":{"title":"!default i konfiguracija biblioteke","prompt":"Biblioteka sadrži $radius: 8px !default. Koji je smisao ove oznake u konfigurabilnom modulu?","options":["Sprečava da se $radius ikad konfiguriše iz drugog fajla.","Primorava browser da promeni vrednost kada korisnik promeni temu.","Postavlja početnu vrednost samo ako promenljiva nije definisana ili je null, pa potrošač može da je konfiguriše pri prvom @use učitavanju.","Daje selektorima modula istu prednost kao CSS !important."],"why":"!default ostavlja prostor za konfiguraciju pre nego što modul generiše stilove. Primer je @use \\"library\\" with ($radius: 12px).","pitfall":"Konfiguracija se daje pri prvom učitavanju modula; pokušaj ponovne konfiguracije već učitanog modula nije način za promenu teme u runtime-u.","steps":["Biblioteka određuje razumnu podrazumevanu vrednost, a potrošač pri učitavanju može dati 12px.","Sve CSS deklaracije koje modul izgradi sa tim tokenom računaju se tokom kompilacije, bez posebne browser promenljive."],"remember":"!default je ugovor za build konfiguraciju, ne CSS prioritet.","wrong":["Oznaka omogućava konfiguraciju; ne zaključava token protiv nje.","Sass konfiguracija se ne izvršava automatski kada se browser tema promeni.","!default se odnosi na dodelu Sass promenljive i nema efekat CSS !important."]},"sass08":{"title":"Zašto math.div umesto oslanjanja na /?","prompt":"Kako jasno napišeš Sass račun koji deli 24px sa 3, bez oslanjanja na zastarelo tumačenje slash operatora?","options":["24px // 3, jer Sass koristi JavaScript sintaksu celobrojnog deljenja.","@use \\"sass:math\\"; pa math.div(24px, 3), što daje 8px.","Treba izbrisati jedinicu px iz svakog izraza da bi račun bio dozvoljen.","Svaki / u CSS-u treba zameniti pozivom math.div, uključujući slash separatore."],"why":"math.div eksplicitno izražava Sass deljenje. Znak / se koristi i u CSS sintaksi kao separator, pa slepa zamena svakog slash-a može promeniti značenje deklaracije.","pitfall":"CSS calc(24px / 3) je drugi, validan izraz za CSS račun; pravilo o Sass slash deprecaciji ne znači da sav CSS / nestaje.","steps":["Učitaj ugrađeni math modul, pa math.div(24px, 3) računa vrednost sa jedinicom px.","Odvojeno prepoznaj slash separatore, npr. u grid-area ili color sintaksi; oni ne znače Sass deljenje."],"remember":"math.div razjašnjava Sass račun; / može biti CSS separator.","wrong":["// započinje komentar u SCSS-u; nije operator za deljenje.","Deljenje dužine brojem može legitimno da vrati dužinu, ovde 8px.","Slash separator u CSS gramatici nije isto što i aritmetičko deljenje."]},"sass09":{"title":"Šta raditi sa Sass @import u 2026?","prompt":"Održavaš Dart Sass 1.x projekat sa deprecation upozorenjima za Sass @import. Koji je razuman pristup?","options":["Tvrditi da je svaki CSS @import zabranjen u browseru, pa obrisati sve takve deklaracije.","Samo sakriti sva upozorenja i računati da migracija nikad neće biti potrebna.","Automatski zameniti tekst @import sa @use bez provere dostupnosti promenljivih i mixin-a.","Planirati migraciju na @use/@forward, proveriti namespace i generisani CSS; deprecation ne znači da je funkcionalnost već uklonjena."],"why":"Sass @import je deprecated od Dart Sass 1.80.0. Module system ima drugačija pravila vidljivosti i učitavanja, pa migracija zahteva proveru ponašanja.","pitfall":"Razlikuj Sass uvoz koji kompajler obrađuje od običnog CSS @import. Ne tvrdi da je planirano uklanjanje već sprovedeno.","steps":["Pronađi direktne i posredne uvoze i utvrdi odakle dolaze članovi koje fajl koristi.","Posle migracije proveri build i rezultujući CSS: namespace, redosled i broj emitovanih stilova mogu biti bitni."],"remember":"Deprecated označava pravac migracije, a ne automatski današnju neispravnost.","wrong":["Sass deprecation nije zabrana standardnog CSS @import u browseru.","Sakrivanje upozorenja ne uklanja zavisnost od zastarelog mehanizma.","@use ne uvodi globalno sve članove; prosta tekstualna zamena često nije dovoljna."]},"sass10":{"title":"Pojednostavi selektor i sačuvaj fokus","prompt":"SCSS dugmeta je vezan za tačan raspored roditelja. Predloži plitku strukturu sa klasom .action-button i hover/focus-visible stanjima, bez !important. Objasni zašto promena HTML rasporeda tada manje utiče na komponentu.","code":".dashboard {\\n  .panel {\\n    .toolbar {\\n      .action-button { &:hover { background: #0056ad; } }\\n    }\\n  }\\n}","why":"Nesting se pretvara u kombinovane CSS selektore. Ako ponašanje dugmeta vežeš za nekoliko roditelja, povećavaš vezanost za DOM i otežavaš prepisivanje stilova.","pitfall":"Plitak selektor nije dozvola za globalna generička imena. Koristi smislen naziv komponente i proveri postojeći cascade.","steps":["Prvo razdvoji stil rasporeda toolbar-a od stila dugmeta, jer su to različite odgovornosti.","Za stanja koristi & uz samostalnu klasu, pa dobijene .action-button:hover i .action-button:focus-visible deklaracije proveri u CSS-u."],"remember":"Nesting organizuje izvor; generisani selektor određuje stvarnu vezanost.","checks":["Dugme ima samostalnu .action-button klasu bez obaveznih dashboard/panel roditelja.","Hover i focus-visible stanja imaju jasno definisan izgled; fokus nije uklonjen.","Odgovor objašnjava promenu specificity/vezanosti i predlaže proveru postojećih stilova."],"solution":".toolbar { display: flex; gap: 0.5rem; }\\n.action-button {\\n  background: #0066cc;\\n  color: white;\\n  &:hover { background: #0056ad; }\\n  &:focus-visible { outline: 3px solid #0066cc; outline-offset: 3px; }\\n}\\n\\n/* Dugme sada može biti premesteno u drugi kontejner. Pregledaj computed styles i postojeće override-e jer niža specificity može promeniti pobedničku deklaraciju. */","wrong":[]},"less01":{"title":"Šta browser dobija iz Less build-a?","prompt":"Kako je razumno isporučiti Less stilove u produkcionoj aplikaciji?","options":["Isporučiti .less kao običan CSS i očekivati da svi browseri nativno razumeju sve Less mogućnosti.","Kompajlirati .less u CSS tokom build-a i isporučiti CSS; Less.js browser kompilacija postoji, ali nije obavezna.","Pokrenuti Less kompilaciju na svakom korisničkom kliku.","Less je moguće kompajlirati isključivo na PHP serveru."],"why":"Less proširuje CSS i alat ga prevodi u CSS. Zvanična dokumentacija za produkciju preporučuje prekompajliranje radi performansi i pouzdanosti.","pitfall":"Nije tačno da browser kompilacija ne postoji: Less.js je može omogućiti. To se razlikuje od nativne podrške CSS parsera za Less.","steps":["Build alat obrađuje Less promenljive i mixin-e i pravi izlazni CSS.","Browser tada učitava taj CSS bez potrebe da za svaki prikaz ponavlja Less kompilaciju."],"remember":"Za produkciju isporuči CSS; preprocesor ostaje deo build-a.","wrong":["Nativni CSS parser ne postaje Less parser samo zato što dobije drugačiju ekstenziju fajla.","Kompilacija stilova po kliku nije potrebna za već pripremljen CSS.","Less.js podržava Node.js i druge integracije; PHP nije jedino okruženje."]},"less02":{"title":"Less lazy evaluation i lokalni scope","prompt":"Koju width vrednost dobija .tile u ovom Less primeru?","code":".tile {\\n  width: @size;\\n  @size: 12px;\\n}\\n@size: 24px;","options":["24px: uvek pobeđuje poslednja deklaracija u celom fajlu, bez obzira na scope.","Build mora da padne zato što je @size korišćen pre lokalne deklaracije.","12px: lokalna @size vrednost može biti pronađena i kada je deklarisana posle korišćenja.","width ostaje doslovno @size u generisanom CSS-u."],"why":"Less dozvoljava lazy evaluation promenljivih. U ovom primeru lokalni scope sadrži @size: 12px, pa se ta vrednost koristi za .tile.","pitfall":"Lazy evaluation ne ukida scope. Ne primenjuj napamet Sass pravilo dodeljivanja po redosledu na Less.","steps":["Prvo utvrdi scope u kojem se @size traži: width je unutar .tile bloka.","U istom bloku postoji lokalna deklaracija 12px, pa spoljna deklaracija 24px ne određuje ovaj rezultat."],"remember":"U Less-u proveri scope i lazy evaluation, ne samo redosled linija.","wrong":["Spoljna deklaracija ne prepisuje automatski lokalnu promenljivu.","Less promenljiva u ovakvom primeru ne mora da bude napisana pre upotrebe.","Preprocesorska promenljiva se razrešava pri kompilaciji i ne ostaje kao @size CSS vrednost."]},"less03":{"title":"Less mixin sa guard uslovom","prompt":"Šta se dešava kada ovaj mixin pozoveš sa .pad(3)?","code":".pad(@n) when (@n > 0) { padding: (@n * 4px); }\\n.card { .pad(3); }","options":["Guard odgovara argumentu, pa .card dobija padding: 12px tokom kompilacije.","Guard se proverava u browseru kada se promeni veličina prozora.","Padding postaje 3px jer guard odbacuje množenje.","when može da proverava samo korisnikov login status."],"why":"Guard je uslov za izbor Less mixin definicije na osnovu argumenta. Broj 3 zadovoljava @n > 0, a množenje daje 12px.","pitfall":"Guard nije runtime if za React state ili korisnička prava; on se vrednuje dok Less pravi CSS.","steps":["Poziv .pad(3) vezuje @n za 3 i uslov 3 > 0 je tačan.","Telo mixin-a se uključuje u .card; izračunat padding je 3 × 4px = 12px."],"remember":"Less guard bira stilove pri kompilaciji na osnovu argumenata.","wrong":["Ovaj guard nema veze sa resize događajem niti se ponovo proverava u browseru.","Uslov ne briše izraz; telo mixin-a množi 3 i 4px.","Guard testira Less izraze; ne daje autorizaciju korisnicima aplikacije."]},"less04":{"title":"Less 4 i deljenje sa zagradama","prompt":"Koristiš Less 4 sa math: \\"parens-division\\". Koja deklaracija se kompajlira u width: 4px?","options":["width: 12px / 3; bez zagrada, jer se svako deljenje uvek odmah računa.","width: 12px // 3;","width: divide(12px / 3); jer Less zahteva ugrađenu funkciju divide.","width: (12px / 3);"],"why":"U ovom math režimu / van zagrada ostaje separator umesto da se tretira kao deljenje. Zagrade jasno označavaju račun koji Less treba da izvrši.","pitfall":"Navedi verziju i math režim kada tumačiš stari Less primer. Drugačija konfiguracija može promeniti evaluaciju aritmetike.","steps":["Prepoznaj da je pitanje vezano baš za parens-division, podrazumevani režim u Less-u 4.","Izraz u zagradama računa 12px ÷ 3, pa dobijaš 4px; sirov slash izlaz ne mora biti validna vrednost za konkretnu CSS osobinu."],"remember":"U parens-division režimu stavi Less deljenje u zagrade.","wrong":["Bez zagrada / se u zadatom režimu ne izračunava kao deljenje.","// je komentar, a ne Less operator za celobrojno deljenje.","Za ovaj račun nije potrebna izmišljena divide funkcija; dovoljan je izraz u zagradama."]},"less05":{"title":"&:hover nije potomak sa :hover","prompt":"Koje selektore generiše dati Less kod?","code":".button {\\n  &:hover { opacity: 0.8; }\\n  .icon { width: 16px; }\\n}","options":[".button :hover i .button.icon.",".button:hover i .button .icon.",".button:hover i samo globalni .icon.","Samo jedan selektor: .button:hover.icon."],"why":"& predstavlja roditeljski selektor i omogućava dodavanje stanja istom elementu. Obična ugnježdena .icon pravi descendant selektor.","pitfall":"Razmak u selektoru menja značenje: .button:hover je hover dugmeta, a .button :hover može da označava hover potomka.","steps":["Zameni & sa .button: dobijaš .button:hover, bez razmaka.","Za .icon nema & pa se generiše kombinacija sa razmakom: .button .icon."],"remember":"& menja način spajanja selektora; prati dobijeni CSS.","wrong":["Prvi selektor pogrešno ubacuje potomka, a drugi pogrešno traži obe klase na istom elementu.","Ugnježdena .icon ostaje vezana za roditelja; ne postaje automatski globalni selektor.","Dva odvojena pravila ne spajaju se sama u jedan kombinovani selektor."]},"less06":{"title":"Dodaj runtime temu postojećem Less projektu","prompt":"Postojeći Less token @surface: #fff daje belu pozadinu kartice. Predloži mali primer light/dark teme koja se menja preko data-theme atributa, bez pokretanja Less kompajlera u browseru. Objasni šta ostaje posao build-a.","code":"@surface: #fff;\\n.card { background: @surface; }","why":"Less build može ostati postojeći način pripreme CSS-a, a promenljive koje treba menjati tokom rada mogu biti CSS custom properties. Browser zatim bira njihove vrednosti kroz stilove za aktivnu temu.","pitfall":"Promena Less @surface vrednosti u izvornom fajlu ne menja već isporučen CSS. Proveri i kontrast teksta u obe teme, ne samo boju pozadine.","steps":["Prebaci promenljive boje na --surface i --text u CSS pravilima za podrazumevanu i dark temu.","Komponenta koristi var(...), a aplikacija menja data-theme na odgovarajućem pretku. Less se i dalje izvršava pri build-u."],"remember":"Preprocesor priprema CSS, a CSS custom properties omogućavaju promenu teme.","checks":["Postoje light i dark vrednosti za custom properties i .card ih koristi sa var().","Promena data-theme utiče na karticu bez novog Less build-a u browseru.","Objašnjena je build/runtime granica i predložena provera boja/kontrasta u obe teme."],"solution":":root { --surface: #fff; --text: #171717; }\\n[data-theme=\\"dark\\"] { --surface: #171717; --text: #f5f5f5; }\\n.card { background: var(--surface); color: var(--text); }\\n\\n/* Ova pravila mogu biti deo .less izvora koji se prekompajlira. React ili drugi UI kod postavlja data-theme=\\"dark\\" na html element, dok browser izračunava custom properties i stilove. */","wrong":[]},"ui01":{"title":"Jedna MUI tema umesto mnogo izuzetaka","prompt":"U admin aplikaciji deset ekrana ima različite nijanse plave i razmake. Kako uvodiš doslednu MUI temu sa najmanje ponavljanja?","why":"ThemeProvider prosleđuje temu komponentama ispod njega. Zajednički palette, spacing, typography i component overrides daju jedno mesto za pravila dizajna.","steps":["Popiši ponovljene vrednosti i pretvori ih u semantičke tokene, npr. primary i text.secondary.","Primeni temu na odgovarajući deo stabla; lokalni sx koristi za stvarne izuzetke i proveri light/dark kontrast."],"remember":"Tema opisuje zajednička pravila; izuzetak ostaje lokalni.","pitfall":"Nasumični globalni !important stilovi mogu popraviti jedan ekran i pokvariti drugi.","checks":["Postavlja createTheme i ThemeProvider iznad potrošača.","Razdvaja zajedničke tokene i component overrides od lokalnih izuzetaka.","Proverava kontrast, focus i obe teme na reprezentativnim komponentama."],"solution":"Napravi createTheme sa palette, typography, spacing i components.MuiButton.defaultProps/styleOverrides. Omotaj aplikaciju sa ThemeProvider. Za pojedinačnu karticu koristi sx sa semantičkim vrednostima, npr. color: \\"text.secondary\\". Pregledaj forme, dijaloge i disabled/focus stanja u obe teme.","wrong":[]},"ui02":{"title":"Broj u sx nije uvek broj piksela","prompt":"Uz podrazumevani MUI spacing od 8 px, šta znači sx={{ margin: 2 }}?","why":"MUI spacing svojstva u sx koriste theme.spacing. Sa podrazumevanom skalom, 2 znači 2 × 8 px = 16 px.","steps":["margin je svojstvo povezano sa spacing sistemom.","Tek tema prevodi broj 2 u konkretnu CSS vrednost; drugačija spacing funkcija može promeniti rezultat."],"remember":"U sx prvo proveri da li broj prolazi kroz temu.","pitfall":"Nemoj pretpostaviti da svako numeričko sx svojstvo koristi istu skalu.","options":["Margin od 2 px.","Margin od 16 px.","Margin od 2%.","Dve CSS klase bez margine."],"wrong":["To je očekivanje običnog numeričkog React style.margin, ne ovog theme-aware sx pravila.","Broj sam ne označava procenat; procenat bi bio eksplicitan string.","sx pravi stil; broj ovde učestvuje u spacing proračunu."]},"ui03":{"title":"Autocomplete ima dva različita stanja","prompt":"Korisnik kuca naziv grada, ali još nije odabrao grad iz predloga. Koja MUI Autocomplete stanja treba razlikovati?","why":"value predstavlja izabranu vrednost, a inputValue tekst u polju. Kucanje teksta nije isto što i potvrda izabrane opcije.","steps":["Upis \\"Beo\\" može promeniti inputValue dok izabrani value ostaje null.","onInputChange i onChange zato poveži sa odvojenim odgovornostima."],"remember":"Tekst pretrage i izabrani entitet nisu isti podatak.","pitfall":"Backend-u nemoj slati grad samo zato što se sličan tekst nalazi u inputu.","options":["Samo value, jer svaki karakter automatski bira entitet.","Samo open, jer on čuva i tekst i grad.","value/onChange za izbor i inputValue/onInputChange za tekst.","Opcije treba direktno upisivati u DOM inputa."],"wrong":["Tekst može biti nepotpun i ne mora odgovarati nijednoj dozvoljenoj opciji.","open opisuje otvorenost liste, ne izabrani podatak.","Time zaobilaziš kontrolisani React/MUI ugovor i otežavaš sinhronizaciju."]},"ui04":{"title":"Isti ID, druga referenca u Autocomplete-u","prompt":"Opcije su objekti {id, name}. Posle refetch-a stižu nove instance istih objekata. Bez getOptionValue i freeSolo, kako stabilno porediš opciju sa value?","why":"Podrazumevano poređenje objekata zavisi od reference. isOptionEqualToValue može da poredi stabilan ID kada refetch napravi nove objekte.","code":"isOptionEqualToValue={(option, value) => option.id === value.id}","steps":["Dve različite objektne instance mogu imati isti ID, a ipak biti nejednake po referenci.","Poređenje stabilnog ID-ja opisuje domenski identitet umesto trenutne instance."],"remember":"Identitet entiteta je njegov stabilni ključ, ne adresa objekta.","pitfall":"Ime nije nužno jedinstveno; za poređenje izaberi stvarni identifikator.","options":["Uporedi objekte operatorom === i očekuj poređenje svih polja.","Uporedi samo indeks u novoj listi.","Uvek čuvaj izabranu opciju kao JSON string u inputValue.","Koristi isOptionEqualToValue sa poređenjem ID-jeva."],"wrong":["=== za objekte poredi reference, ne strukturu.","Redosled može da se promeni pri sortiranju ili novom odgovoru.","To meša tekst pretrage sa izabranim entitetom i ne rešava ugovor opcija."]},"ui05":{"title":"Bootstrap mobile-first kolone","prompt":"U standardnom Bootstrap 5.3 grid-u element ima className=\\"col-12 col-md-6\\". Kako se ponaša ispod i od md breakpoint-a, bez dodatnih override-a?","why":"col-12 zauzima svih 12 kolona, a md pravilo od podrazumevanih 768 px menja širinu na 6 od 12. Pravila važe od breakpoint-a naviše dok ih drugo pravilo ne promeni.","steps":["Na manjoj širini ostaje osnovno col-12 pravilo.","Od md širine min-width pravilo daje polovinu širine reda."],"remember":"Mobile-first klasa postavlja osnovu; breakpoint je nadograđuje.","pitfall":"md ne znači prepoznavanje određenog uređaja, već širinu viewport-a.","options":["Puna širina ispod md, polovina reda od md naviše.","Polovina ispod md, puna širina iznad.","Uvek tačno 6 px širine.","Samo CSS Grid browsera, bez Bootstrap stilova."],"wrong":["Time je smer mobile-first pravila obrnut.","Broj označava deo 12-kolonskog grida, ne piksele.","Ove klase dobijaju značenje iz Bootstrap stylesheet-a; nisu ugrađene HTML komande."]},"ui06":{"title":"Ko upravlja DOM-om Bootstrap dijaloga?","prompt":"React state zatvara dijalog, a Bootstrap JS plugin istovremeno menja isti DOM. Šta je razuman smer integracije?","why":"Dva mehanizma koja nezavisno menjaju isti element mogu izgubiti sinhronizaciju. Bootstrap CSS možeš koristiti uz React, a interaktivno ponašanje uskladiti kroz React komponentu ili jasno izolovanu integraciju.","steps":["Odredi jedan izvor istine za open/closed stanje i životni ciklus.","Za dijalog proveri i fokus, Escape i cleanup, a ne samo vizuelno zatvaranje."],"remember":"Jedan vlasnik ponašanja po UI elementu.","pitfall":"Dodavanje još jednog click listener-a ne popravlja nejasno vlasništvo stanja.","options":["Bootstrap CSS je zato zabranjen u React-u.","Uskladi ponašanje kroz React integraciju sa jasnim vlasnikom stanja.","Koristi više direktnih DOM izmena dok test ne prođe.","Sakrij dijalog opacity: 0 i zanemari fokus."],"wrong":["Problem je sukob DOM ponašanja, a ne samo korišćenje CSS klasa.","Time pojačavaš sukob između modela stanja i stvarnog DOM-a.","Nevidljivi interaktivni elementi mogu ostati dostupni tastaturom i pokvariti pristupačnost."]},"ui07":{"title":"Figma CSS je početak razgovora","prompt":"Dobio si Figma desktop frame i generisani CSS za formu. Kako od toga praviš održiv responsive React ekran?","why":"Inspect podaci opisuju dizajn, ali sami ne određuju ponašanje pri drugoj širini, stvarnom tekstu i greškama. Implementacija zahteva odluke o layout-u, komponentama i stanjima.","steps":["Izvuci tokene, odnose između elemenata i postojeće komponente pre kopiranja pojedinačnih koordinata.","Razjasni mobile, loading, empty, error i focus stanja; proveri stvaran duži tekst i tastaturu."],"remember":"Iz dizajna prenosi nameru i pravila, pa proveri ponašanje.","pitfall":"Mnogo absolute koordinata može pogoditi jedan screenshot, a pokvariti duži prevod.","checks":["Razlikuje inspect reference od gotove arhitekture.","Predlaže grid/flex prema odnosima i koristi zajedničke tokene/komponente.","Navodi konkretna nedostajuća stanja i proveru responsive/a11y ponašanja."],"solution":"Uskladi spacing/typography/color tokene sa postojećom temom. Formu podeli na smislene komponente i koristi flow/grid/flex prema strukturi. Sa dizajnerom razjasni sužavanje kolona, tekst greške i disabled/loading stanja. Uporedi ekran na više širina, sa dužim prevodom, tastaturom i stvarnim podacima.","wrong":[]},"ui08":{"title":"Design token ili kopirana nijansa?","prompt":"Figma koristi semantičku promenljivu text/secondary sa različitim light/dark vrednostima. Šta najviše čuva tu nameru u aplikaciji?","why":"Semantički token povezuje ulogu boje sa odgovarajućom temom. Kopiranje samo trenutnog hex-a gubi vezu sa režimom i otežava buduće izmene.","steps":["Uloga teksta ostaje ista kada se tema promeni.","Aplikacioni token mapiraj na dogovorene vrednosti i proveri kontrast u oba režima."],"remember":"Token označava svrhu, a tema bira vrednost.","pitfall":"Isti naziv tokena ne garantuje da su vrednosti i kontrast usklađeni; proveri ih.","options":["Svuda kopiraj samo light hex vrednost.","Čuvaj screenshot teksta kao sliku.","Prepoznaj temu po URL nazivu Figma fajla.","Mapiraj ga na semantički token aplikacione teme."],"wrong":["Tako tamni režim ne dobija svoj dogovoreni prikaz.","Time gubiš stvaran tekst, skaliranje i pristupačnost.","Naziv fajla nije ugovor između design tokena i aplikacionog režima."]},"viz01":{"title":"Chart.js instanca ima životni ciklus","prompt":"React komponenta direktno kreira new Chart(canvas, config) u Effect-u. Šta cleanup treba da uradi pre ponovnog korišćenja canvas-a?","why":"destroy() oslobađa reference i listenere Chart.js instance. React uklanjanje canvas-a samo po sebi nije eksplicitno uništavanje te instance.","steps":["Sačuvaj instancu koju je konkretni Effect napravio.","Vrati cleanup koji poziva njeno destroy(); dev Strict Mode dodatno otkriva neispravno uparene setup/cleanup pozive."],"remember":"Imperativni resurs koji napraviš moraš i osloboditi.","pitfall":"Ovo pitanje je o direktnom Chart.js API-ju; React wrapper može već upravljati tim životnim ciklusom.","options":["Pozove destroy() na kreiranoj instanci.","Samo isprazni niz labels u React state-u.","Svaki put napravi novu instancu preko stare bez cleanup-a.","Pozove chart.update() umesto destroy()."],"wrong":["Time ne uklanjaš Chart.js listenere i reference instance.","Canvas ne treba ponovo koristiti za novu instancu pre uništavanja prethodne.","update ponovo crta postojeću instancu; nije operacija oslobađanja."]},"viz02":{"title":"Promenjeni podaci i ponovno crtanje","prompt":"U direktnoj Chart.js instanci promenio si njene dataset vrednosti i želiš prikaz novih podataka bez animacije. Šta radiš?","why":"Chart.js instanca mora dobiti update da obradi promenu i ponovo iscrta grafikon. Režim none isključuje animaciju tog ažuriranja.","steps":["Menjaš podatke instance, ne proizvoljno React state objekat.","Pozovi chart.update(\\"none\\") da instanca obradi skale, podatke i prikaz bez ove animacije."],"remember":"Podaci instance + update = novi prikaz.","pitfall":"Pravila imperativne instance ne dozvoljavaju direktnu mutaciju React state-a.","options":["Samo promenim običan niz i očekujem da biblioteka automatski primeti sve izmene.","Pozovem chart.update(\\"none\\").","Obrišem canvas i izgubim instancu.","Pozovem React setState sa istom mutiranom referencom."],"wrong":["Direktna instanca dobija eksplicitan update; običan niz nije signal za ponovno crtanje.","Za ovu izmenu nije potrebno uništiti i ponovo praviti ceo grafikon.","Pitanje je o Chart.js instanci; ista mutirana React referenca nije pouzdan signal za render."]},"viz03":{"title":"Grafikon koji možeš i da pročitaš","prompt":"Dashboard prikazuje prihod po mesecima samo kao canvas grafikon. Kako omogućavaš razumevanje i korisniku screen reader-a?","why":"Obojeni pikseli canvas-a sami ne prenose podatke screen reader-u. Daj grafikonu pristupačno ime i smislen tekstualni prikaz podataka.","steps":["Sažmi šta grafikon pokazuje bez oslanjanja samo na boju.","Ponudi tabelu ili drugi tekstualni ekvivalent stvarnih vrednosti; uskladi ga sa filtrima grafikona."],"remember":"Vizuelni trend treba da ima i razumljiv tekstualni put.","pitfall":"aria-label=\\"Grafikon\\" imenuje oblik, ali ne objašnjava podatke i njihov smisao.","checks":["Daje canvas-u odgovarajuću ulogu i ime.","Obezbeđuje pristup istim podacima kao tekstu/tabeli.","Razlikuje serije i bez same boje i proverava stvarne vrednosti/filtere."],"solution":"Canvas-u daj role=\\"img\\" i opisno ime poput \\"Mesečni prihod za izabranu godinu\\". Ispod dodaj kratak sažetak trenda i pristupačnu tabelu mesec/prihod. Ažuriraj grafikon i tabelu iz istog izvora podataka. Koristi jasne oznake serija i proveri prikaz tastaturom i screen reader-om.","wrong":[]},"viz04":{"title":"Google Maps učitaj kada je potreban","prompt":"Mapa postoji samo na jednoj ruti. Koji pristup omogućava traženje potrebnih Google Maps biblioteka po potrebi, uz zvanični loader?","why":"Dynamic library import omogućava da importLibrary zatraži određenu biblioteku kada je koristiš. Deljeni loader sprečava nekontrolisano ponavljanje učitavanja skripte.","steps":["Razdvoji učitavanje API-ja od pravljenja konkretne mape.","Sačekaj potrebnu biblioteku i prikaži loading/error stanje pre pristupa njenim klasama."],"remember":"Asinhrono učitavanje API-ja je deo životnog ciklusa UI-ja.","pitfall":"Ne pretpostavljaj da google.maps postoji odmah pri prvom renderu.","options":["Dodaj novi script tag tokom svakog rendera.","Koristi klase pre završetka učitavanja i sakrij grešku.","Premesti browser ključ u VITE_ promenljivu i mapa više ne traži mrežu.","Deljeni loader i await google.maps.importLibrary za potrebne biblioteke."],"wrong":["Render može biti ponovljen mnogo puta, pa bi učitavanje bilo duplirano i teško za kontrolu.","Sakrivena greška ne čini API spremnim; treba sačekati Promise i prikazati neuspeh.","Lokacija build konfiguracije ne ugrađuje Google Maps servis i biblioteke u tvoju aplikaciju."]},"viz05":{"title":"Browser Maps ključ i ograničenja","prompt":"Maps JavaScript API u browseru koristi API ključ koji se može videti u mrežnom zahtevu. Koja zaštita odgovara toj vrsti ključa?","why":"Browser ključ nije serverska tajna. Za taj slučaj podesi Websites/application ograničenja i dozvoljene API-je u Google Cloud-u, uz praćenje upotrebe.","steps":["Pretpostavi da korisnik može videti sve što njegov browser šalje.","Ograniči gde i za koje Maps API-je ključ sme da se koristi; serverske kredencijale drži na serveru."],"remember":"Za browser ključ kontroliši upotrebu; ne računaj na skrivanje.","pitfall":"VITE_ prefiks i minifikacija ne pretvaraju javno korišćen ključ u server secret.","options":["Ograničenja dozvoljenih sajtova i API-ja uz praćenje upotrebe.","Samo minifikuj bundle.","Stavi ga u VITE_MAPS_KEY i smatraj ga tajnim.","Koristi isti neograničeni ključ za browser i serverske API-je."],"wrong":["Minifikacija nije kontrola pristupa ključu koji browser koristi.","Vite klijentske env vrednosti mogu završiti u isporučenom kodu.","Time širiš dozvoljenu upotrebu i vezuješ različite bezbednosne granice za isti ključ."]},"viz06":{"title":"Migracija sa starog Maps Marker-a","prompt":"Za novu integraciju biraš AdvancedMarkerElement umesto deprecated google.maps.Marker. Koji dodatni zahtevi su bitni prema migracionom vodiču?","why":"Advanced markers zahtevaju marker biblioteku i map ID uz novu klasu. Zamena samo naziva konstruktora zato nije cela migracija.","steps":["Proveri učitavanje marker biblioteke u postojećem loader-u.","Prosledi odgovarajući mapId i prilagodi kreiranje markera novom API-ju."],"remember":"Migracija obuhvata preduslove i ponašanje, ne samo rename.","pitfall":"Deprecated ne znači da je stari Marker već uklonjen iz svih podržanih integracija.","options":["Promeni samo boju starog Marker-a.","Učitaj marker biblioteku i podesi map ID uz novu klasu.","Isključi API ključ da napredni marker radi lokalno.","Zaključi da je ceo Maps JavaScript API ukinut."],"wrong":["Stil stare instance ne prelazi na novi API.","Nova marker klasa ne ukida preduslove Maps JavaScript API-ja.","Deprecation se odnosi na staru Marker klasu, ne na ceo servis."]},"li11":{"title":"Redux state i izvedeni podaci","prompt":"Store čuva listu zadataka i filter. Da li filteredTasks mora biti još jedna lista u store-u?","why":"Filtrirana lista može da se izvede iz zadataka i filtera. Čuvanje više kopija iste informacije uvodi dodatna pravila sinhronizacije.","steps":["Odredi minimalne izvorne podatke: tasks i filter.","Selector izračunava prikaz; memoizaciju dodaj kada postoji korist za računanje ili stabilnost reference."],"remember":"Čuvaj izvorne podatke, izvedi ono što iz njih sledi.","pitfall":"Memoizovani selector ne rešava pogrešnu mutaciju izvornih podataka.","options":["Da, svaka moguća kombinacija filtera mora biti zaseban state.","Ne, jer filtriranje pripada isključivo reducer-u.","Ne; izvedi je selector-om iz liste i filtera.","Da, jer selector sme samo da pročita jedno polje."],"wrong":["Tako stvaraš mnogo kopija koje lako postanu neusaglašene.","Selector je prikladno mesto za čitanje i izvođenje podataka bez promene state-a.","Selector može kombinovati i transformisati više ulaznih podataka."]},"li12":{"title":"Zašto catch ne hvata rejected thunk?","prompt":"Thunk napravljen sa createAsyncThunk završi rejected akcijom. Kako u komponenti koristiš try/catch nad njegovim rezultatom?","why":"Dispatch tog async thunk-a normalno vraća Promise sa završnom fulfilled/rejected akcijom. unwrap vraća uspešan payload ili baca grešku/rejected payload u pozivajući tok.","code":"try {\\n  const saved = await dispatch(saveItem(values)).unwrap();\\n} catch (error) {\\n  // Show the save error.\\n}","steps":["Razlikuj rejected Redux akciju od odbijenog Promise-a koji pozivalac čeka.","unwrap prevodi rezultat akcije u očekivani success/throw ugovor za ovaj poziv."],"remember":"Za payload ili throw koristi unwrap, a ne pretpostavku o dispatch Promise-u.","pitfall":"Ovo je ugovor createAsyncThunk-a; ne generalizuj na svaki proizvoljni thunk.","options":["Dovoljno je await dispatch(thunk(args)); rejected akcija uvek baca.","Catch radi samo ako isključim Redux middleware.","Payload greške treba čitati iz DOM-a toast poruke.","Sa await dispatch(thunk(args)).unwrap() unutar try/catch."],"wrong":["Promise standardnog createAsyncThunk dispatch-a se razrešava završnom akcijom.","Middleware omogućava izvršavanje thunk-a; njegovo uklanjanje ne rešava rezultat.","DOM poruka je prikaz, a ne pouzdan programski rezultat zahteva."]},"li13":{"title":"Axios: odgovor sa greškom ili bez odgovora?","prompt":"Uz podrazumevani validateStatus, server pošalje HTTP 422 odgovor. Gde AxiosError obično nosi HTTP odgovor?","why":"Za odgovor sa neuspešnim statusom AxiosError ima response sa statusom i podacima. Kada zahtev nema primljen odgovor, situacija je drugačija od serverovog 422.","steps":["Prvo proveri da li je greška Axios greška.","Ako postoji error.response, obradi status i očekivani format validacionih grešaka; inače razlikuj mrežu/otkazivanje i pripremu zahteva."],"remember":"Neuspešan HTTP odgovor nije isto što i odsustvo odgovora.","pitfall":"Prilagođeni validateStatus može promeniti da li status izaziva rejection.","options":["U error.response, npr. response.status i response.data.","Samo u error.request; response nikad ne postoji za 422.","Axios uvek smatra sve HTTP statuse uspešnim.","Uvek kao automatski popunjena Formik polja."],"wrong":["error.request bez response se tipično koristi da objasni nedobijen odgovor, što nije ovaj slučaj.","Podrazumevani validateStatus ne prihvata svaki status; ugovor možeš prilagoditi.","Axios ne poznaje tvoju formu; mapiranje server grešaka radi aplikacija."]},"li14":{"title":"Otkazivanje Axios pretrage","prompt":"Za svaku promenu query-ja šalješ Axios zahtev. Napiši Effect koji otkazuje prethodni zahtev, ignoriše kasni rezultat i ne prikazuje otkazivanje kao mrežnu grešku.","why":"AbortController prekida podržani transport, dok lokalna aktivnost štiti UI od rezultata čiji Effect više ne važi. Otkazivanje nije ista stvar kao neuspeh servera.","steps":["Napravi kontroler za taj Effect i prosledi signal Axios-u.","U cleanup-u označi rezultat nevažećim i pozovi abort; obradi otkazivanje odvojeno od stvarnih grešaka."],"remember":"Zaštiti i zahtev i pravo njegovog rezultata da menja UI.","pitfall":"Otkazan browser zahtev ne garantuje da server nije već izvršio upis.","checks":["Prosleđuje novi signal po Effect-u i abort u cleanup-u.","Kasni odgovor ne menja UI posle promene query-ja/unmount-a.","Otkazivanje odvaja od greške i čisti prethodni error kada počne nova pretraga."],"solution":"useEffect(() => {\\n  const controller = new AbortController();\\n  let active = true;\\n  setError(null);\\n  axios.get(\\"/api/items\\", { params: { q: query }, signal: controller.signal })\\n    .then(({ data }) => { if (active) setItems(data); })\\n    .catch(error => {\\n      if (active && !axios.isCancel(error)) setError(\\"Pretraga nije uspela\\");\\n    });\\n  return () => { active = false; controller.abort(); };\\n}, [query]);","wrong":[]},"li15":{"title":"Formik i podaci učitani posle mount-a","prompt":"Forma se mount-uje prazna, zatim stiže drugi initialValues objekat. Šta je tačno za enableReinitialize?","why":"Podrazumevano je false. Kada je true, promena initialValues po dubokom poređenju može resetovati formu, pa moraš planirati ponašanje za nesnimljene izmene.","steps":["Razlikuj prvobitno inicijalizovanje forme od kasnijeg resetovanja.","Pri refetch-u ili promeni zapisa dogovori da li novi podaci smeju da zamene dirty unos."],"remember":"Reinitialize može resetovati korisnički unos, pa je to UX odluka.","pitfall":"Nemoj uključiti flag samo da bi podaci postali vidljivi, bez razmatranja dirty forme.","options":["Uvek je true i nikad ne utiče na unos korisnika.","Promena reference uvek resetuje formu čak i uz false.","True omogućava reset pri promenjenim initialValues; proveri nesnimljene izmene.","To automatski čuva svaku izmenu na serveru."],"wrong":["Podrazumevana vrednost je false, a reset može promeniti trenutne vrednosti.","Formik ovaj slučaj ne svodi na bezuslovni reset pri svakoj novoj referenci.","Flag upravlja reinicijalizacijom lokalne forme, ne persistence API-jem."]},"li16":{"title":"Saga call i fork","prompt":"Generator koristi yield call(loadProfile). U čemu je ključna razlika u odnosu na yield fork(loadProfile)?","why":"call čeka završetak pozvane funkcije/Promise-a u toj sagi. fork pokreće zadatak bez takvog čekanja i vraća Task, koji možeš kasnije join/cancel.","steps":["Kod call naredna linija čeka rezultat tog poziva.","Kod fork saga nastavlja, pa zavisnosti od rezultata moraš posebno koordinisati."],"remember":"call čeka rezultat; fork daje zadatak koji se izvršava uporedo.","pitfall":"Uporedo ovde ne znači da CPU-intenzivan JavaScript automatski prelazi na drugi thread.","options":["fork automatski izvršava JavaScript na posebnom CPU thread-u.","call menja Redux state, a fork čita state.","Između njih nema razlike pri asinhronom radu.","call čeka, a fork vraća Task bez čekanja njegovog završetka."],"wrong":["Saga raspoređuje asinhrone zadatke, ne stvara implicitno Worker thread.","To nisu reducer/select ugovori ovih efekata.","Razlika u čekanju menja redosled i koordinaciju narednih koraka."]},"qa09":{"title":"Poništavanje već deljenog commit-a","prompt":"Običan commit na deljenoj main grani uvodi regresiju. Želiš novi commit koji poništava njegovu promenu, uz očuvanje deljene istorije. Koju Git operaciju biraš?","why":"git revert pravi novi commit sa obrnutom promenom. Time istorija pokazuje i originalnu izmenu i njeno poništavanje.","steps":["Proveri tačan commit i da li poništavanje utiče na kasnije zavisne izmene.","Primeni revert, razreši eventualne konflikte i proveri stvarno ponašanje pre slanja."],"remember":"Za novu poništavajuću promenu u deljenoj istoriji koristi revert.","pitfall":"Revert merge commit-a ima dodatnu mainline semantiku; ovaj primer je običan commit.","options":["git revert <commit>.","git reset --hard i obavezan force push svim saradnicima.","git stash trajno poništava već objavljen commit.","Samo obriši lokalni branch."],"wrong":["To prepisuje deljenu istoriju, suprotno zadatom cilju.","Stash prvenstveno sklanja lokalne izmene, ne pravi traženi poništavajući commit.","Brisanje branch reference ne poništava sadržaj main grane."]},"qa10":{"title":"Od nejasnog tiketa do proverljivog dogovora","prompt":"Jira/Trello tiket kaže \\"srediti pretragu\\", a odluke su rasute u Slack porukama. Kao lead, šta razjasniš i gde ostavljaš dogovor za razvoj i review?","why":"Proverljivi acceptance criteria povezuju nameru sa konkretnim ponašanjem. Jedno dostupno mesto za odluku smanjuje različita tumačenja u razvoju, review-u i proveri.","steps":["Pretvori nejasan zahtev u primere: šta korisnik unosi, koji rezultat dobija i šta vidi kada nema podataka ili API ne uspe.","Uz tiket poveži dogovor, dizajn i API ugovor; naknadne odluke zabeleži tamo, a ne samo u razgovoru."],"remember":"Dobar dogovor može da se pročita i proveri bez autora razgovora.","pitfall":"Acceptance criteria opisuju konkretan zadatak; nisu isto što i opšti timski Definition of Done.","checks":["Razjašnjava ponašanje i granične slučajeve sa zainteresovanim stranama.","Piše merljive kriterijume i povezuje dizajn/API dogovor.","Obezbeđuje trag odluka i proveru kriterijuma u PR-u; ne zahteva konkretan alat kao jedino rešenje."],"solution":"Primer kriterijuma: prazan upit vraća početnu listu; novi upit prikazuje loading; poslednji upit određuje rezultat; empty i error imaju različit prikaz; pretraga radi tastaturom na mobilnom i desktopu. Dogovori kada se zahtev šalje i šta radi pagination. Zapiši kriterijume u tiket, poveži specifikaciju/Confluence i traži da PR pokaže kako su provereni. Važne promene iz Slack-a vrati u trajni dogovor.","wrong":[]}}`),r=[{title:`Tipovi opisuju vrednosti`,tag:`Osnove`,explain:`TypeScript je JavaScript sa statičkim proverama. Kod se i dalje izvršava po JavaScript pravilima. Tip number opisuje dozvoljene vrednosti; ne pretvara string u broj i ne proverava API odgovor.`,mental:`Anotacija je ugovor za proveru koda. Konverzija i validacija su radnje u izvršavanju.`,code:`let count = 3; // inference: number
count = 4;     // u redu
// count = "4"; // type greška

function double(value: number): number {
  return value * 2;
}`,trap:`Ne anotiraj sve mehanički. Piši tip tamo gde razjašnjava ugovor ili gde inference nije dovoljan.`},{title:`Objekti, opcioni podaci i unions`,tag:`Modeli`,explain:`Objekat opisuješ svojstvima. Znak ? dozvoljava izostavljanje svojstva. Union A | B znači da vrednost može biti A ili B; dok ne znaš koja je, radi samo operacije koje su bezbedne za obe.`,mental:`Ako podatak može nedostajati, tip treba to iskreno da kaže.`,code:`type User = {
  id: string;
  name?: string;
};
function displayName(user: User) {
  return user.name ?? "Bez imena";
}
type Id = string | number;`,trap:`any uklanja zaštitu; non-null ! nije provera. Prvo razumi unknown, undefined i strictNullChecks.`},{title:`Narrowing i stanja koja imaju smisla`,tag:`Bezbedne grane`,explain:`JavaScript provera poput typeof ili provere status literala sužava tip u toj grani. Kod složenog stanja, zasebne union grane bolje opisuju dozvoljene kombinacije od mnogo opcionih polja.`,mental:`Proveri u kojoj si grani, pa koristi samo podatke koji toj grani pripadaju.`,code:`type Result<T> =
  | { status: "success"; data: T }
  | { status: "error"; message: string };

function read(result: Result<string>) {
  if (result.status === "success") {
    return result.data.toUpperCase();
  }
  return result.message;
}`,trap:`typeof null je "object". Za nepoznate objekte proveri null, svojstva i njihove tipove.`},{title:`Generics: sačuvaj vezu između tipova`,tag:`Ponovna upotreba`,explain:`T je mesto za konkretan tip koji pozivalac prosledi ili kompajler izvede. Za razliku od any, generik čuva vezu između ulaza i izlaza. Constraint opisuje minimum koji implementaciji treba.`,mental:`T nije bilo šta bez pravila; to je isti nepoznati tip koji pratiš kroz ugovor.`,code:`function first<T>(items: T[]): T | undefined {
  return items[0];
}
const n = first([10, 20]); // number | undefined

function get<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}`,trap:`Ne obećavaj T ako vraćaš samo deo strukture. Prazan niz i odsutni ključ zahtevaju promišljen ugovor.`},{title:`Sastavi tipove bez akrobatike`,tag:`Advanced osnove`,explain:`Pick bira polja, Omit ih izostavlja, Partial ih čini opcionim, a Readonly ograničava izmene kroz taj tip. keyof i T[K] povezuju ključeve i vrednosti. Mapped/conditional types služe ponovljivim transformacijama.`,mental:`Prvo napiši dobar domenski model. Tek onda iz njega izvodi tipove koje zaista koristiš.`,code:`type Profile = { id: string; name: string; phone: string };
type Update = Partial<Pick<Profile, "name" | "phone">>;

const modes = ["view", "edit"] as const;
type Mode = typeof modes[number];

const config = { pageSize: 20 } satisfies { pageSize: number };`,trap:`as const i readonly ne zamrzavaju objekat u runtime-u. satisfies nije validator.`},{title:`TypeScript koji koristiš u Reactu`,tag:`Praktični React`,explain:`Kreni od props ugovora i callback parametara. useState često izvodi tip sam, ali početni null ili prazan niz mogu tražiti eksplicitan generik. Za DOM događaje koristi konkretan element.`,mental:`Komponenta je funkcija sa jasno opisanim ulazom; tipovi treba da učine pogrešnu upotrebu vidljivom.`,code:`type Props = { onSave: (name: string) => void };

function NameForm({ onSave }: Props) {
  const [name, setName] = useState("");
  return <input value={name}
    onChange={e => setName(e.currentTarget.value)} />;
}
// Za početni null: useState<User | null>(null)`,trap:`input.value ostaje string i za numerički input. ReactNode je širi od samo JSX elementa.`},{title:`Granice sistema: runtime i alatke`,tag:`API i provere`,explain:`JSON izvan programa nije pod zaštitom tvog statičkog modela. Proveri HTTP, parsiraj podatke i validiraj šemu na granici. Build, type-check i testovi imaju različite zadatke.`,mental:`Tip opisuje obećanje; validator proverava da li spoljašnja vrednost obećanje ispunjava.`,code:`const UserSchema = z.object({
  id: z.string(),
  name: z.string()
});
type User = z.infer<typeof UserSchema>;

const raw: unknown = await response.json();
const user = UserSchema.parse(raw);`,trap:`Primeri pretpostavljaju odgovarajuće importe i okruženje. parse može baciti grešku koju UI/servis mora smisleno obraditi.`},{title:`Primeni na svoj admin ekran`,tag:`Završni zadatak`,explain:`Poveži modele, tipizovan servis, stanja zahteva i komponente. Napravi jednu malu vertikalnu funkcionalnost: lista korisnika sa filterom, loading/error/empty stanjima i tipizovanim props.`,mental:`Cilj je da sam napišeš i objasniš mali tok, pa ga izmeniš kada se zahtev promeni.`,code:`type User = { id: string; name: string };
type Column<T> = {
  id: string;
  title: string;
  render: (row: T) => React.ReactNode;
};
// Dodaj servis, validaciju, otkazivanje i UI stanja.`,trap:`Radi u editoru uz tsc --noEmit. Ovaj trening prikazuje i čuva odgovore, ali ne izvršava TS niti ocenjuje otvoreni kod automatski.`}],i={version:1,topics:t,questions:n,lessons:r};export{i as default,r as lessons,n as questions,t as topics,e as version};